# «аргументы» — обычный срез (argv, длина == argc): «аргументы[1]» при запуске
# без пользовательских аргументов (длина == 1) выходит за границы и прерывается
# рантайм-проверкой среза (SIGABRT), а не читает мусор за argv. (Раньше argv был
# указателем-с-длиной и литеральный индекс под охранником ловился статически;
# теперь единая абстракция среза — проверка границ в рантайме, как у любого среза.)
cat > выход_за_границы_аргументов.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    printf(аргументы[1]);
    вернуть 0
}
KONDA

"$BIN" выход_за_границы_аргументов.конда >"$TMP/выход_за_границы_аргументов.log" 2>&1 || {
    cat "$TMP/выход_за_границы_аргументов.log" >&2
    fail "доступ к аргументы[1] должен транспилироваться (проверка границ — в рантайме)"
}
./вывод/выход_за_границы_аргументов.elf >/dev/null 2>"$TMP/выход_за_границы_аргументов.err" && rc=0 || rc=$?
assert_eq "134" "$rc" "аргументы[1] без пользовательских аргументов прерывает программу (SIGABRT)"
grep -q "выход за границы среза" "$TMP/выход_за_границы_аргументов.err" || {
    cat "$TMP/выход_за_границы_аргументов.err" >&2
    fail "рантайм-сообщение о выходе за границы среза argv должно быть понятным"
}

