# Модель A: перевод строки завершает оператор, «;» не нужна. Проверяем все
# конструкции без «;»: объявления, присваивания, циклы, если/иначе, вернуть,
# продолжение строки по висящему оператору и многострочный вызов в скобках.
cat > без_точки_с_запятой.конда <<'KONDA'
#содержит <stdio.h>

целое32 удвоить(целое32 х)
{
    целое32 р = х + х
    вернуть р
}

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 сумма = 0
    для целое32 и = 1; и <= 5; и = и + 1 {
        сумма = сумма + и
    }
    целое32 длинное = сумма +
                      удвоить(10)
    printf("%d %d\n",
           сумма,
           длинное)
    если (длина(аргументы) > 1)
    {
        printf("много\n")
    }
    иначе
    {
        printf("мало\n")
    }
    вернуть 0
}
KONDA

"$BIN" без_точки_с_запятой.конда >"$TMP/без_точки_с_запятой.log" 2>&1 || {
    cat "$TMP/без_точки_с_запятой.log" >&2
    fail "код без «;» (модель A) должен транспилироваться"
}
assert_eq "15 35" "$(./вывод/без_точки_с_запятой.elf | head -n1)" "без «;»: вывод и продолжение строки"
assert_eq "мало"  "$(./вывод/без_точки_с_запятой.elf   | tail -n1)" "без «;»: ветка иначе"
assert_eq "много" "$(./вывод/без_точки_с_запятой.elf x | tail -n1)" "без «;»: ветка если"

