# «возможно<Структура*>» — nullable-указатель на структуру (и «внешний тип»).
# Раньше «возможно<…>» принимал только примитивы (парсер: «ожидался тип»);
# нужно для интеропа с C (opaque-хендлы toytoolkit: возможно<display*> = нуль,
# потом присвоение из фабрики). Доступ к полю — только под охранником.
cat > возможно_структура.конда <<'KONDA'
#содержит <stdio.h>

структура Узел { целое32 знач }

возможно<Узел*> найти(целое32 к)
{
    вернуть нуль
}

целое32 точка_входа(срез<символ*> аргументы)
{
    возможно<Узел*> п = найти(5)
    если (п != нуль) {
        printf("%d\n", п.знач)
    } иначе {
        printf("не найдено\n")
    }
    вернуть 0
}
KONDA
"$BIN" возможно_структура.конда >"$TMP/возможно_структура.log" 2>&1 || {
    cat "$TMP/возможно_структура.log" >&2
    fail "возможно<Структура*> с охранником должно компилироваться"
}
assert_eq "не найдено" "$(./вывод/возможно_структура.elf)" "возможно<Структура*>: null-путь под охранником"

# Негатив: доступ к полю nullable-структуры БЕЗ охранника — нулевое разыменование.
cat > возможно_структура_без_охраны.конда <<'KONDA'
#содержит <stdio.h>

структура Узел { целое32 знач }

целое32 читать(возможно<Узел*> у)
{
    вернуть у.знач
}

целое32 точка_входа(срез<символ*> аргументы)
{
    вернуть 0
}
KONDA
if "$BIN" возможно_структура_без_охраны.конда >"$TMP/возможно_структура_без_охраны.log" 2>&1; then
    fail "доступ к полю nullable-структуры без охранника должен быть ошибкой"
fi
grep -q "может быть нулевым" "$TMP/возможно_структура_без_охраны.log" || {
    cat "$TMP/возможно_структура_без_охраны.log" >&2
    fail "ошибка должна указывать на возможный нуль при доступе к полю"
}

# ─── Null-safety: результат вызова «возможно<T*>» отслеживается (§43 Ф5) ──────
# Раньше nullable-возврат функции не считался возможным нулём: «п = найти()»
# делал «п» ненулевым, и дереф без охранника (или после реассайна под охранником)
# был null-дереф. Класс TOCTOU: проверили не-нуль, затем переприсвоили nullable,
# затем разыменовали. Фикс: сигнатура несёт «возврат_возможно», выражение_может_
# быть_нуль учитывает вызов.

# 1) Объявление из nullable-вызова, дереф БЕЗ охранника — ошибка.
cat > нуллабл_вызов_объявление.конда <<'KONDA'
#содержит <stdio.h>
структура Узел { целое32 знач }
возможно<Узел*> найти(целое32 к) { вернуть нуль }
целое32 точка_входа(срез<символ*> аргументы)
{
    возможно<Узел*> п = найти(5)
    printf("%d\n", п.знач)
    вернуть 0
}
KONDA
if "$BIN" нуллабл_вызов_объявление.конда >"$TMP/нуллабл_объявл.log" 2>&1; then
    fail "дереф nullable-результата вызова без охранника должен быть ошибкой"
fi
grep -q "может быть нулевым" "$TMP/нуллабл_объявл.log" || {
    cat "$TMP/нуллабл_объявл.log" >&2
    fail "ошибка должна указывать на возможный нуль результата вызова"
}

# 2) Прямой дереф результата вызова «найти(5).знач» — ошибка (временный не сузить).
cat > нуллабл_вызов_прямой.конда <<'KONDA'
#содержит <stdio.h>
структура Узел { целое32 знач }
возможно<Узел*> найти(целое32 к) { вернуть нуль }
целое32 точка_входа(срез<символ*> аргументы)
{
    printf("%d\n", найти(5).знач)
    вернуть 0
}
KONDA
if "$BIN" нуллабл_вызов_прямой.конда >"$TMP/нуллабл_прямой.log" 2>&1; then
    fail "прямой дереф результата nullable-вызова должен быть ошибкой"
fi
grep -q "может быть" "$TMP/нуллабл_прямой.log" || { cat "$TMP/нуллабл_прямой.log" >&2; fail "нуллабл_вызов_прямой: ожидалась конкретная диагностика, не любая ошибка"; }

# 3) TOCTOU: под охранником «если (п != нуль)» реассайн в nullable-вызов, затем
#    дереф — сужение ДОЛЖНО инвалидироваться (проверили одно, используем другое).
cat > нуллабл_вызов_toctou.конда <<'KONDA'
#содержит <stdio.h>
структура Узел { целое32 знач }
возможно<Узел*> найти(целое32 к) { вернуть нуль }
целое32 точка_входа(срез<символ*> аргументы)
{
    возможно<Узел*> п = найти(5)
    если (п != нуль) {
        п = найти(9)
        printf("%d\n", п.знач)
    } иначе { }
    вернуть 0
}
KONDA
if "$BIN" нуллабл_вызов_toctou.конда >"$TMP/нуллабл_toctou.log" 2>&1; then
    fail "TOCTOU: дереф после реассайна nullable-вызова под охранником — ошибка"
fi
grep -q "может быть нулевым" "$TMP/нуллабл_toctou.log" || { cat "$TMP/нуллабл_toctou.log" >&2; fail "нуллабл_вызов_toctou: ожидалась конкретная диагностика, не любая ошибка"; }

# 4) Позитив: правильный охранник «если (п != нуль) { п.знач }» — компилируется
#    и на null-пути идёт в «иначе» (сужение работает как раньше).
cat > нуллабл_вызов_охранник.конда <<'KONDA'
#содержит <stdio.h>
структура Узел { целое32 знач }
возможно<Узел*> найти(целое32 к) { вернуть нуль }
целое32 точка_входа(срез<символ*> аргументы)
{
    возможно<Узел*> п = найти(5)
    если (п != нуль) { printf("%d\n", п.знач) } иначе { printf("нет\n") }
    вернуть 0
}
KONDA
"$BIN" нуллабл_вызов_охранник.конда >"$TMP/нуллабл_охранник.log" 2>&1 || {
    cat "$TMP/нуллабл_охранник.log" >&2
    fail "корректный охранник над nullable-вызовом должен компилироваться"
}
assert_eq "нет" "$(./вывод/нуллабл_вызов_охранник.elf)" "сужение под охранником: null-путь в «иначе»"

# 5) Позитив: функция с НЕнулевым возвратом («Узел*», не «возможно») — результат
#    ненулевой, дереф без охранника разрешён (не переусердствовали с запретом).
cat > ненуллабл_вызов.конда <<'KONDA'
#содержит <stdio.h>
структура Узел { целое32 знач }
Узел* дай(Узел* у) { вернуть у }
целое32 читать(Узел* у) { вернуть дай(у).знач }
целое32 точка_входа(срез<символ*> аргументы)
{
    вернуть 0
}
KONDA
"$BIN" --только-си ненуллабл_вызов.конда >"$TMP/ненуллабл.log" 2>&1 || {
    cat "$TMP/ненуллабл.log" >&2
    fail "дереф результата НЕнулевого возврата не должен требовать охранника"
}

# Негатив: обычный «Структура* п = нуль» (не «возможно») — ненулевой по умолчанию.
