    cat "$TMP/путь_нуль_одна_ветвь.log" >&2
    fail "ошибка возможного нуля должна указывать на путь исполнения"
}

# Тот же указатель присвоен в ОБЕИХ ветвях → не нуль ни на одном пути → OK.
cat > путь_нуль_обе_ветви.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    возможно<символ*> п = нуль
    если (длина(аргументы) > 1) {
