    }
    printf("%d\n", послед)
    вернуть 0
}
KONDA

"$BIN" цикл_гарантирован_иниц.конда >"$TMP/цикл_гарантирован_иниц.log" 2>&1 || {
    cat "$TMP/цикл_гарантирован_иниц.log" >&2
    fail "цикл с константными границами должен засчитывать инициализацию в теле"
}
assert_eq "2" "$(./вывод/цикл_гарантирован_иниц.elf)" "гарантированный цикл: послед = 2"

# Динамическая граница (argc) — цикл может не выполниться → консервативно ошибка.
cat > цикл_динамический_иниц.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 послед
    для целое32 и = 0; и < длина(аргументы); и = и + 1 {
        послед = и
    }
    printf("%d\n", послед)
    вернуть 0
}
KONDA

if "$BIN" цикл_динамический_иниц.конда >"$TMP/цикл_динамический_иниц.log" 2>&1; then
