# для_каждого по массиву фикс. размера (всегда ≥1 элемент) → гарантирован.
cat > цикл_каждого_гарантирован.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 а[3] = { 5, 6, 7 }
    целое32 послед
    для_каждого э из а {
        послед = э
    }
    printf("%d\n", послед)
    вернуть 0
}
KONDA

"$BIN" цикл_каждого_гарантирован.конда >"$TMP/цикл_каждого_гарантирован.log" 2>&1 || {
