# ─── Условия/циклы без обрамляющих «(…)» (как в Rust) ────────────────────────
# «если»/«иначе если»/«пока»/«для»/«для_каждого» пишутся без скобок вокруг
# условия/заголовка; тело всегда начинается с «{». Проверяем разбор и результат.
cat > без_скобок.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 н = длина(аргументы)
    целое32 сумма = 0
    если н > 2 {
        сумма = 100
    } иначе если н == 2 {
        сумма = 20
    } иначе {
        сумма = 1
    }
    для целое32 и = 0; и < н; и = и + 1 {
        сумма = сумма + и
    }
    целое32 к = 0
    пока к < 3 {
        к = к + 1
    }
    для_каждого а из аргументы {
        сумма = сумма + 0
    }
    printf("%d %d\n", сумма, к)
    вернуть 0
}
KONDA

"$BIN" без_скобок.конда >"$TMP/без_скобок.log" 2>&1 || {
    cat "$TMP/без_скобок.log" >&2
    fail "условия/циклы без «(…)» должны транспилироваться"
}
# при двух аргументах: н==3 → ветвь 100, цикл +0+1+2=3, foreach +0 → 103; к=3
assert_eq "103 3" "$(./вывод/без_скобок.elf a b)" "если/иначе/пока/для/для_каждого без скобок"

# Обратная совместимость: скобки вокруг условия «если»/«пока» — это обычное
# скобочное выражение, по-прежнему допустимы.
cat > скобки_условия_ок.конда <<'KONDA'
целое32 точка_входа(срез<символ*> аргументы)
{
    если (длина(аргументы) > 0) { вернуть 1 }
    вернуть 0
}
KONDA
"$BIN" --только-си скобки_условия_ок.конда >"$TMP/скобки_условия_ок.log" 2>&1 || {
    cat "$TMP/скобки_условия_ок.log" >&2
    fail "скобочное условие «если (…)» должно оставаться допустимым"
}

# Негатив: старая форма «для (…)» снята — обрамляющие скобки заголовка «для»
# больше не разбираются (заголовок — «инициализация; условие; шаг» без скобок).
cat > для_скобки_снято.конда <<'KONDA'
целое32 точка_входа(срез<символ*> аргументы)
{
    для (целое32 и = 0; и < 3; и = и + 1) { }
    вернуть 0
}
KONDA
if "$BIN" --только-си для_скобки_снято.конда >"$TMP/для_скобки_снято.log" 2>&1; then
    cat "$TMP/для_скобки_снято.log" >&2
    fail "старая форма «для (…)» должна быть ошибкой разбора"
fi
grep -q "неожиданное выражение" "$TMP/для_скобки_снято.log" || { cat "$TMP/для_скобки_снято.log" >&2; fail "для_скобки_снято: ожидалась конкретная диагностика, не любая ошибка"; }

# ─── Срезы: защита от переполнения буфера ──────────────────────────────────

# Базовый сценарий: выделить, заполнить в цикле, прочитать, длина.
cat > срез_базовый.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> д = выделить(5)
    для целое32 и = 0; и < длина(д); и = и + 1 {
        д[и] = и * и
    }
    целое32 сумма = 0
    для целое32 и = 0; и < длина(д); и = и + 1 {
        сумма = сумма + д[и]
    }
    printf("%d %d\n", длина(д), сумма)
    вернуть 0
}
KONDA

"$BIN" срез_базовый.конда >"$TMP/срез_базовый.log" 2>&1 || {
    cat "$TMP/срез_базовый.log" >&2
    fail "базовый срез должен транспилироваться"
}
grep -q "срез_доступ"   вывод/срез_базовый.c || { cat вывод/срез_базовый.c >&2; fail "доступ к срезу через срез_доступ"; }
grep -q "срез_выделить" вывод/срез_базовый.c || { cat вывод/срез_базовый.c >&2; fail "выделить → срез_выделить"; }
assert_eq "5 30" "$(./вывод/срез_базовый.elf)" "срез: длина и сумма квадратов 0..4"

# Оптимизация A: размер элемента НЕ хранится в дескрипторе Срез (16 байт, а не
# 24). Тип объявляется двумя полями. Проверяем layout здесь; передачу sizeof(T)
# в срез_доступ/срез_клон — отдельным тестом ниже (тут доступ проходит BCE).
grep -q "typedef struct { void \*данные; size_t длина; } Срез;" вывод/срез_базовый.c || {
    cat вывод/срез_базовый.c >&2
    fail "Срез должен быть {данные, длина} без эл_размер (16-байтный дескриптор)"
}
grep -q "эл_размер; } Срез" вывод/срез_базовый.c && {
    cat вывод/срез_базовый.c >&2
    fail "эл_размер не должен храниться в дескрипторе Срез"
}

# Передача sizeof(T) литералом в срез_выделить/срез_доступ/срез_клон. Срез «д»
# возвращается из создать5() → покидает область → куча (escape-анализ на стек не
# продвигает), поэтому срез_выделить_бз реально эмитится. Охраняемый индекс — не
# BCE, поэтому срез_доступ тоже эмитится.
cat > срез_разм_элем.конда <<'KONDA'
#содержит <stdio.h>

срез<целое32> создать5()
{
    срез<целое32> д = выделить(5)
    вернуть д
}

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> д = создать5()
    неподписанный целое32 к = как<неподписанный целое32>(длина(аргументы))
    если (к < длина(д)) { } иначе { к = 0 }
    д[к] = 7
    срез<целое32> е = клон(д)
    printf("%d\n", е[к])
    вернуть 0
}
KONDA

"$BIN" срез_разм_элем.конда >"$TMP/срез_разм_элем.log" 2>&1 || {
    cat "$TMP/срез_разм_элем.log" >&2
    fail "срез_разм_элем должен транспилироваться"
}
grep -q "срез_выделить_бз(5, sizeof(int32_t))" вывод/срез_разм_элем.c || {
    cat вывод/срез_разм_элем.c >&2
    fail "срез_выделить должен получать sizeof(T) литералом"
}
grep -q ")срез_доступ(д, к, sizeof(int32_t)," вывод/срез_разм_элем.c || {
    cat вывод/срез_разм_элем.c >&2
    fail "срез_доступ должен получать sizeof(T) литералом на месте вызова"
}
grep -q "срез_клон(д, sizeof(int32_t))" вывод/срез_разм_элем.c || {
    cat вывод/срез_разм_элем.c >&2
    fail "срез_клон должен получать sizeof(T) литералом"
}
assert_eq "7" "$(./вывод/срез_разм_элем.elf)" "срез с sizeof-элементом: доступ и клон корректны"

# Оптимизация B: элизия знак-клампа «количество < 0 ? 0» когда количество
# доказанно ≥ 0 → срез_выделить_бз (без ветви). Признаки: беззнаковый тип и
# числовой литерал. Знаковое значение (может стать отрицательным) сохраняет
# кламп → обычный срез_выделить.
cat > выделить_бз.конда <<'KONDA'
#содержит <stdio.h>

срез<целое32> лит8()
{
    срез<целое32> с = выделить(8)
    вернуть с
}

целое32 точка_входа(срез<символ*> аргументы)
{
    неподписанный целое32 н = как<неподписанный целое32>(длина(аргументы))
    срез<целое32> беззнак = выделить(н)
    срез<целое32> литерал = лит8()
    срез<целое32> знак = выделить(длина(аргументы))
    printf("%d %d %d\n", длина(беззнак), длина(литерал), длина(знак))
    вернуть 0
}
KONDA

"$BIN" выделить_бз.конда >"$TMP/выделить_бз.log" 2>&1 || {
    cat "$TMP/выделить_бз.log" >&2
    fail "выделить_бз должен транспилироваться"
}
grep -q "срез_выделить_бз(н, sizeof(int32_t))" вывод/выделить_бз.c || {
    cat вывод/выделить_бз.c >&2
    fail "беззнаковое количество → срез_выделить_бз (без клампа)"
}
grep -q "срез_выделить_бз(8, sizeof(int32_t))" вывод/выделить_бз.c || {
    cat вывод/выделить_бз.c >&2
    fail "литеральное количество → срез_выделить_бз (без клампа)"
}
grep -q "срез_выделить(((int32_t)(аргументы).длина), sizeof(int32_t))" вывод/выделить_бз.c || {
    cat вывод/выделить_бз.c >&2
    fail "знаковое количество должно сохранять кламп (срез_выделить)"
}
assert_eq "3 8 3" "$(./вывод/выделить_бз.elf a b)" "выделить_бз: длины корректны при обоих вариантах"

# Оптимизация C: escape-анализ размещает «выделить(литерал)», не покидающий
# область, на стеке (без calloc/free). Заимствование (индекс, длина, клон-
# источник, обычный срез-параметр) не считается утечкой.
cat > стек_срез.конда <<'KONDA'
#содержит <stdio.h>

целое32 сумма(срез<целое32> с)
{
    целое32 т = 0
    для целое32 и = 0; и < длина(с); и = и + 1 { т = т + с[и] }
    вернуть т
}

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> стек = выделить(4)
    для целое32 и = 0; и < длина(стек); и = и + 1 { стек[и] = и * 10 }
    срез<целое32> копия = клон(стек)
    printf("%d %d\n", сумма(стек), сумма(копия))
    вернуть 0
}
KONDA

"$BIN" стек_срез.конда >"$TMP/стек_срез.log" 2>&1 || {
    cat "$TMP/стек_срез.log" >&2
    fail "стек_срез должен транспилироваться"
}
# «стек» размещается на стеке: буфер _стек_стек[4] и дескриптор без calloc.
grep -q "int32_t _стек_стек\[4\] = {0};" вывод/стек_срез.c || {
    cat вывод/стек_срез.c >&2
    fail "невыбегающий выделить(литерал) должен размещаться на стеке"
}
grep -q "Срез стек = (Срез){ \.данные = _стек_стек, \.длина = 4 };" вывод/стек_срез.c || {
    cat вывод/стек_срез.c >&2
    fail "стековый срез: дескриптор {данные, длина} на буфер"
}
# Для стекового среза нет ни срез_выделить, ни free(стек.данные).
awk '/int32_t main/,/^}/' вывод/стек_срез.c | grep -q "срез_выделить.*стек\|free(стек\.данные)" && {
    cat вывод/стек_срез.c >&2
    fail "стековый срез не должен ни выделяться в куче, ни освобождаться"
}
# Клон-приёмник — на куче: клон копирует в новую heap-память, освобождается.
grep -q "free(копия.данные);" вывод/стек_срез.c || {
    cat вывод/стек_срез.c >&2
    fail "клон должен давать heap-владельца с free"
}
assert_eq "60 60" "$(./вывод/стек_срез.elf)" "стековый срез: сумма и независимый клон"

# Escape-негативы: каждый способ утечки владения оставляет срез в куче (ложное
# продвижение на стек = крах). Проверяем, что _стек_ не появляется.
cat > стек_негатив.конда <<'KONDA'
#содержит <stdio.h>

срез<целое32> отдать()
{
    срез<целое32> в = выделить(4)
    вернуть в
}

целое32 поглотить(владеет срез<целое32> п)
{
    вернуть длина(п)
}

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> м1 = выделить(4)
    срез<целое32> м2 = м1
    срез<целое32> пере = выделить(4)
    пере = клон(м2)
    срез<целое32> потр = выделить(4)
    целое32 _ = поглотить(потр)
    printf("%d %d\n", длина(м2), длина(пере))
    вернуть 0
}
KONDA

"$BIN" стек_негатив.конда >"$TMP/стек_негатив.log" 2>&1 || {
    cat "$TMP/стек_негатив.log" >&2
    fail "стек_негатив должен транспилироваться"
}
if grep -q "_стек_" вывод/стек_негатив.c; then
    cat вывод/стек_негатив.c >&2
    fail "убегающий срез (возврат/move/переприсваивание/владеет) НЕ должен идти на стек"
fi
assert_eq "4 4" "$(./вывод/стек_негатив.elf)" "escape-негативы работают на куче"

# ASan/UBSan: стековый срез с индексацией и клоном — без выхода за буфер.
if command -v cc >/dev/null 2>&1; then
    cc -std=gnu23 -g -O0 -fsanitize=address,undefined вывод/стек_срез.c -o "$TMP/стек_срез_asan" 2>/dev/null
    if [ -x "$TMP/стек_срез_asan" ]; then
        "$TMP/стек_срез_asan" >"$TMP/стек_срез_asan.out" 2>&1 || {
            cat "$TMP/стек_срез_asan.out" >&2
            fail "стековый срез под ASan/UBSan падает"
        }
        assert_eq "60 60" "$(cat "$TMP/стек_срез_asan.out")" "стековый срез чист под ASan"
    fi
fi

# ─── Типы элемента среза: срез<структура> и срез<T*> (Задачи 2+4) ─────────────
# Элемент среза может быть ИМЕНОВАННОЙ структурой (по значению) или указателем
# (на примитив/структуру). Та же срез-машинерия: границы, autofree дескриптора,
# move/клон; для структур из примитивов деструкции элементов нет (нулевая цена).
cat > срез_структура.конда <<'KONDA'
#содержит <stdio.h>

структура Точка {
    целое32 х
    целое32 у
}

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<Точка> точки = выделить(3)
    точки[0].х = 10
    точки[1].х = 30
    точки[2].х = 5
    целое32 сумма = 0
    для_каждого т из точки { сумма = сумма + т.х }
    срез<Точка> копия = клон(точки)
    копия[0].х = 100
    printf("%d %d %d\n", сумма, точки[0].х, копия[0].х)
    вернуть 0
}
KONDA

"$BIN" срез_структура.конда >"$TMP/срез_структура.log" 2>&1 || {
    cat "$TMP/срез_структура.log" >&2
    fail "срез<структура> должен транспилироваться"
}
# Каст элемента — по имени структуры (Точка *), а не «int».
grep -q "(Точка \*)" вывод/срез_структура.c || {
    cat вывод/срез_структура.c >&2
    fail "срез<структура>: каст элемента должен быть по имени структуры"
}
grep -q "sizeof(Точка)" вывод/срез_структура.c || {
    cat вывод/срез_структура.c >&2
    fail "срез<структура>: выделение/клон по sizeof(Точка)"
}
# клон независим (копия[0].х=100 не трогает точки[0].х=10); сумма=45.
assert_eq "45 10 100" "$(./вывод/срез_структура.elf)" "срез<структура>: доступ, foreach, независимый клон"

# срез<T*>: указательный элемент. Строки (символ*) — канонический безопасный
# случай; выкладываются на стек как массив указателей.
cat > срез_указателей.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<символ*> имена = выделить(2)
    имена[0] = "Аня"
    имена[1] = "Боря"
    для_каждого имя из имена { printf("%s\n", имя) }
    вернуть 0
}
KONDA

"$BIN" срез_указателей.конда >"$TMP/срез_указателей.log" 2>&1 || {
    cat "$TMP/срез_указателей.log" >&2
    fail "срез<символ*> должен транспилироваться"
}
grep -q "(char\* \*)" вывод/срез_указателей.c || {
    cat вывод/срез_указателей.c >&2
    fail "срез<символ*>: каст элемента — указатель на указатель"
}
assert_eq "Аня
Боря" "$(./вывод/срез_указателей.elf)" "срез<символ*>: массив строк + foreach"

# ASan/UBSan: срез структур и срез указателей — без выхода за буфер.
if command -v cc >/dev/null 2>&1; then
    for f in срез_структура срез_указателей; do
        cc -std=gnu23 -g -O0 -fsanitize=address,undefined "вывод/$f.c" -o "$TMP/${f}_asan" 2>/dev/null
        if [ -x "$TMP/${f}_asan" ]; then
            "$TMP/${f}_asan" >"$TMP/${f}_asan.out" 2>&1 || {
                cat "$TMP/${f}_asan.out" >&2
                fail "$f под ASan/UBSan падает"
            }
        fi
    done
fi

