# ─── Ящик<T>: одиночный владеющий heap-объект (Задача 5) ──────────────────────
# «Ящик<T> б = выделить()» → «T* б = calloc(1, sizeof(T))»; «б.поле» → «б->поле»;
# autofree «free(б)» при выходе; move как у среза (двойного free нет).
cat > ящик.конда <<'KONDA'
#содержит <stdio.h>

структура Окно {
    целое32 ширина
    целое32 высота
}

целое32 точка_входа(срез<символ*> аргументы)
{
    Ящик<Окно> о = выделить()
    о.ширина = 640
    о.высота = 480
    Ящик<Окно> п = о             // перемещение владения
    printf("%d x %d\n", п.ширина, п.высота)
    вернуть 0
}
KONDA
"$BIN" ящик.конда >"$TMP/ящик.log" 2>&1 || {
    cat "$TMP/ящик.log" >&2
    fail "Ящик<T> должен транспилироваться"
}
grep -q "Окно \*о = calloc(1, sizeof(Окно))" вывод/ящик.c || {
    cat вывод/ящик.c >&2
    fail "Ящик: выделить() → T* = calloc(1, sizeof(T))"
}
grep -q "о->ширина = 640" вывод/ящик.c || {
    cat вывод/ящик.c >&2
    fail "Ящик: б.поле → б->поле (авто-разыменование)"
}
grep -q "free(п)" вывод/ящик.c || { cat вывод/ящик.c >&2; fail "Ящик: autofree free(б)"; }
# Двойного free нет: источник перемещён (free только у получателя «п»).
awk '/int32_t main|точка_входа/,/^}/' вывод/ящик.c | grep -c "free(" | grep -q "^1$" || {
    cat вывод/ящик.c >&2
    fail "Ящик move: должен быть ровно один free (источник перемещён)"
}
assert_eq "640 x 480" "$(./вывод/ящик.elf)" "Ящик: доступ к полям, move, autofree"

# ASan/UBSan: Ящик без утечки/двойного free.
if command -v cc >/dev/null 2>&1; then
    cc -std=gnu23 -g -O0 -fsanitize=address,undefined вывод/ящик.c -o "$TMP/ящик_asan" 2>/dev/null
    if [ -x "$TMP/ящик_asan" ]; then
        "$TMP/ящик_asan" >"$TMP/ящик_asan.out" 2>&1 || {
            cat "$TMP/ящик_asan.out" >&2; fail "Ящик под ASan/UBSan падает"; }
        assert_eq "640 x 480" "$(cat "$TMP/ящик_asan.out")" "Ящик чист под ASan"
    fi
fi

