# Бэктрейс при срабатывании guard'а: конда_прервать печатает стек перед abort.
# Всегда вшит в рантайм; читаемость дают -rdynamic/-g/unwind-таблицы (только
# размер, не скорость), снимаемые «--без-символов». -fno-omit-frame-pointer НЕ
# добавляется (скорость релиза цела). Проверяем и отладку, и релиз.
cat > бэктрейс.конда <<'KONDA'
#содержит <stdio.h>

целое32 достать(срез<целое32> с, целое32 и) { вернуть с[и] }

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> с = выделить(3)
    printf("%d\n", достать(с, длина(аргументы) + 100))
    вернуть 0
}
KONDA

for mode in "" "--релиз"; do
    label="${mode:-отладка}"
    "$BIN" $mode бэктрейс.конда >"$TMP/бэктрейс.$label.log" 2>&1 || {
        cat "$TMP/бэктрейс.$label.log" >&2
        fail "бэктрейс ($label): транспиляция"
    }
    # Рантайм: конда_прервать вшит и вызван из guard'а.
    grep -q "конда_прервать" вывод/бэктрейс.c || {
        cat вывод/бэктрейс.c >&2
        fail "бэктрейс ($label): guard должен звать конда_прервать"
    }
    grep -q "backtrace(" вывод/бэктрейс.c || fail "бэктрейс ($label): нет backtrace() в рантайме"
    # Линковка: размер-флаги есть, а -fno-omit-frame-pointer НЕТ (скорость).
    cc_cmd=$("$BIN" $mode бэктрейс.конда 2>/dev/null | grep -E "rdynamic")
    printf '%s' "$cc_cmd" | grep -q -- "-rdynamic" || fail "бэктрейс ($label): нет -rdynamic по умолчанию"
    printf '%s' "$cc_cmd" | grep -q -- "-funwind-tables" || fail "бэктрейс ($label): нет -funwind-tables"
    printf '%s' "$cc_cmd" | grep -q -- "-fno-omit-frame-pointer" && fail "бэктрейс ($label): -fno-omit-frame-pointer не должен добавляться"
    # Исполнение: SIGABRT, сообщение guard'а И заголовок стека.
    ./вывод/бэктрейс.elf >"$TMP/бэктрейс.$label.out" 2>"$TMP/бэктрейс.$label.err" && rc=0 || rc=$?
    assert_eq "134" "$rc" "бэктрейс ($label): выход за границы прерывает (SIGABRT)"
    grep -q "выход за границы среза" "$TMP/бэктрейс.$label.err" || {
        cat "$TMP/бэктрейс.$label.err" >&2
        fail "бэктрейс ($label): сообщение guard'а"
    }
    grep -q "стек вызовов" "$TMP/бэктрейс.$label.err" || {
        cat "$TMP/бэктрейс.$label.err" >&2
        fail "бэктрейс ($label): должен печататься стек вызовов"
    }
done

# «--без-символов»: размер-флаги сняты, но бэктрейс всё равно печатается.
cc_cmd=$("$BIN" --релиз --без-символов бэктрейс.конда 2>/dev/null | grep -E "cc |gcc ")
printf '%s' "$cc_cmd" | grep -q -- "-rdynamic" && fail "--без-символов: -rdynamic должен быть снят"
printf '%s' "$cc_cmd" | grep -q -- "-g" && fail "--без-символов: -g должен быть снят"
./вывод/бэктрейс.elf >"$TMP/бэктрейс_без.out" 2>"$TMP/бэктрейс_без.err" && rc=0 || rc=$?
assert_eq "134" "$rc" "--без-символов: программа всё равно прерывается"
grep -q "стек вызовов" "$TMP/бэктрейс_без.err" || {
    cat "$TMP/бэктрейс_без.err" >&2
    fail "--без-символов: бэктрейс должен остаться (кадры адресами)"
}

