# Библиотека без срезов не должна тянуть рантайм-пролог срезов. (Программа с
# точкой входа теперь ВСЕГДА несёт срез: «аргументы» (argv) — срез<символ*>,
# синтезируемый прологом main; поэтому «без срезов» проверяем на библиотеке.)
cat > без_срезов.конда <<'KONDA'
#содержит <stdio.h>

