# ─── Массивы фиксированного размера (как в Rust [T; N]) ────────────────────

# Базовый сценарий: объявить, заполнить, прочитать. Зануление по умолчанию.
cat > массив_базовый.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 арр[5]
    для целое32 и = 0; и < 5; и = и + 1 {
        арр[и] = и + 1
    }
    целое32 сумма = 0
    для целое32 и = 0; и < 5; и = и + 1 {
        сумма = сумма + арр[и]
    }
    printf("%d %d\n", арр[2], сумма)
    вернуть 0
}
KONDA

"$BIN" массив_базовый.конда >"$TMP/массив_базовый.log" 2>&1 || {
    cat "$TMP/массив_базовый.log" >&2
    fail "массив фикс. размера должен транспилироваться"
}
grep -q "int32_t арр\[5\] = {0}" вывод/массив_базовый.c || { cat вывод/массив_базовый.c >&2; fail "объявление массива → [N] = {0}"; }
grep -q "арр\[2\]"             вывод/массив_базовый.c || { cat вывод/массив_базовый.c >&2; fail "литеральный индекс → прямой доступ"; }
# Цикл «и < 5» по массиву длины 5 — доступ доказанно в границах, проверка снята.
if grep -q ")массив_доступ(" вывод/массив_базовый.c; then
    cat вывод/массив_базовый.c >&2
    fail "доступ в каноническом цикле по массиву должен быть без рантайм-проверки"
fi
assert_eq "3 15" "$(./вывод/массив_базовый.elf)" "массив: элемент [2] и сумма 1..5"

