# ─── Элиминация лишних проверок границ ──────────────────────────────────────

# Канонический цикл «для и=0; и<длина(д); и=и+1» — доступ д[и] доказанно
# в границах, рантайм-проверка убирается (прямой доступ к .данные).
cat > элиминация_цикл.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> д = выделить(5)
    для целое32 и = 0; и < длина(д); и = и + 1 {
        д[и] = и * и
    }
    целое32 сумма = 0
    для целое32 и = 0; и < длина(д); и = и + 1 {
        сумма = сумма + д[и]
    }
    printf("%d\n", сумма)
    вернуть 0
}
KONDA

"$BIN" элиминация_цикл.конда >"$TMP/элиминация_цикл.log" 2>&1 || {
    cat "$TMP/элиминация_цикл.log" >&2
    fail "цикл по срезу должен транспилироваться"
}
if grep -q ")срез_доступ(" вывод/элиминация_цикл.c; then
    cat вывод/элиминация_цикл.c >&2
    fail "проверка границ в каноническом цикле по срезу должна быть устранена"
fi
assert_eq "30" "$(./вывод/элиминация_цикл.elf)" "элиминация в цикле: вывод корректен"

# «утверждать_равные(a, b, …)»: одна рантайм-проверка длин ВНЕ цикла делает
# «b[и]»/«c[и]» доказанно-безопасными в цикле «и < длина(a)» — SoA-паттерн
# физики/3D на срезах-параметрах, тело векторизуется (0 проверок внутри).
cat > утв_равные.конда <<'KONDA'
#содержит <stdio.h>

вещественное64 сумма_soa(срез<вещественное64> поз, срез<вещественное64> скор,
                          срез<вещественное64> ускор, вещественное64 dt)
{
    утверждать_равные(поз, скор, ускор)
    вещественное64 s = 0.0
    для целое32 и = 0; и < длина(поз); и = и + 1 {
        скор[и] = скор[и] + ускор[и] * dt
        поз[и] = поз[и] + скор[и] * dt
        s = s + поз[и]
    }
    вернуть s
}

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<вещественное64> п = выделить(4)
    срез<вещественное64> с = выделить(4)
    срез<вещественное64> у = выделить(4)
    для целое32 и = 0; и < длина(у); и = и + 1 { у[и] = 1.0 }
    вещественное64 r = сумма_soa(п, с, у, 1.0)
    printf("%.0f\n", r)
    вернуть 0
}
KONDA
"$BIN" утв_равные.конда >"$TMP/утв_равные.log" 2>&1 || {
    cat "$TMP/утв_равные.log" >&2; fail "утверждать_равные должно транспилироваться"; }
# В горячем теле НЕТ ни одного срез_доступ (все три среза — прямой доступ).
if grep -q ")срез_доступ(" вывод/утв_равные.c; then
    grep -n "срез_доступ(" вывод/утв_равные.c >&2
    fail "утверждать_равные: скор[и]/ускор[и] должны быть доказаны (нет срез_доступ)"
fi
# Проверка длин эмитится РОВНО один раз (вне цикла).
grep -q "срезы разной длины" вывод/утв_равные.c \
    || fail "утверждать_равные: должна эмититься рантайм-проверка длин"
# poz[i]=poz[i]+skor[i]*dt, skor[i]=skor[i]+uskor[i]*dt=0+1=1; poz=0+1=1; сумма=4.
assert_eq "4" "$(./вывод/утв_равные.elf)" "утверждать_равные: SoA-цикл считает верно"

# Несовпадение длин → чистая паника (abort), не тихая порча.
cat > утв_равные_несовпад.конда <<'KONDA'
ничего ф(срез<целое32> a, срез<целое32> b)
{
    утверждать_равные(a, b)
    для целое32 и = 0; и < длина(a); и = и + 1 { a[и] = b[и] }
}
целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> x = выделить(8)
    срез<целое32> y = выделить(4)
    ф(x, y)
    вернуть 0
}
KONDA
"$BIN" утв_равные_несовпад.конда >"$TMP/утвн.log" 2>&1 \
    || { cat "$TMP/утвн.log" >&2; fail "утв_равные_несовпад должно транспилироваться"; }
if ./вывод/утв_равные_несовпад.elf 2>"$TMP/утвн.err"; then
    fail "несовпадение длин в утверждать_равные должно приводить к abort"
fi
grep -q "срезы разной длины" "$TMP/утвн.err" \
    || { cat "$TMP/утвн.err" >&2; fail "паника утверждать_равные должна быть понятной"; }

# Реассайн члена группы ИНВАЛИДИРУЕТ доказательство (memory-safety): после
# «скор = выделить(2)» доступ «скор[и]» под «и<длина(поз)» снова проверяется.
cat > утв_равные_инвалид.конда <<'KONDA'
целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> поз = выделить(8)
    срез<целое32> скор = выделить(8)
    утверждать_равные(поз, скор)
    скор = выделить(2)
    для целое32 и = 0; и < длина(поз); и = и + 1 { поз[и] = скор[и] }
    вернуть 0
}
KONDA
"$BIN" утв_равные_инвалид.конда >"$TMP/утви.log" 2>&1 \
    || { cat "$TMP/утви.log" >&2; fail "утв_равные_инвалид должно транспилироваться"; }
grep -q "срез_доступ(скор" вывод/утв_равные_инвалид.c \
    || { grep -n "скор" вывод/утв_равные_инвалид.c >&2; \
         fail "после реассайна скор[и] обязан снова проверяться (инвалидация группы)"; }

# «утверждать_в_границах(индексы, длина(база))»: косвенный доступ индекс-буфера
# «база[индексы[i]]» (3D-меши) — прямой gather без проверки в цикле, одна
# O(n)-валидация индексов вне цикла.
cat > утв_границы.конда <<'KONDA'
#содержит <stdio.h>

вещественное64 собрать(срез<вещественное64> вершины, срез<целое32> индексы)
{
    утверждать_в_границах(индексы, длина(вершины))
    вещественное64 s = 0.0
    для целое32 и = 0; и < длина(индексы); и = и + 1 {
        s = s + вершины[индексы[и]]
    }
    вернуть s
}

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<вещественное64> в = выделить(4)
    для целое32 и = 0; и < длина(в); и = и + 1 { в[и] = и * 10 }
    срез<целое32> идx = выделить(6)
    идx[0] = 3
    идx[1] = 1
    идx[2] = 0
    идx[3] = 3
    идx[4] = 2
    идx[5] = 1
    printf("%.0f\n", собрать(в, идx))
    вернуть 0
}
KONDA
"$BIN" утв_границы.конда >"$TMP/утв_границы.log" 2>&1 || {
    cat "$TMP/утв_границы.log" >&2; fail "утверждать_в_границах должно транспилироваться"; }
# Косвенный gather «вершины[индексы[и]]» — прямой, без срез_доступ в теле.
if grep -q ")срез_доступ(" вывод/утв_границы.c; then
    grep -n "срез_доступ(" вывод/утв_границы.c >&2
    fail "утверждать_в_границах: вершины[индексы[и]] должен быть прямым (нет срез_доступ)"
fi
grep -q "вне \[0," вывод/утв_границы.c \
    || fail "утверждать_в_границах: должна эмититься O(n)-валидация индексов"
# в=[0,10,20,30]; idx=[3,1,0,3,2,1] → 30+10+0+30+20+10 = 100.
assert_eq "100" "$(./вывод/утв_границы.elf)" "утверждать_в_границах: gather считает верно"

# Индекс вне границ → чистая паника (abort).
cat > утв_границы_oob.конда <<'KONDA'
#содержит <stdio.h>
вещественное64 ф(срез<вещественное64> в, срез<целое32> идx)
{
    утверждать_в_границах(идx, длина(в))
    вещественное64 s = 0.0
    для целое32 и = 0; и < длина(идx); и = и + 1 { s = s + в[идx[и]] }
    вернуть s
}
целое32 точка_входа(срез<символ*> аргументы)
{
    срез<вещественное64> в = выделить(4)
    срез<целое32> идx = выделить(2)
    идx[0] = 1
    идx[1] = 9
    printf("%.0f\n", ф(в, идx))
    вернуть 0
}
KONDA
"$BIN" утв_границы_oob.конда >"$TMP/угoob.log" 2>&1 \
    || { cat "$TMP/угoob.log" >&2; fail "утв_границы_oob должно транспилироваться"; }
if ./вывод/утв_границы_oob.elf 2>"$TMP/угoob.err"; then
    fail "индекс вне границ в утверждать_в_границах должен приводить к abort"
fi
grep -q "вне \[0, 4)" "$TMP/угoob.err" \
    || { cat "$TMP/угoob.err" >&2; fail "паника утверждать_в_границах должна называть индекс и границу"; }

# Реассайн базы ИНВАЛИДИРУЕТ доказательство (memory-safety).
cat > утв_границы_инвалид.конда <<'KONDA'
целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> в = выделить(8)
    срез<целое32> идx = выделить(4)
    утверждать_в_границах(идx, длина(в))
    в = выделить(2)
    целое32 s = 0
    для целое32 и = 0; и < длина(идx); и = и + 1 { s = s + в[идx[и]] }
    вернуть s
}
KONDA
"$BIN" утв_границы_инвалид.конда >"$TMP/уги.log" 2>&1 \
    || { cat "$TMP/уги.log" >&2; fail "утв_границы_инвалид должно транспилироваться"; }
grep -q "срез_доступ(в" вывод/утв_границы_инвалид.c \
    || { grep -n "идx" вывод/утв_границы_инвалид.c >&2; \
