# Неканонический цикл (предел не «длина(д)») — проверка СОХРАНЯЕТСЯ, рантайм
# ловит выход за границу.
cat > сохранить_проверку.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> д = выделить(3)
    целое32 предел = длина(аргументы) + 100
    для целое32 и = 0; и < предел; и = и + 1 {
        д[и] = и
    }
    printf("недостижимо\n")
    вернуть 0
}
KONDA

"$BIN" сохранить_проверку.конда >"$TMP/сохранить_проверку.log" 2>&1 || {
    cat "$TMP/сохранить_проверку.log" >&2
    fail "цикл с чужим пределом должен транспилироваться"
}
grep -q ")срез_доступ(" вывод/сохранить_проверку.c || {
    cat вывод/сохранить_проверку.c >&2
    fail "проверка границ при цикле с чужим пределом должна сохраняться"
}
./вывод/сохранить_проверку.elf >/dev/null 2>"$TMP/сохранить_проверку.err" && rc=0 || rc=$?
assert_eq "134" "$rc" "выход за границу в неканоническом цикле прерывает программу"

# Тело меняет индекс — элиминация недопустима, проверка сохраняется.
cat > сохранить_при_изменении_индекса.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> д = выделить(5)
    для целое32 и = 0; и < длина(д); и = и + 1 {
        и = и + длина(аргументы)
        д[и] = 1
    }
    printf("ок\n")
    вернуть 0
}
KONDA

"$BIN" сохранить_при_изменении_индекса.конда >"$TMP/сохранить_при_изменении_индекса.log" 2>&1 || {
