}
grep -q ")срез_доступ(" вывод/сохранить_при_изменении_индекса.c || {
    cat вывод/сохранить_при_изменении_индекса.c >&2
    fail "при изменении индекса в теле проверка границ должна сохраняться"
}

# Регресс безопасности: тело меняет индекс НЕ присваиванием, а передачей в
# «изменяемый»-параметр (кодоген подставит «&и», функция изменит переменную).
# Элиминация проверки границ ДОЛЖНА быть отменена — иначе heap-overflow (ASan
# ловил его до фикса имя_изменяется_в: детекция мутации по режиму параметра).
cat > сохранить_при_ref_индексе.конда <<'KONDA'
#содержит <stdio.h>

ничего сдвинуть(изменяемый целое32 и) { и = и + 100 }

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> с = выделить(длина(аргументы))
    для целое32 и = 0; и < длина(с); и = и + 1 {
        сдвинуть(и)
        с[и] = 7
    }
    printf("недостижимо\n")
    вернуть 0
}
KONDA
"$BIN" сохранить_при_ref_индексе.конда >"$TMP/сохранить_при_ref_индексе.log" 2>&1 || {
    cat "$TMP/сохранить_при_ref_индексе.log" >&2
    fail "цикл с ref-мутацией индекса должен транспилироваться"
}
grep -q ")срез_доступ(" вывод/сохранить_при_ref_индексе.c || {
    cat вывод/сохранить_при_ref_индексе.c >&2
    fail "ref-мутация индекса («изменяемый») ДОЛЖНА отменять элиминацию границ"
}
./вывод/сохранить_при_ref_индексе.elf a b >/dev/null 2>&1 && rc=0 || rc=$?
assert_eq "134" "$rc" "ref-мутация индекса: выход за границу ловится рантайм-проверкой"

# То же для guard-режима «если (и < длина(с))»: ref-мутация «и» после охранника
# отменяет элиминацию.
cat > сохранить_при_ref_guard.конда <<'KONDA'
#содержит <stdio.h>

ничего сдвинуть(изменяемый неподписанный целое32 и) { и = и + 100 }

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> с = выделить(длина(аргументы))
    неподписанный целое32 и = 0
    если (и < длина(с)) {
        сдвинуть(и)
        с[и] = 7
    } иначе { }
    printf("недостижимо\n")
    вернуть 0
}
KONDA
"$BIN" сохранить_при_ref_guard.конда >"$TMP/сохранить_при_ref_guard.log" 2>&1 || {
    cat "$TMP/сохранить_при_ref_guard.log" >&2
    fail "guard с ref-мутацией индекса должен транспилироваться"
}
grep -q ")срез_доступ(" вывод/сохранить_при_ref_guard.c || {
    cat вывод/сохранить_при_ref_guard.c >&2
    fail "guard: ref-мутация индекса ДОЛЖНА отменять элиминацию границ"
}
./вывод/сохранить_при_ref_guard.elf a b >/dev/null 2>&1 && rc=0 || rc=$?
assert_eq "134" "$rc" "guard ref-мутация: выход за границу ловится рантайм-проверкой"

# Ложных срабатываний нет: вызов ПО ЗНАЧЕНИЮ (printf) в теле цикла НЕ мешает
