# ─── Статические переменные и функции (static) ──────────────────────────────

# Статическая локальная переменная сохраняет значение между вызовами;
# статическая функция → внутренняя связь.
cat > статический_счётчик.конда <<'KONDA'
#содержит <stdio.h>

статический целое32 следующий()
{
    статический целое32 счётчик = 0
    счётчик = счётчик + 1
    вернуть счётчик
}

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 а = следующий()
    целое32 б = следующий()
    целое32 в = следующий()
    printf("%d %d %d\n", а, б, в)
    вернуть 0
}
KONDA

"$BIN" статический_счётчик.конда >"$TMP/статический_счётчик.log" 2>&1 || {
    cat "$TMP/статический_счётчик.log" >&2
    fail "статическая переменная и функция должны транспилироваться"
}
grep -q "static int32_t следующий"  вывод/статический_счётчик.c || { cat вывод/статический_счётчик.c >&2; fail "статическая функция → static"; }
grep -q "static int32_t счётчик"    вывод/статический_счётчик.c || { cat вывод/статический_счётчик.c >&2; fail "статическая переменная → static"; }
assert_eq "1 2 3" "$(./вывод/статический_счётчик.elf)" "static-переменная сохраняет значение между вызовами"

