# ─── Autofree срезов (RAII) ─────────────────────────────────────────────────

# Владеющий срез освобождается в конце функции (free перед возвратом).
cat > автоосвобождение_базовое.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> д = выделить(длина(аргументы) + 5)
    для целое32 и = 0; и < длина(д); и = и + 1 {
        д[и] = и
    }
    printf("%d\n", д[2])
    вернуть 0
}
KONDA

"$BIN" автоосвобождение_базовое.конда >"$TMP/автоосвобождение_базовое.log" 2>&1 || {
    cat "$TMP/автоосвобождение_базовое.log" >&2
    fail "срез с autofree должен транспилироваться"
}
grep -q "free(д.данные)" вывод/автоосвобождение_базовое.c || {
    cat вывод/автоосвобождение_базовое.c >&2
    fail "владеющий срез должен освобождаться (free(д.данные))"
}
assert_eq "1" "$(grep -c 'free(д.данные)' вывод/автоосвобождение_базовое.c)" "срез освобождается ровно один раз"
assert_eq "2" "$(./вывод/автоосвобождение_базовое.elf)" "autofree: программа работает корректно"

# Срез во вложенном блоке освобождается в конце этого блока.
cat > автоосвобождение_блок.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    если (длина(аргументы) > 0) {
        срез<целое32> врем = выделить(длина(аргументы) + 1)
        врем[0] = 7
        printf("%d\n", врем[0])
    }
    printf("после\n")
    вернуть 0
}
KONDA

"$BIN" автоосвобождение_блок.конда >"$TMP/автоосвобождение_блок.log" 2>&1 || {
    cat "$TMP/автоосвобождение_блок.log" >&2
    fail "срез во вложенном блоке должен транспилироваться"
}
# free(врем.данные) должен стоять внутри блока «если», до printf("после").
grep -q "free(врем.данные)" вывод/автоосвобождение_блок.c || {
    cat вывод/автоосвобождение_блок.c >&2
    fail "срез вложенного блока должен освобождаться в конце блока"
}
assert_eq "7" "$(./вывод/автоосвобождение_блок.elf x | head -n1)" "autofree вложенного блока: вывод"

# Параметр-срез заимствуется: внутри функции не освобождается (владелец снаружи).
cat > автоосвобождение_заимствование.конда <<'KONDA'
#содержит <stdio.h>

целое32 сумма_среза(срез<целое32> с)
{
    целое32 итог = 0
    для целое32 и = 0; и < длина(с); и = и + 1 {
        итог = итог + с[и]
    }
    вернуть итог
}

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> д = выделить(3)
    д[0] = 10
    д[1] = 20
    д[2] = 30
    printf("%d\n", сумма_среза(д))
    вернуть 0
}
KONDA

"$BIN" автоосвобождение_заимствование.конда >"$TMP/автоосвобождение_заимствование.log" 2>&1 || {
    cat "$TMP/автоосвобождение_заимствование.log" >&2
    fail "заимствование среза должно транспилироваться"
}
# В теле сумма_среза параметр не владеет → ни одного free. Якорим паттерн на
# начало строки определения (вызов в main идёт с отступом и не совпадёт).
sed -n '/^int32_t сумма_среза/,/^}/p' вывод/автоосвобождение_заимствование.c | grep -q "free(" && {
    cat вывод/автоосвобождение_заимствование.c >&2
    fail "параметр-срез не должен освобождаться (заимствование)"
}
assert_eq "60" "$(./вывод/автоосвобождение_заимствование.elf)" "заимствование: владелец освобождает, функция нет"

# Перемещение владения (move): «срез б = а» — данные не копируются, владельцем
# становится б, освобождается ровно один раз (источник а больше не free).
cat > перемещение_базовое.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> а = выделить(3)
    а[0] = 11
    срез<целое32> б = а
    printf("%d\n", б[0])
    вернуть 0
}
KONDA

"$BIN" перемещение_базовое.конда >"$TMP/перемещение_базовое.log" 2>&1 || {
    cat "$TMP/перемещение_базовое.log" >&2
    fail "перемещение среза должно транспилироваться"
}
grep -q "Срез б = а;" вывод/перемещение_базовое.c || {
    cat вывод/перемещение_базовое.c >&2
    fail "move должен копировать дескриптор (Срез б = а)"
}
assert_eq "1" "$(grep -c 'free(' вывод/перемещение_базовое.c)" "после move освобождается ровно один владелец"
