# Возврат среза наружу: функция передаёт владение вызывающему. Внутри функции
# возвращаемый срез не освобождается, у вызывающего — освобождается один раз.
cat > срез_возврат.конда <<'KONDA'
#содержит <stdio.h>

срез<целое32> создать(целое32 н)
{
    срез<целое32> р = выделить(н)
    вернуть р
}

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> д = создать(4)
    для целое32 и = 0; и < длина(д); и = и + 1 {
        д[и] = и + 1
    }
    целое32 сумма = 0
    для целое32 и = 0; и < длина(д); и = и + 1 {
        сумма = сумма + д[и]
    }
    printf("%d\n", сумма)
    вернуть 0
}
KONDA

"$BIN" срез_возврат.конда >"$TMP/срез_возврат.log" 2>&1 || {
    cat "$TMP/срез_возврат.log" >&2
    fail "возврат среза из функции должен транспилироваться"
}
