    cat вывод/срез_возврат.c >&2
    fail "функция должна возвращать тип Срез"
}
# Внутри создать возвращаемый срез не освобождается (владение уходит наружу).
sed -n '/^Срез создать/,/^}/p' вывод/срез_возврат.c | grep -q "free(" && {
    cat вывод/срез_возврат.c >&2
    fail "возвращаемый срез не должен освобождаться внутри функции"
}
# У вызывающего срез освобождается ровно один раз.
assert_eq "1" "$(grep -c 'free(д.данные)' вывод/срез_возврат.c)" "принятый срез освобождается один раз"
assert_eq "10" "$(./вывод/срез_возврат.elf)" "возврат среза: сумма 1..4"

