# Функция-потребитель: «владеет»-параметр забирает владение. Функция сама
# освобождает срез, а у вызывающего после передачи его освобождать не нужно.
cat > потребитель.конда <<'KONDA'
#содержит <stdio.h>

целое32 поглотить(владеет срез<целое32> с)
{
    вернуть с[0]
}

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> д = выделить(3)
    д[0] = 77
    целое32 р = поглотить(д)
    printf("%d\n", р)
    вернуть 0
}
KONDA

"$BIN" потребитель.конда >"$TMP/потребитель.log" 2>&1 || {
    cat "$TMP/потребитель.log" >&2
    fail "функция-потребитель должна транспилироваться"
}
# Потребитель освобождает переданный срез внутри себя.
sed -n '/^int32_t поглотить/,/^}/p' вывод/потребитель.c | grep -q "free(с.данные)" || {
    cat вывод/потребитель.c >&2
    fail "«владеет»-параметр должен освобождаться внутри функции"
}
# У вызывающего срез перемещён — повторного free нет.
sed -n '/int32_t main/,/^}/p' вывод/потребитель.c | grep -q "free(д.данные)" && {
    cat вывод/потребитель.c >&2
    fail "после передачи во «владеет»-параметр вызывающий не должен освобождать срез"
}
assert_eq "77" "$(./вывод/потребитель.elf)" "функция-потребитель: вывод"

