# Передача владельца из объемлющей области во «владеет»-параметр ВНУТРИ цикла
# запрещена: на втором витке источник уже перемещён → use-after-free.
# (Регресс: раньше ловился только move-через-присваивание «срез б = а», а
# move-через-вызов-потребитель в цикле проскакивал → двойной free.)
cat > потребитель_перемещение_в_цикле.конда <<'KONDA'
#содержит <stdio.h>

целое32 поглотить(владеет срез<целое32> с)
{
    вернуть с[0]
}

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> а = выделить(2)
    для целое32 и = 0; и < 3; и = и + 1 {
        поглотить(а)
    }
    вернуть 0
}
KONDA

if "$BIN" потребитель_перемещение_в_цикле.конда >"$TMP/потребитель_перемещение_в_цикле.log" 2>&1; then
    cat "$TMP/потребитель_перемещение_в_цикле.log" >&2
    fail "передача владельца в потребитель внутри цикла должна быть ошибкой"
fi
grep -q "внутри цикла запрещено" "$TMP/потребитель_перемещение_в_цикле.log" || {
    cat "$TMP/потребитель_перемещение_в_цикле.log" >&2
    fail "ошибка перемещения в потребитель внутри цикла должна объяснять причину"
}

# То же для «пока».
cat > потребитель_перемещение_в_пока.конда <<'KONDA'
#содержит <stdio.h>

целое32 поглотить(владеет срез<целое32> с)
{
    вернуть с[0]
}

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> а = выделить(2)
    пока (длина(аргументы) > 100) {
        поглотить(а)
    }
    вернуть 0
}
KONDA

if "$BIN" потребитель_перемещение_в_пока.конда >"$TMP/потребитель_перемещение_в_пока.log" 2>&1; then
    cat "$TMP/потребитель_перемещение_в_пока.log" >&2
    fail "передача владельца в потребитель внутри пока должна быть ошибкой"
fi
grep -q "из объемлющей области внутри цикла" "$TMP/потребитель_перемещение_в_пока.log" || { cat "$TMP/потребитель_перемещение_в_пока.log" >&2; fail "потребитель_перемещение_в_пока: ожидалась конкретная диагностика, не любая ошибка"; }

# Нет ложного срабатывания: срез, объявленный ВНУТРИ тела цикла, можно отдавать
# потребителю — на каждом витке создаётся новый владелец.
cat > потребитель_внутренний_в_цикле.конда <<'KONDA'
#содержит <stdio.h>

целое32 поглотить(владеет срез<целое32> с)
{
    вернуть с[0]
}

целое32 точка_входа(срез<символ*> аргументы)
{
    для целое32 и = 0; и < 2; и = и + 1 {
        срез<целое32> а = выделить(2)
        поглотить(а)
    }
    вернуть 0
}
KONDA

"$BIN" потребитель_внутренний_в_цикле.конда >"$TMP/потребитель_внутренний_в_цикле.log" 2>&1 || {
