}

# ─── Пользовательские структуры ─────────────────────────────────────────────

# Объявление структуры, доступ к полям (чтение/запись), зануление по умолчанию.
cat > структура_базовая.конда <<'KONDA'
#содержит <stdio.h>

структура Точка {
    целое32 х
    целое32 у
}

целое32 точка_входа(срез<символ*> аргументы)
{
    Точка п
    п.х = 3
    п.у = 4
    printf("%d %d\n", п.х, п.у)
    вернуть 0
}
KONDA

"$BIN" структура_базовая.конда >"$TMP/структура_базовая.log" 2>&1 || {
    cat "$TMP/структура_базовая.log" >&2
    fail "базовая структура должна транспилироваться"
}
grep -q "typedef struct {" вывод/структура_базовая.c || {
    cat вывод/структура_базовая.c >&2
    fail "структура должна давать typedef struct"
}
grep -q "Точка п = {0}" вывод/структура_базовая.c || {
    cat вывод/структура_базовая.c >&2
    fail "переменная-структура должна зануляться"
}
assert_eq "3 4" "$(./вывод/структура_базовая.elf)" "доступ к полям структуры"

# Вложенные структуры и передача структуры в функцию (по значению).
cat > структура_вложенная.конда <<'KONDA'
#содержит <stdio.h>

структура Точка {
    целое32 х
    целое32 у
}

структура Отрезок {
    Точка начало
    Точка конец
}

целое32 сумма_координат(Точка п)
{
    вернуть п.х + п.у
}

целое32 точка_входа(срез<символ*> аргументы)
{
    Отрезок о
    о.начало.х = 1
    о.конец.у = 5
    Точка т
    т.х = 10
    т.у = 20
    printf("%d %d %d\n", о.начало.х, о.конец.у, сумма_координат(т))
    вернуть 0
}
KONDA

"$BIN" структура_вложенная.конда >"$TMP/структура_вложенная.log" 2>&1 || {
    cat "$TMP/структура_вложенная.log" >&2
    fail "вложенные структуры должны транспилироваться"
}
assert_eq "1 5 30" "$(./вывод/структура_вложенная.elf)" "вложенные структуры и параметр-структура"

