# ─── 2D-массивы «T a[N][M]» (v1: доказано-безопасный индекс, элемент-примитив)
# Обе размерности идут в C нативно; границы обоих измерений проверяет семантика
# (константа + канонический счётчик цикла). 2D структур пока не поддержан.
cat > массив_2d.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 сетка[2][3] = { { 1, 2, 3 }, { 4, 5, 6 } }
    целое32 сумма = 0
    для целое32 и = 0; и < 2; и = и + 1 {
        для целое32 к = 0; к < 3; к = к + 1 {
            сумма = сумма + сетка[и][к]
        }
    }
    printf("%d %d\n", сумма, сетка[1][2])
    вернуть 0
}
KONDA
"$BIN" массив_2d.конда >"$TMP/м2d.log" 2>&1 || {
    cat "$TMP/м2d.log" >&2; fail "2D-массив должен транспилироваться"; }
grep -q "int32_t сетка\[2\]\[3\]" вывод/массив_2d.c || {
    cat вывод/массив_2d.c >&2; fail "2D-массив → C «int32_t g[2][3]»"; }
assert_eq "21 6" "$(./вывод/массив_2d.elf)" "2D init + вложенный цикл + константный индекс"

# Константный OOB — статическая ошибка.
cat > массив_2d_oob.конда <<'KONDA'
целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 g[2][3]
    g[2][0] = 1
    вернуть 0
}
KONDA
if "$BIN" массив_2d_oob.конда >"$TMP/м2doob.log" 2>&1; then
    fail "константный OOB в 2D-массиве должен быть ошибкой компиляции"
fi
grep -q "индекс 2 вне границ" "$TMP/м2doob.log" || {
    cat "$TMP/м2doob.log" >&2; fail "OOB-сообщение должно быть понятным"; }

# Динамический индекс 2D — рантайм-проверка обеих осей (массив_доступ_2d),
# OOB даёт чистую панику «выход за границы 2D-массива» (SIGABRT, не segfault).
cat > массив_2d_дин.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 g[2][3] = { { 10, 20, 30 }, { 40, 50, 60 } }
    целое32 к = длина(аргументы)
    printf("%d\n", g[0][к])
    вернуть 0
}
KONDA
"$BIN" массив_2d_дин.конда >"$TMP/м2dд.log" 2>&1 || {
    cat "$TMP/м2dд.log" >&2; fail "2D с динамическим индексом должно транспилироваться"; }
grep -q "массив_доступ_2d" вывод/массив_2d_дин.c || {
    cat вывод/массив_2d_дин.c >&2; fail "динам. 2D-индекс должен идти через массив_доступ_2d"; }
assert_eq "20" "$(./вывод/массив_2d_дин.elf)" "динам. 2D-индекс: g[0][1] = 20 (arg-count=1)"
# OOB: 7 аргументов → к=7 → выход за границу → чистая паника.
./вывод/массив_2d_дин.elf a b c d e >/dev/null 2>"$TMP/м2dд.err" && rc=0 || rc=$?
assert_eq "134" "$rc" "OOB 2D-массива → SIGABRT (не segfault)"
grep -q "выход за границы 2D-массива" "$TMP/м2dд.err" || {
    cat "$TMP/м2dд.err" >&2; fail "рантайм-сообщение о границе 2D должно быть понятным"; }

# 2D массив структур — поддержан: доступ «м[i][j].поле».
