{
    Т м[2][2] = { { { x=1, y=2 }, { x=3, y=4 } }, { { x=5, y=6 }, { x=7, y=8 } } }
    printf("%d %d\n", м[1][0].x, м[1][1].y)
    вернуть 0
}
KONDA
"$BIN" массив_2d_структ.конда >"$TMP/м2dс.log" 2>&1 || {
