assert_eq "5 8" "$(./вывод/массив_2d_структ.elf)" "2D-массив структур: доступ через поле"

# ─── Массив структур «Точка пс[N]» (v1: элемент без владеющих полей) ─────────
# Индексация/поле через ту же машинерию, что примитивные массивы (границы) +
# индекс типа элемента. Литерал массива struct-литералов, доступ по динам. индексу.
cat > массив_структур.конда <<'KONDA'
#содержит <stdio.h>

структура Предмет { целое32 ид; целое32 очки }

целое32 точка_входа(срез<символ*> аргументы)
{
    Предмет пс[3] = { { ид = 1, очки = 10 }, { ид = 2, очки = 20 }, { ид = 3, очки = 30 } }
    целое32 сумма = 0
    для целое32 и = 0; и < 3; и = и + 1 {
        сумма = сумма + пс[и].очки
    }
    Предмет ещё[2]
    ещё[0].ид = 7
    printf("%d %d %d\n", сумма, пс[1].ид, ещё[0].ид)
    вернуть 0
}
KONDA
"$BIN" массив_структур.конда >"$TMP/массив_структур.log" 2>&1 || {
    cat "$TMP/массив_структур.log" >&2; fail "массив структур должен транспилироваться"; }
grep -q "Предмет пс\[3\]" вывод/массив_структур.c || {
    cat вывод/массив_структур.c >&2; fail "массив структур → C «Предмет пс[3]»"; }
assert_eq "60 2 7" "$(./вывод/массив_структур.elf)" "массив структур: init + индексация работают"

# Границы массива структур: динамический выход за пределы → чистая паника.
