# ─── Деструкторы структур (RAII) ────────────────────────────────────────────

# «[удалить = f]» — деструктор вызывается автоматически в конце области.
cat > деструктор_базовый.конда <<'KONDA'
#содержит <stdio.h>

[удалить = закрыть]
структура Ресурс {
    целое32 дескриптор
}

целое32 закрыть(Ресурс* р)
{
    printf("закрыто %d\n", р.дескриптор)
    вернуть 0
}

целое32 точка_входа(срез<символ*> аргументы)
{
    Ресурс р
    р.дескриптор = 42
    printf("работа\n")
    вернуть 0
}
KONDA

"$BIN" деструктор_базовый.конда >"$TMP/деструктор_базовый.log" 2>&1 || {
    cat "$TMP/деструктор_базовый.log" >&2
    fail "структура с деструктором должна транспилироваться"
}
grep -q "закрыть(&р)" вывод/деструктор_базовый.c || {
    cat вывод/деструктор_базовый.c >&2
    fail "деструктор должен вызываться (закрыть(&р))"
}
assert_eq "работа"     "$(./вывод/деструктор_базовый.elf | head -n1)" "тело до деструктора"
assert_eq "закрыто 42" "$(./вывод/деструктор_базовый.elf | tail -n1)" "деструктор вызван в конце области"

# Доступ к полю через указатель: «.» транслируется в «->».
grep -q "р->дескриптор" вывод/деструктор_базовый.c || {
    cat вывод/деструктор_базовый.c >&2
    fail "доступ к полю через указатель должен давать «->»"
}

# Деструктор во вложенном блоке вызывается в конце этого блока.
cat > деструктор_блок.конда <<'KONDA'
#содержит <stdio.h>

[удалить = освободить_р]
структура Р {
    целое32 значение
}

целое32 освободить_р(Р* р)
{
    printf("drop %d\n", р.значение)
    вернуть 0
}

целое32 точка_входа(срез<символ*> аргументы)
{
    если (длина(аргументы) > 0) {
        Р врем
        врем.значение = 7
        printf("в блоке\n")
    }
    printf("после блока\n")
    вернуть 0
}
KONDA

"$BIN" деструктор_блок.конда >"$TMP/деструктор_блок.log" 2>&1 || {
    cat "$TMP/деструктор_блок.log" >&2
    fail "структура с деструктором во вложенном блоке должна транспилироваться"
}
assert_eq "в блоке"     "$(./вывод/деструктор_блок.elf x | head -n1)" "тело блока"
assert_eq "drop 7"      "$(./вывод/деструктор_блок.elf x | head -n2 | tail -n1)" "деструктор в конце блока"
assert_eq "после блока" "$(./вывод/деструктор_блок.elf x | tail -n1)" "после блока — деструктор уже вызван"

# Несколько структур с деструкторами освобождаются в обратном порядке.
cat > деструктор_порядок.конда <<'KONDA'
#содержит <stdio.h>

[удалить = дроп]
структура Кусок {
    целое32 ном
}

целое32 дроп(Кусок* к)
{
    printf("дроп %d\n", к.ном)
    вернуть 0
}

целое32 точка_входа(срез<символ*> аргументы)
{
    Кусок а
    а.ном = 1
    Кусок б
    б.ном = 2
    вернуть 0
}
KONDA

