# Транзитивная деструкция на большой глубине вложенности структур (регрессия:
# раньше recursion был жёстко ограничен «глубина > 16», и деструктор на дне
# цепочки длиннее 16 уровней молча пропускался кодогеном — утечка ресурса без
# единой диагностики). Строим цепочку У0..У20 (глубина 21 > старого лимита 16);
# У0 несёт деструктор. Верная транзитивная деструкция должна его вызвать.
{
    printf '#содержит <stdio.h>\n'
    printf '[удалить = дроп_глубокий]\n'
    printf 'структура У0 {\n    целое32 в\n}\n'
    printf 'целое32 дроп_глубокий(У0* с)\n{\n    printf("дроп\\n")\n    вернуть 0\n}\n'
    i=1
    while [ "$i" -le 20 ]; do
        prev=$((i - 1))
        printf 'структура У%d {\n    У%d внутр\n}\n' "$i" "$prev"
        i=$((i + 1))
    done
    printf '\nцелое32 точка_входа(срез<символ*> аргументы)\n{\n'
    printf '    У20 верх\n    printf("тело\\n")\n    вернуть 0\n}\n'
} > деструктор_глубокая_вложенность.конда

"$BIN" деструктор_глубокая_вложенность.конда >"$TMP/деструктор_глубокая_вложенность.log" 2>&1 || {
    cat "$TMP/деструктор_глубокая_вложенность.log" >&2
    fail "структура с глубокой вложенностью (21 уровень) должна транспилироваться"
}
printf 'тело\nдроп\n' > "$TMP/деструктор_глубокая_вложенность.ожид"
./вывод/деструктор_глубокая_вложенность.elf > "$TMP/деструктор_глубокая_вложенность.вывод"
if ! cmp -s "$TMP/деструктор_глубокая_вложенность.вывод" "$TMP/деструктор_глубокая_вложенность.ожид"; then
    cat "$TMP/деструктор_глубокая_вложенность.вывод" >&2
    fail "деструктор на глубине 21 должен вызываться (был бы пропущен при старом лимите глубины 16)"
fi

