# ─── Авто-конверсия массива в срез при передаче в функцию ───────────────────

# Базовый сценарий: «сумма(срез<целое32>)» вызывается с массивом «целое32[N]».
# На месте вызова кодоген должен построить дескриптор {данные, длина};
# размер элемента в дескрипторе не хранится (известен статически), массив
# остаётся на стеке, аллокаций нет.
cat > конверсия_базовая.конда <<'KONDA'
#содержит <stdio.h>

целое32 сумма(срез<целое32> с)
{
    целое32 итог = 0
    для целое32 и = 0; и < длина(с); и = и + 1 {
        итог = итог + с[и]
    }
    вернуть итог
}

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 а[5] = { 1, 2, 3, 4, 5 }
    printf("%d\n", сумма(а))
    вернуть 0
}
KONDA

"$BIN" конверсия_базовая.конда >"$TMP/конверсия_базовая.log" 2>&1 || {
    cat "$TMP/конверсия_базовая.log" >&2
    fail "массив должен авто-конвертироваться в срез на вызове"
}
grep -q "(Срез){ \.данные = а, \.длина = 5 }" вывод/конверсия_базовая.c || {
    cat вывод/конверсия_базовая.c >&2
    fail "кодоген должен строить compound-literal Срез из массива"
}
# Никаких аллокаций на месте вызова — массив на стеке. Проверяем тело main.
if awk '/int32_t main/,/^}/' вывод/конверсия_базовая.c | grep -q "срез_выделить\|calloc\|malloc"; then
    cat вывод/конверсия_базовая.c >&2
    fail "авто-конверсия не должна выделять память"
fi
assert_eq "15" "$(./вывод/конверсия_базовая.elf)" "сумма массива через срез-параметр"

