# Массив → сырой указательный параметр известной функции ЗАПРЕЩЁН: decay теряет
# длину, а в теле возможен выход за границы без проверки (безопасность). Нужен
# срез<T> (или используйте C-функцию — у неё нет сигнатуры, decay сохраняется).
cat > конверсия_в_указатель_запрещена.конда <<'KONDA'
#содержит <stdio.h>

целое32 первый(целое32* п)
{
    вернуть п[100]
}

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 а[3] = { 7, 8, 9 }
    printf("%d\n", первый(а))
    вернуть 0
}
KONDA

if "$BIN" конверсия_в_указатель_запрещена.конда >"$TMP/конверсия_в_указатель_запрещена.log" 2>&1; then
    cat "$TMP/конверсия_в_указатель_запрещена.log" >&2
    fail "передача массива в сырой указательный параметр должна быть ошибкой"
fi
grep -q "теряет длину" "$TMP/конверсия_в_указатель_запрещена.log" || {
    cat "$TMP/конверсия_в_указатель_запрещена.log" >&2
    fail "ошибка decay массива в указатель должна предлагать «срез<T>»"
}

