    вернуть 0
}
KONDA

"$BIN" конверсия_через_срез.конда >"$TMP/конверсия_через_срез.log" 2>&1 || {
    cat "$TMP/конверсия_через_срез.log" >&2
    fail "передача массива в срез-параметр должна компилироваться"
}
assert_eq "7" "$(./вывод/конверсия_через_срез.elf)" "массив → срез-параметр: безопасно"

# Срез-параметр + срез-аргумент работает по-прежнему (не сломан).
cat > конверсия_срез_аргумент.конда <<'KONDA'
#содержит <stdio.h>

целое32 первый(срез<целое32> с)
{
    вернуть с[0]
}

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> д = выделить(2)
    д[0] = 42
    printf("%d\n", первый(д))
    вернуть 0
}
KONDA

"$BIN" конверсия_срез_аргумент.конда >"$TMP/конверсия_срез_аргумент.log" 2>&1 || {
    cat "$TMP/конверсия_срез_аргумент.log" >&2
    fail "обычная передача среза в срез-параметр должна по-прежнему работать"
}
# В compound literal заворачиваться срез не должен — передаётся как есть.
if grep -q "(Срез){ \.данные = д" вывод/конверсия_срез_аргумент.c; then
    cat вывод/конверсия_срез_аргумент.c >&2
    fail "срез-переменная не должна заворачиваться в (Срез){…}"
fi
assert_eq "42" "$(./вывод/конверсия_срез_аргумент.elf)" "срез-параметр + срез-аргумент"

# ─── Path-sensitive move владения (если/иначе + sink-вернуть, запрет в цикле) ─

# Симметричный move в обеих ветвях если/иначе: разрешён, после if владение
# одинаково перемещено в обоих случаях → autofree корректен.
cat > перемещение_обе_ветви.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> а = выделить(2)
    а[0] = 7
    если (длина(аргументы) > 1) {
        срез<целое32> б = а
        printf("тогда %d\n", б[0])
    } иначе {
        срез<целое32> в = а
        printf("иначе %d\n", в[0])
    }
    вернуть 0
}
KONDA

"$BIN" перемещение_обе_ветви.конда >"$TMP/перемещение_обе_ветви.log" 2>&1 || {
    cat "$TMP/перемещение_обе_ветви.log" >&2
    fail "симметричный move в обеих ветвях должен компилироваться"
}
assert_eq "иначе 7" "$(./вывод/перемещение_обе_ветви.elf)" "ветвь иначе: владение перешло в в"
assert_eq "тогда 7" "$(./вывод/перемещение_обе_ветви.elf x)" "ветвь тогда: владение перешло в б"

# Асимметричный move (в одной ветви — да, в другой — нет): ошибка компиляции
# с понятной диагностикой про двусмысленное освобождение.
cat > перемещение_одна_ветвь.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> а = выделить(2)
    если (длина(аргументы) > 1) {
        срез<целое32> б = а
        printf("%d\n", б[0])
    }
    вернуть 0
}
KONDA

if "$BIN" перемещение_одна_ветвь.конда >"$TMP/перемещение_одна_ветвь.log" 2>&1; then
    cat "$TMP/перемещение_одна_ветвь.log" >&2
    fail "асимметричный move должен быть ошибкой компиляции"
fi
grep -q "перемещён в одной ветви" "$TMP/перемещение_одна_ветвь.log" || {
    cat "$TMP/перемещение_одна_ветвь.log" >&2
    fail "ошибка асимметричного move должна называть несовместимость ветвей"
}

# Sink-вернуть: ветвь, которая безусловно возвращает, не вливается в merge.
# Move в такой ветви — корректно, после if срез всё ещё жив для fallthrough.
cat > перемещение_сток_возврат.конда <<'KONDA'
#содержит <stdio.h>

целое32 потребить(владеет срез<целое32> с)
{
    вернуть 0
}

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> а = выделить(2)
    а[0] = 11
    если (длина(аргументы) > 1) {
        потребить(а)
        вернуть 0
    }
    printf("после if %d\n", а[0])
    вернуть 0
}
KONDA

"$BIN" перемещение_сток_возврат.конда >"$TMP/перемещение_сток_возврат.log" 2>&1 || {
    cat "$TMP/перемещение_сток_возврат.log" >&2
    fail "sink-вернуть в ветви должен сниматься с merge"
}
assert_eq "после if 11" "$(./вывод/перемещение_сток_возврат.elf)" "fallthrough после if: а жив"
# С аргументом — ветвь с потребить+вернуть, фолбэк не достигается.
assert_eq "" "$(./вывод/перемещение_сток_возврат.elf x)" "ветвь с потребить+вернуть: ничего не печатает"

# Move источника из объемлющей области ВНУТРИ цикла — запрещён: на втором
# витке источник уже перемещён → use-after-move; статический однопроходный
# анализ это безопасно не разрешит.
cat > перемещение_в_цикле.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> а = выделить(2)
    для целое32 и = 0; и < 1; и = и + 1 {
        срез<целое32> б = а
    }
    вернуть 0
}
KONDA

if "$BIN" перемещение_в_цикле.конда >"$TMP/перемещение_в_цикле.log" 2>&1; then
    cat "$TMP/перемещение_в_цикле.log" >&2
    fail "move из объемлющей области в цикле должен быть ошибкой"
fi
grep -q "внутри цикла запрещено" "$TMP/перемещение_в_цикле.log" || {
    cat "$TMP/перемещение_в_цикле.log" >&2
    fail "ошибка move в цикле должна объяснять причину"
}

# То же для пока:
cat > перемещение_в_пока.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> а = выделить(2)
    пока (длина(аргументы) > 100) {
        срез<целое32> б = а
    }
    вернуть 0
}
KONDA

if "$BIN" перемещение_в_пока.конда >"$TMP/перемещение_в_пока.log" 2>&1; then
    cat "$TMP/перемещение_в_пока.log" >&2
    fail "move из объемлющей области в пока должен быть ошибкой"
fi
grep -q "из объемлющей области внутри цикла" "$TMP/перемещение_в_пока.log" || { cat "$TMP/перемещение_в_пока.log" >&2; fail "перемещение_в_пока: ожидалась конкретная диагностика, не любая ошибка"; }

# Move-внутри-цикла собственного среза цикла (объявленного внутри тела) —
# по-прежнему разрешён: новый владелец создаётся на каждом витке.
cat > перемещение_внутреннего_в_цикле.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    для целое32 и = 0; и < 2; и = и + 1 {
        срез<целое32> а = выделить(2)
        срез<целое32> б = а
        б[0] = и
        printf("%d ", б[0])
    }
    printf("\n")
    вернуть 0
}
KONDA

"$BIN" перемещение_внутреннего_в_цикле.конда >"$TMP/перемещение_внутреннего_в_цикле.log" 2>&1 || {
    cat "$TMP/перемещение_внутреннего_в_цикле.log" >&2
    fail "move среза, объявленного внутри тела цикла, должен быть разрешён"
}
assert_eq "0 1 " "$(./вывод/перемещение_внутреннего_в_цикле.elf)" "цикл: 2 витка, владение move OK"

# Диагностика use-after-move называет строку места move.
cat > использование_после_перемещения_строка.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> а = выделить(2)
    срез<целое32> б = а
    printf("%d\n", а[0])
    вернуть 0
}
KONDA

if "$BIN" использование_после_перемещения_строка.конда >"$TMP/использование_после_перемещения_строка.log" 2>&1; then
    cat "$TMP/использование_после_перемещения_строка.log" >&2
    fail "use-after-move должен быть ошибкой"
fi
grep -q "move на строке 6" "$TMP/использование_после_перемещения_строка.log" || {
    cat "$TMP/использование_после_перемещения_строка.log" >&2
    fail "диагностика use-after-move должна называть строку места move"
}

# ─── Multi-file: транспиляция нескольких .конда как одной программы ─────────

# Функция в одном файле, main в другом: семантика видит сигнатуру сразу
# (signature-pass работает на объединённом AST), кодоген эмитит прототип
# в начале сгенерированного C, так что вызов до определения корректен.
cat > файлы_модуль.конда <<'KONDA'
целое32 удвоить(целое32 х)
{
    вернуть х * 2
}
KONDA
cat > файлы_главный.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    printf("%d\n", удвоить(21))
    вернуть 0
}
KONDA

"$BIN" файлы_главный.конда файлы_модуль.конда >"$TMP/файлы.log" 2>&1 || {
    cat "$TMP/файлы.log" >&2
    fail "multi-file: вызов функции из соседнего файла должен работать"
}
# Прототип должен быть до main.
grep -q "^int32_t удвоить(int32_t х);" вывод/файлы_главный.c || {
    cat вывод/файлы_главный.c >&2
    fail "multi-file: forward-прототип отсутствует"
}
assert_eq "42" "$(./вывод/файлы_главный.elf)" "вызов удвоить(21) из соседнего файла → 42"

# Структура объявлена в одном файле, используется в другом: typedef
# выводится один раз (структуры эмитятся раньше прототипов и тел).
cat > файлы_типы.конда <<'KONDA'
структура Точка {
    целое32 х
    целое32 у
}
KONDA
cat > файлы_использует_типы.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    Точка п = { х = 3, у = 4 }
    printf("%d,%d\n", п.х, п.у)
    вернуть 0
}
KONDA

"$BIN" файлы_использует_типы.конда файлы_типы.конда >"$TMP/файлы_типы.log" 2>&1 || {
    cat "$TMP/файлы_типы.log" >&2
    fail "multi-file: структура из соседнего файла должна быть видна"
}
assert_eq "3,4" "$(./вывод/файлы_использует_типы.elf)" "структура из соседнего файла"

# Cross-file generics: обобщённая функция И структура объявлены в одном файле,
# используются в другом. Без cross-file пред-скана имён обобщённых парсер файла-
# потребителя принял бы «максимум<целое32>(…)»/«Пара<целое32> п» за сравнение «<».
# Слияние идёт до мономорфизации, поэтому сам разворот шаблонов уже общий.
cat > обобщ_модуль.конда <<'KONDA'
T максимум<T>(T а, T б)
{
    если (а > б) { вернуть а }
    иначе { вернуть б }
}

структура Пара<T> {
    T первый
    T второй
}
KONDA
cat > обобщ_главный.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 я = максимум<целое32>(3, 9)   // явный тип-аргумент, шаблон в соседнем файле
    целое32 в = максимум(4, 2)             // выведенный, шаблон в соседнем файле
    Пара<целое32> п                        // обобщённая структура из соседнего файла
    п.первый = 100
    п.второй = 200
    printf("%d %d %d\n", я, в, п.первый + п.второй)
    вернуть 0
}
KONDA

"$BIN" обобщ_главный.конда обобщ_модуль.конда >"$TMP/обобщ_файлы.log" 2>&1 || {
    cat "$TMP/обобщ_файлы.log" >&2
    fail "cross-file generics должны транспилироваться"
}
assert_eq "9 4 300" "$(./вывод/обобщ_главный.elf)" \
    "cross-file: обобщённая функция (явная+выведенная) и структура из соседнего файла"

# Порядок файлов не важен (пред-скан имён обобщённых — по всем файлам до разбора).
"$BIN" обобщ_модуль.конда обобщ_главный.конда >"$TMP/обобщ_файлы2.log" 2>&1 || {
    cat "$TMP/обобщ_файлы2.log" >&2
    fail "cross-file generics не должны зависеть от порядка файлов"
}

# Перечисление объявлено в одном файле, используется как тип переменной в
# другом (зеркало теста для структур выше — раньше имена перечислений
# собирались только внутри текущего файла, и «Имя п» с именем перечисления
# из соседнего файла не распознавалось как объявление переменной).
cat > файлы_перечисление.конда <<'KONDA'
перечисление Цвет {
    КРАСНЫЙ
    ЗЕЛЁНЫЙ
    СИНИЙ
}
KONDA
cat > файлы_использует_перечисление.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    Цвет ц = ЗЕЛЁНЫЙ
    если (ц == ЗЕЛЁНЫЙ) {
        printf("зелёный\n")
    }
    вернуть 0
}
KONDA

"$BIN" файлы_использует_перечисление.конда файлы_перечисление.конда \
    >"$TMP/файлы_перечисление.log" 2>&1 || {
    cat "$TMP/файлы_перечисление.log" >&2
    fail "multi-file: перечисление из соседнего файла должно быть видно"
}
assert_eq "зелёный" "$(./вывод/файлы_использует_перечисление.elf)" "перечисление из соседнего файла"

# Порядок файлов не важен и для перечислений (signature-pass не зависит от
# позиции файла в командной строке).
"$BIN" файлы_перечисление.конда файлы_использует_перечисление.конда \
    >"$TMP/файлы_перечисление_перестановка.log" 2>&1 || {
    cat "$TMP/файлы_перечисление_перестановка.log" >&2
    fail "multi-file: порядок файлов не должен влиять на видимость перечисления"
}

# ─── Sum-типы: размеченные перечисления с данными + привязка в «выбор» ───────
# Конструирование варианта, исчерпывающий match с привязкой полей, вариант без
# данных. Кодоген — размеченный союз (tag+union), нулевая рантайм-цена.
cat > sum_базовый.конда <<'KONDA'
#содержит <stdio.h>
перечисление Фигура {
    Круг(вещественное64 радиус)
    Прямоугольник(вещественное64 ширина, вещественное64 высота)
    Пусто
}
вещественное64 площадь(Фигура ф)
{
    выбор ф {
        Круг(р) { вернуть 3.14159 * р * р }
        Прямоугольник(ш, в) { вернуть ш * в }
        Пусто { вернуть 0.0 }
    }
    вернуть 0.0
}
целое32 точка_входа(срез<символ*> аргументы)
{
    Фигура а = Круг(2.0)
    Фигура б = Прямоугольник(3.0, 4.0)
    Фигура в = Пусто
    printf("%.2f %.2f %.2f\n", площадь(а), площадь(б), площадь(в))
    вернуть 0
}
KONDA
"$BIN" sum_базовый.конда >"$TMP/sum_базовый.log" 2>&1 || {
    cat "$TMP/sum_базовый.log" >&2; fail "sum-тип должен транспилироваться"; }
grep -q "int32_t тег" вывод/sum_базовый.c || {
    cat вывод/sum_базовый.c >&2; fail "sum-тип должен давать размеченный союз (tag+union)"; }
assert_eq "12.57 12.00 0.00" "$(./вывод/sum_базовый.elf)" "sum-тип: площадь по вариантам"

# sum-тип не имеет рантайм-цены сверх логики (нет ВЫЗОВОВ проверки среза в switch).
# Пролог среза теперь есть в любой программе с main (argv — срез<символ*>), поэтому
# ищем именно ВЫЗОВ «(T *)срез_доступ(…» (шаблон «)срез_доступ(»), а не определение
# «void *срез_доступ(Срез …» — идиома проекта для «нет доступа к срезу».
grep -q ")срез_доступ(" вывод/sum_базовый.c && {
    cat вывод/sum_базовый.c >&2; fail "sum-тип/выбор не должны добавлять рантайм-проверок"; }

# «выбор» с «_» и без привязки полей (игнор нагрузки) — тоже допустим.
cat > sum_умолчание.конда <<'KONDA'
#содержит <stdio.h>
перечисление Сигнал {
    Данные(целое32 к)
    Стоп
    Старт
}
целое32 точка_входа(срез<символ*> аргументы)
{
    Сигнал с = Стоп
    выбор с {
        Данные(к) { printf("данные %d\n", к) }
        _ { printf("управление\n") }
    }
    вернуть 0
}
KONDA
"$BIN" sum_умолчание.конда >"$TMP/sum_умолчание.log" 2>&1 || {
    cat "$TMP/sum_умолчание.log" >&2; fail "sum-тип с «_» должен транспилироваться"; }
assert_eq "управление" "$(./вывод/sum_умолчание.elf)" "sum-тип: ветка «_»"

# Негатив: неисчерпывающий «выбор» без «_» — ошибка.
cat > sum_неисчерп.конда <<'KONDA'
#содержит <stdio.h>
перечисление Ф {
    Круг(вещественное64 р)
    Пусто
}
целое32 точка_входа(срез<символ*> аргументы)
{
    Ф ф = Пусто
    выбор ф { Круг(р) { printf("%f\n", р) } }
    вернуть 0
}
KONDA
if "$BIN" sum_неисчерп.конда >"$TMP/sum_неисчерп.log" 2>&1; then
    fail "неисчерпывающий выбор sum-типа должен быть ошибкой"
fi
grep -q "не исчерпывающий" "$TMP/sum_неисчерп.log" || {
    cat "$TMP/sum_неисчерп.log" >&2; fail "понятная ошибка исчерпываемости sum-типа"; }

# Негатив: неверное число привязок в ветке.
