# Обычное (C-стиль) перечисление без данных не затронуто — прежнее поведение.
cat > sum_обычный_enum.конда <<'KONDA'
#содержит <stdio.h>
перечисление Цвет {
    Красный
    Зелёный = 5
    Синий
}
целое32 точка_входа(срез<символ*> аргументы)
{
    Цвет ц = Зелёный
