test -f вывод/файлы_модуль.c || fail "имя выхода должно идти от первого .конда-аргумента"

# ─── для_каждого: foreach по срезу/массиву ──────────────────────────────────

# Базовый foreach по срезу: значения копируются (read-only обход).
cat > для_каждого_срез.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> с = выделить(4)
    с[0] = 10
    с[1] = 20
    с[2] = 30
    с[3] = 40
    для_каждого в из с {
        printf("%d ", в)
    }
    printf("\n")
    вернуть 0
}
KONDA

"$BIN" для_каждого_срез.конда >"$TMP/для_каждого_срез.log" 2>&1 || {
    cat "$TMP/для_каждого_срез.log" >&2
    fail "для_каждого по срезу должно компилироваться"
}
# Прямой доступ без рантайм-проверки границ (индекс цикла канонически безопасен).
# Пролог всегда содержит определение срез_доступ; проверяем, что в теле main
# его вызов не появляется.
if awk '/^int32_t main/,/^}/' вывод/для_каждого_срез.c | grep -q "срез_доступ("; then
    cat вывод/для_каждого_срез.c >&2
    fail "для_каждого должен генерировать прямой доступ без рантайм-проверки"
fi
assert_eq "10 20 30 40 " "$(./вывод/для_каждого_срез.elf)" "для_каждого по срезу: все элементы по порядку"

# Zip-«для_каждого» по нескольким срезам + мутация (§56 фаза 2). Десугар в
# «утверждать_равные + канонический цикл»: тело векторизуется (0 срез_доступ).
cat > для_каждого_зип.конда <<'KONDA'
#содержит <stdio.h>

ничего оси(срез<вещественное64> поз, срез<вещественное64> скор, вещественное64 dt)
{
    для_каждого изменяемый п из поз, с из скор {
        п = п + с * dt
    }
}

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<вещественное64> п = выделить(3)
    срез<вещественное64> с = выделить(3)
    для_каждого изменяемый э из с { э = 2.0 }
    оси(п, с, 10.0)
    вещественное64 сум = 0.0
    для_каждого a из п { сум = сум + a }
    printf("%.0f\n", сум)
    вернуть 0
}
KONDA
"$BIN" для_каждого_зип.конда >"$TMP/зип.log" 2>&1 || {
    cat "$TMP/зип.log" >&2; fail "zip-для_каждого должно транспилироваться"; }
# Тело zip и одиночной мутации — прямой доступ (нет срез_доступ в теле main/оси).
if grep -q ")срез_доступ(" вывод/для_каждого_зип.c; then
    grep -n "срез_доступ(" вывод/для_каждого_зип.c >&2
    fail "zip-для_каждого: тело должно быть прямым (нет срез_доступ)"
fi
# п = 0 + 2*10 = 20 на каждый из 3 → сумма 60.
assert_eq "60" "$(./вывод/для_каждого_зип.elf)" "zip-для_каждого: мутация+редукция считают верно"

# Запись в связь БЕЗ «изменяемый» — ошибка (гейт мутации).
cat > зип_ro_гейт.конда <<'KONDA'
целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> a = выделить(3)
    срез<целое32> b = выделить(3)
    для_каждого x из a, y из b { x = y }
    вернуть 0
}
KONDA
if "$BIN" зип_ro_гейт.конда >"$TMP/зипгейт.log" 2>&1; then
    fail "запись в read-only связь zip должна быть ошибкой"
fi
grep -q "требует «изменяемый»" "$TMP/зипгейт.log" \
    || { cat "$TMP/зипгейт.log" >&2; fail "гейт мутации zip должен требовать «изменяемый»"; }

