# ─── Статические UB-проверки операторов ─────────────────────────────────────

# Сдвиг на число бит вне разрядности типа — ошибка компиляции.
cat > сдвиг_вне_диапазона.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 х = 1 << 40
    printf("%d\n", х)
    вернуть 0
}
KONDA

if "$BIN" сдвиг_вне_диапазона.конда >"$TMP/сдвиг_вне_диапазона.log" 2>&1; then
    cat "$TMP/сдвиг_вне_диапазона.log" >&2
    fail "сдвиг на число бит вне разрядности должен быть ошибкой"
fi
grep -q "сдвиг на 40 бит вне диапазона" "$TMP/сдвиг_вне_диапазона.log" || {
    cat "$TMP/сдвиг_вне_диапазона.log" >&2
    fail "ошибка сдвига вне диапазона должна быть понятной"
}

# Корректный сдвиг в пределах разрядности — компилируется и сворачивается.
cat > сдвиг_ок.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 х = 1 << 4
    printf("%d\n", х)
    вернуть 0
}
KONDA

"$BIN" сдвиг_ок.конда >"$TMP/сдвиг_ок.log" 2>&1 || {
    cat "$TMP/сдвиг_ок.log" >&2
    fail "корректный сдвиг должен компилироваться"
}
assert_eq "16" "$(./вывод/сдвиг_ок.elf)" "1 << 4 = 16"

# Переполнение константного выражения относительно типа результата — ошибка.
cat > константное_переполнение.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 х = 2000000000 + 2000000000
    printf("%d\n", х)
    вернуть 0
}
KONDA

if "$BIN" константное_переполнение.конда >"$TMP/константное_переполнение.log" 2>&1; then
    cat "$TMP/константное_переполнение.log" >&2
    fail "переполнение константного выражения должно быть ошибкой"
fi
grep -q "переполнение в константном выражении" "$TMP/константное_переполнение.log" || {
    cat "$TMP/константное_переполнение.log" >&2
    fail "ошибка константного переполнения должна быть понятной"
}

# Свёрнутый индекс через сдвиг проверяется на границы массива.
cat > индекс_сдвиг_вне_границ.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 а[2]
    а[1 << 4] = 1
    вернуть 0
}
KONDA

if "$BIN" индекс_сдвиг_вне_границ.конда >"$TMP/индекс_сдвиг_вне_границ.log" 2>&1; then
    cat "$TMP/индекс_сдвиг_вне_границ.log" >&2
    fail "свёрнутый сдвигом индекс за границей массива должен быть ошибкой"
fi
grep -q "вне границ массива" "$TMP/индекс_сдвиг_вне_границ.log" || { cat "$TMP/индекс_сдвиг_вне_границ.log" >&2; fail "индекс_сдвиг_вне_границ: ожидалась конкретная диагностика, не любая ошибка"; }

# ─── выделить: статический overflow + защита аллокации ──────────────────────

# Константное количество, переполняющее размер выделения, — ошибка компиляции.
cat > выделить_переполнение.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> д = выделить(5000000000000000000)
    вернуть 0
}
KONDA

if "$BIN" выделить_переполнение.конда >"$TMP/выделить_переполнение.log" 2>&1; then
    cat "$TMP/выделить_переполнение.log" >&2
    fail "переполнение размера выделения должно быть ошибкой"
fi
grep -q "размер выделения переполняется" "$TMP/выделить_переполнение.log" || {
    cat "$TMP/выделить_переполнение.log" >&2
    fail "ошибка переполнения выделения должна быть понятной"
}

# В прологе срезов есть проверка неудачи аллокации (детерминированный abort).
cat > выделить_защита.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> д = выделить(3)
    д[0] = 1
    printf("%d\n", д[0])
    вернуть 0
}
KONDA

"$BIN" выделить_защита.конда >"$TMP/выделить_защита.log" 2>&1 || {
    cat "$TMP/выделить_защита.log" >&2
    fail "обычное выделение должно компилироваться"
}
grep -q "не удалось выделить срез" вывод/выделить_защита.c || {
    cat вывод/выделить_защита.c >&2
    fail "пролог срезов должен содержать проверку неудачи аллокации"
}

# ─── Запрет неявного сужения + явный каст «как<тип>(…)» ─────────────────────

# Неявное сужение непостоянного значения в более узкий тип — ошибка.
cat > сужение_запрещено.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 ш = длина(аргументы)
    целое8 м = ш
    printf("%d\n", м)
    вернуть 0
}
KONDA

if "$BIN" сужение_запрещено.конда >"$TMP/сужение_запрещено.log" 2>&1; then
    cat "$TMP/сужение_запрещено.log" >&2
    fail "неявное сужение непостоянного значения должно быть ошибкой"
fi
grep -q "неявное сужение" "$TMP/сужение_запрещено.log" || {
    cat "$TMP/сужение_запрещено.log" >&2
    fail "ошибка неявного сужения должна предлагать «как<…>»"
}

# Явное приведение «как<целое8>(…)» снимает запрет.
cat > сужение_каст.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 ш = 300
    целое8 м = как<целое8>(ш)
    printf("%d\n", м)
    вернуть 0
}
KONDA

"$BIN" сужение_каст.конда >"$TMP/сужение_каст.log" 2>&1 || {
    cat "$TMP/сужение_каст.log" >&2
    fail "явное приведение должно компилироваться"
}
grep -q "(int8_t)(" вывод/сужение_каст.c || {
    cat вывод/сужение_каст.c >&2
    fail "приведение должно эмитить C-каст (int8_t)"
}
assert_eq "44" "$(./вывод/сужение_каст.elf)" "как<целое8>(300) = 44 (300 mod 256)"

# Расширение (узкий → широкий) не требует приведения.
cat > расширение_ок.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    целое8 а = 5
    целое32 ш = а
    printf("%d\n", ш)
    вернуть 0
}
KONDA

"$BIN" расширение_ок.конда >"$TMP/расширение_ок.log" 2>&1 || {
    cat "$TMP/расширение_ок.log" >&2
    fail "расширение типа не должно требовать приведения"
}
assert_eq "5" "$(./вывод/расширение_ок.elf)" "целое8 → целое32: значение сохранено"

# ─── выбор/match по перечислению с проверкой исчерпываемости ────────────────

# Исчерпывающий выбор по всем вариантам — компилируется в C switch.
cat > выбор_полный.конда <<'KONDA'
#содержит <stdio.h>

перечисление Цвет {
    КРАСНЫЙ
    ЗЕЛЁНЫЙ
    СИНИЙ
}

целое32 точка_входа(срез<символ*> аргументы)
{
    Цвет ц = ЗЕЛЁНЫЙ
    выбор ц {
        КРАСНЫЙ {
            printf("красный\n")
        }
        ЗЕЛЁНЫЙ {
            printf("зелёный\n")
        }
        СИНИЙ {
            printf("синий\n")
        }
    }
    вернуть 0
}
KONDA

"$BIN" выбор_полный.конда >"$TMP/выбор_полный.log" 2>&1 || {
    cat "$TMP/выбор_полный.log" >&2
    fail "исчерпывающий выбор должен компилироваться"
}
grep -q "switch (" вывод/выбор_полный.c || {
    cat вывод/выбор_полный.c >&2
    fail "выбор должен давать C switch"
}
assert_eq "зелёный" "$(./вывод/выбор_полный.elf)" "выбор: выполнилась ветка ЗЕЛЁНЫЙ"

# Не исчерпывающий выбор (пропущен вариант) — ошибка компиляции.
cat > выбор_неполный.конда <<'KONDA'
#содержит <stdio.h>

перечисление Цвет {
    КРАСНЫЙ
    ЗЕЛЁНЫЙ
    СИНИЙ
}

целое32 точка_входа(срез<символ*> аргументы)
{
    Цвет ц = КРАСНЫЙ
    выбор ц {
        КРАСНЫЙ {
            printf("к\n")
        }
        ЗЕЛЁНЫЙ {
            printf("з\n")
        }
    }
    вернуть 0
}
KONDA

if "$BIN" выбор_неполный.конда >"$TMP/выбор_неполный.log" 2>&1; then
    cat "$TMP/выбор_неполный.log" >&2
    fail "не исчерпывающий выбор должен быть ошибкой"
fi
grep -q "не исчерпывающий: не обработан вариант «СИНИЙ»" "$TMP/выбор_неполный.log" || {
    cat "$TMP/выбор_неполный.log" >&2
    fail "ошибка исчерпываемости должна называть пропущенный вариант"
}

# Ветка «_» покрывает остальные варианты.
cat > выбор_умолчание.конда <<'KONDA'
#содержит <stdio.h>

перечисление Цвет {
    КРАСНЫЙ
    ЗЕЛЁНЫЙ
    СИНИЙ
}

целое32 точка_входа(срез<символ*> аргументы)
{
    Цвет ц = СИНИЙ
    выбор ц {
        КРАСНЫЙ {
            printf("к\n")
        }
        _ {
            printf("прочее\n")
        }
    }
    вернуть 0
}
KONDA

"$BIN" выбор_умолчание.конда >"$TMP/выбор_умолчание.log" 2>&1 || {
    cat "$TMP/выбор_умолчание.log" >&2
    fail "выбор с веткой «_» должен компилироваться"
}
assert_eq "прочее" "$(./вывод/выбор_умолчание.elf)" "выбор: ветка «_» для СИНИЙ"

# Вариант чужого перечисления в ветке — ошибка.
cat > выбор_чужой_вариант.конда <<'KONDA'
#содержит <stdio.h>

