# Инициализация во всех ветвях исчерпывающего выбора → переменная инициализирована.
cat > выбор_инициализация.конда <<'KONDA'
#содержит <stdio.h>

перечисление Цвет {
    КРАСНЫЙ
    СИНИЙ
}

целое32 точка_входа(срез<символ*> аргументы)
{
    Цвет ц = СИНИЙ
    целое32 к
    выбор ц {
        КРАСНЫЙ {
            к = 1
        }
        СИНИЙ {
            к = 2
        }
    }
    printf("%d\n", к)
    вернуть 0
}
KONDA

"$BIN" выбор_инициализация.конда >"$TMP/выбор_инициализация.log" 2>&1 || {
    cat "$TMP/выбор_инициализация.log" >&2
    fail "инициализация во всех ветвях выбора должна засчитываться"
}
assert_eq "2" "$(./вывод/выбор_инициализация.elf)" "выбор: к инициализирована в обеих ветвях"

# ─── f-строки (интерполяция в стиле Swift) ──────────────────────────────────

# Встраивание переменной и выражения «\(…)» — как в примере из ТЗ.
cat > fстрока_базовая.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    символ* имя = "Аня"
    целое32 возраст = 25
    символ* прив = "Привет, \(имя). Через год тебе будет \(возраст + 1)."
    printf("%s\n", прив)
    вернуть 0
}
KONDA

"$BIN" fстрока_базовая.конда >"$TMP/fстрока_базовая.log" 2>&1 || {
    cat "$TMP/fстрока_базовая.log" >&2
    fail "f-строка с переменной и выражением должна компилироваться"
}
grep -q "snprintf(" вывод/fстрока_базовая.c || {
    cat вывод/fстрока_базовая.c >&2
    fail "f-строка должна эмитить snprintf"
}
assert_eq "Привет, Аня. Через год тебе будет 26." "$(./вывод/fстрока_базовая.elf)" "f-строка: интерполяция имени и выражения"

# Спецификаторы по типу: символ→%c, вещественное→%f, enum→%d, целое64.
cat > fстрока_типы.конда <<'KONDA'
#содержит <stdio.h>

перечисление Цвет {
    КРАСНЫЙ
    СИНИЙ
}

целое32 точка_входа(срез<символ*> аргументы)
{
    символ с = 65
    Цвет ц = СИНИЙ
    целое64 д = 5
    printf("%s\n", "с=\(с) ц=\(ц) д=\(д)")
    вернуть 0
}
KONDA

"$BIN" fстрока_типы.конда >"$TMP/fстрока_типы.log" 2>&1 || {
    cat "$TMP/fстрока_типы.log" >&2
    fail "f-строка с разными типами должна компилироваться"
}
assert_eq "с=A ц=1 д=5" "$(./вывод/fстрока_типы.elf)" "f-строка: спецификаторы по типу"

# Литеральный «%» в f-строке экранируется (одиночный % печатается как %).
cat > fстрока_процент.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 п = 100
    printf("%s\n", "готово на \(п)%")
    вернуть 0
}
KONDA

"$BIN" fстрока_процент.конда >"$TMP/fстрока_процент.log" 2>&1 || {
    cat "$TMP/fстрока_процент.log" >&2
    fail "f-строка с литеральным «%» должна компилироваться"
}
assert_eq "готово на 100%" "$(./вывод/fстрока_процент.elf)" "f-строка: литеральный процент"

# Вложенные скобки внутри интерполяции разбираются корректно.
cat > fстрока_вложенные.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 х = 3
    printf("%s\n", "(\(х * (х + 1)))")
    вернуть 0
}
KONDA

"$BIN" fстрока_вложенные.конда >"$TMP/fстрока_вложенные.log" 2>&1 || {
    cat "$TMP/fстрока_вложенные.log" >&2
    fail "f-строка с вложенными скобками должна компилироваться"
}
assert_eq "(12)" "$(./вывод/fстрока_вложенные.elf)" "f-строка: вложенные скобки в выражении"

# Срез/структуру интерполировать нельзя — ошибка с позицией f-строки.
cat > fстрока_срез_ошибка.конда <<'KONDA'
