    cat "$TMP/fстрока_срез_ошибка.log" >&2
    fail "ошибка интерполяции среза должна быть понятной"
}

# Обычная строка без «\(…)» по-прежнему передаётся как есть (printf-семантика %%).
cat > fстрока_обычная.конда <<'KONDA'
