# ─── Безопасность: приведения и интерполяция ────────────────────────────────

# Приведение целого к указателю запрещено: иначе можно сфабриковать
# произвольный адрес и разыменовать его (обход всех проверок).
cat > каст_целое_в_указатель.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    целое64 адрес = 4096
    символ* п = как<символ*>(адрес)
    printf("%c\n", п[0])
    вернуть 0
}
KONDA

if "$BIN" каст_целое_в_указатель.конда >"$TMP/каст_целое_в_указатель.log" 2>&1; then
    cat "$TMP/каст_целое_в_указатель.log" >&2
    fail "приведение целого к указателю должно быть ошибкой"
fi
grep -q "фабрикация произвольного указателя" "$TMP/каст_целое_в_указатель.log" || {
    cat "$TMP/каст_целое_в_указатель.log" >&2
    fail "ошибка фабрикации указателя должна быть понятной"
}

