# ─── «аргументы» (argv) — единый срез<символ*> (§36) ────────────────────────

# «аргументы» — обычный срез: «длина(аргументы)» == argc (ВКЛЮЧАЯ имя программы),
# итерация каноническим циклом по срезу (проверка границ элидируется). Проверяем
# синтез среза, элизию в цикле и то, что имя программы входит в срез (argv[0]).
cat > аргументы_срез.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    для целое32 и = 1; и < длина(аргументы); и = и + 1 {
        printf("%s\n", аргументы[и])
    }
    printf("итого:%d\n", длина(аргументы))
    вернуть 0
}
KONDA

"$BIN" аргументы_срез.конда >"$TMP/аргументы_срез.log" 2>&1 || {
    cat "$TMP/аргументы_срез.log" >&2
    fail "аргументы как срез<символ*> должны транспилироваться"
}
# Синтезированный из argc/argv срез с именем параметра.
grep -q "Срез аргументы = { (void \*)argv, (size_t)argc };" вывод/аргументы_срез.c || {
    cat вывод/аргументы_срез.c >&2
    fail "пролог main должен синтезировать Срез аргументы из argc/argv"
}
# Канонический цикл по срезу argv — проверка границ элидируется (нет ВЫЗОВА).
if grep -q ")срез_доступ(" вывод/аргументы_срез.c; then
    cat вывод/аргументы_срез.c >&2
    fail "доступ в каноническом цикле по аргументы не должен нести рантайм-проверку"
fi
# итого==3 (имя программы + два аргумента) подтверждает, что argv[0] в срезе.
assert_eq "x
y
итого:3" "$(./вывод/аргументы_срез.elf x y)" \
    "аргументы: итерация и длина(аргументы)==argc (с именем программы)"

