# ─── Строки: «срез<символ> с = "литерал"» (§37, slice 1) ────────────────────
# Строка = срез<символ> (UTF-8-байты). Литерал → ЗАИМСТВОВАННЫЙ срез над .rodata:
# длина(с) == число БАЙТ (sizeof(лит)-1), NUL сохранён (совместимость с C), не
# владеет (autofree не трогает .rodata), доступ проверяется как у любого среза,
# в каноническом цикле проверка снимается. Единая абстракция среза — новых
# рантайм-проверок для строк нет.
cat > строка_литерал.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<символ> с = "abc"
    printf("%d\n", длина(с))
    для целое32 к = 0; к < длина(с); к = к + 1 {
        printf("%c", с[к])
    }
    printf("\n")
    вернуть 0
}
KONDA

"$BIN" строка_литерал.конда >"$TMP/строка_литерал.log" 2>&1 || {
    cat "$TMP/строка_литерал.log" >&2
    fail "«срез<символ> с = \"литерал\"» должно транспилироваться"
}
# Заимствованный срез над .rodata: данные — сам литерал, длина через sizeof-1.
grep -q '(Срез){ .данные = (void\*)"abc", .длина = sizeof("abc") - 1 }' вывод/строка_литерал.c || {
    cat вывод/строка_литерал.c >&2
    fail "литерал-строка должна давать заимствованный срез (данные=литерал, длина=sizeof-1)"
}
# Borrow: .rodata не освобождается (нет free по этому срезу).
grep -q "free(с" вывод/строка_литерал.c && {
    cat вывод/строка_литерал.c >&2
    fail "строка-литерал заимствована (.rodata) — free недопустим"
}
# Канонический цикл по строке — проверка границ элидируется (нет ВЫЗОВА).
if grep -q ")срез_доступ(" вывод/строка_литерал.c; then
    cat вывод/строка_литерал.c >&2
    fail "доступ в каноническом цикле по строке не должен нести рантайм-проверку"
fi
assert_eq "3
abc" "$(./вывод/строка_литерал.elf)" "строка-литерал: длина==байты, посимвольный обход"

# Длина — в БАЙТАХ UTF-8 (кириллица: 2 байта/символ).
cat > строка_utf8.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
