    printf("%d\n", длина(с))
    вернуть 0
}
KONDA

"$BIN" строка_utf8.конда >"$TMP/строка_utf8.log" 2>&1 || {
    cat "$TMP/строка_utf8.log" >&2
    fail "UTF-8-строка-литерал должна транспилироваться"
}
assert_eq "6" "$(./вывод/строка_utf8.elf)" "длина строки — в байтах UTF-8 (мир=6)"

