# Строка передаётся в функцию как обычный срез<символ>; выход за границы —
# рантайм-проверка среза (длина статически не фиксируется у литерала).
cat > строка_границы.конда <<'KONDA'
#содержит <stdio.h>

символ взять(срез<символ> т, целое32 и)
{
    вернуть т[и]
}

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<символ> с = "ab"
    printf("%c\n", взять(с, 5))
    вернуть 0
}
KONDA

"$BIN" строка_границы.конда >"$TMP/строка_границы.log" 2>&1 || {
    cat "$TMP/строка_границы.log" >&2
    fail "передача строки в функцию должна транспилироваться"
}
