assert_eq "134" "$rc" "выход за границы строки прерывает программу (SIGABRT)"
grep -q "выход за границы среза" "$TMP/строка_границы.err" || {
    cat "$TMP/строка_границы.err" >&2
    fail "рантайм-сообщение о выходе за границы строки — как у среза"
}

# ─── Строки §37, пп.1—4 ─────────────────────────────────────────────────────

# П.1: коэрция литерала на call-site + в присваивании.
# ─ Литерал → срез<символ>-параметр (кодоген строит Срез из литерала).
# ─ Литерал → переприсваивание BORROW-строке (без утечки — заимствованная память
#   не освобождается; провенанс обновляется).
cat > строка_коэрция.конда <<'KONDA'
#содержит <stdio.h>
целое32 длн(срез<символ> с) { вернуть длина(с) }
целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 л1 = длн("abc")            // литерал прямо в вызов
    срез<символ> с = "abc"
    с = "quux"                          // переприсваивание borrow ← литерал
    printf("%d %d\n", л1, длина(с))
    вернуть 0
}
KONDA
"$BIN" строка_коэрция.конда >"$TMP/строка_коэрция.log" 2>&1 || {
    cat "$TMP/строка_коэрция.log" >&2
    fail "коэрция литерала в срез<символ> на call-site/присваивании"
}
assert_eq "3 4" "$(./вывод/строка_коэрция.elf)" "коэрция: длина литерала и переприсваивание"

# П.1 guard: присвоение литерала ВЛАДЕЮЩЕЙ строке — ошибка (утечка + free .rodata).
cat > строка_литерал_в_владеющую.конда <<'KONDA'
целое32 точка_входа(срез<символ*> аргументы)
{
    срез<символ> с = выделить(4)
    с = "abc"
    вернуть 0
}
KONDA
if "$BIN" строка_литерал_в_владеющую.конда >"$TMP/стр_вл.log" 2>&1; then
    fail "литерал → ВЛАДЕЮЩАЯ строка должно быть ошибкой"
fi
grep -qE "нельзя присвоить строковый литерал/f-строку ВЛАДЕЮЩЕМУ" "$TMP/стр_вл.log" || {
    cat "$TMP/стр_вл.log" >&2; fail "ошибка про утечку+free .rodata должна быть понятной"; }

# П.6: возврат литерала как срез<символ> — ТЕПЕРЬ РАЗРЕШЁН (заимствованный
# возврат; функция классифицируется как borrow-returning, вызывающий не free'ит).
# Полноценный набор для п.6 — ниже в разделе «§37 п.6».
cat > строка_возврат_литерала.конда <<'KONDA'
#содержит <stdio.h>
срез<символ> т() { вернуть "hi" }
целое32 точка_входа(срез<символ*> аргументы)
{
    срез<символ> с = т()
    printf("%d\n", длина(с))
    вернуть 0
}
KONDA
"$BIN" строка_возврат_литерала.конда >"$TMP/стр_рет.log" 2>&1 || {
    cat "$TMP/стр_рет.log" >&2
    fail "возврат строкового литерала (borrow-фабрика) должен компилироваться"
}
assert_eq "2" "$(./вывод/строка_возврат_литерала.elf)" "borrow-возврат литерала: длина"

# П.2: владеющая строка через «выделить»+запись — можно вернуть; caller autofree'ит.
cat > строка_владеющая.конда <<'KONDA'
#содержит <stdio.h>
срез<символ> сделать()
{
    срез<символ> с = выделить(4)
    с[0] = 'h'; с[1] = 'i'; с[2] = '!'
    вернуть с
}
целое32 точка_входа(срез<символ*> аргументы)
{
    срез<символ> с = сделать()
    printf("длина=%d\n", длина(с))
    вернуть 0
}
KONDA
"$BIN" строка_владеющая.конда >"$TMP/стр_вл2.log" 2>&1 || {
    cat "$TMP/стр_вл2.log" >&2
    fail "владеющую строку через «выделить» можно вернуть и вызывающий autofree'ит"
}
# Кодоген: free по возвращённой строке у вызывающего (autofree) — ровно один.
grep -q "free(с.данные)" вывод/строка_владеющая.c || {
    cat вывод/строка_владеющая.c >&2
    fail "владеющая строка у вызывающего должна освобождаться autofree"
}
assert_eq "длина=4" "$(./вывод/строка_владеющая.elf)" "владеющая строка: длина"

# П.2: f-строка в контексте срез<символ> — заимствованный срез над стек-буфером.
cat > строка_f.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 x = 42
    срез<символ> с = "n=\(x)"
    printf("длина=%d\n", длина(с))
    для целое32 и = 0; и < длина(с); и = и + 1 {
        printf("%c", с[и])
    }
    printf("\n")
    вернуть 0
}
KONDA
"$BIN" строка_f.конда >"$TMP/стр_f.log" 2>&1 || {
    cat "$TMP/стр_f.log" >&2; fail "f-строка → срез<символ> должно транспилироваться"; }
# Кодоген: snprintf в _kfN + Срез{буфер, длина}; НЕТ autofree по такому срезу.
grep -q "snprintf(_kf0" вывод/строка_f.c || {
    cat вывод/строка_f.c >&2; fail "f-строка должна использовать stack-буфер snprintf"; }
grep -q "free(с" вывод/строка_f.c && {
    cat вывод/строка_f.c >&2; fail "f-строка-срез заимствован (стек) — free недопустим"; }
assert_eq "длина=4
n=42" "$(./вывод/строка_f.elf)" "f-строка-срез: длина от snprintf + посимвольный обход"

# П.2 guard: возврат f-строки — ошибка (стек умрёт).
cat > строка_возврат_f.конда <<'KONDA'
срез<символ> т() { целое32 x = 42; вернуть "n=\(x)" }
целое32 точка_входа(срез<символ*> аргументы) { вернуть 0 }
KONDA
if "$BIN" строка_возврат_f.конда >"$TMP/стр_рет_f.log" 2>&1; then
    fail "возврат f-строки как срез<символ> должно быть ошибкой (стек)"
fi
grep -q "живёт на стеке" "$TMP/стр_рет_f.log" || {
    cat "$TMP/стр_рет_f.log" >&2; fail "ошибка возврата f-строки должна объяснять стек"; }

# П.3: алиас «строка» = срез<символ> (параметр, локал, тип возврата).
cat > строка_алиас.конда <<'KONDA'
#содержит <stdio.h>
целое32 длн(строка с) { вернуть длина(с) }
строка сделать()
{
    строка с = выделить(4)
    с[0] = 'h'; с[1] = 'i'; с[2] = '!'
    вернуть с
}
целое32 точка_входа(срез<символ*> аргументы)
{
    строка л = "abc"
    строка в = сделать()
    printf("%d %d\n", длн(л), длн(в))
    вернуть 0
}
KONDA
"$BIN" строка_алиас.конда >"$TMP/стр_ал.log" 2>&1 || {
    cat "$TMP/стр_ал.log" >&2
    fail "алиас «строка» должен работать в параметре/локале/возврате"
}
assert_eq "3 4" "$(./вывод/строка_алиас.elf)" "алиас «строка»: длн литерала и владеющей"

# П.3: «строка» остаётся валидным ИМЕНЕМ переменной (контекстное).
cat > строка_имя_переменной.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 строка = 42
    printf("%d\n", строка)
    вернуть 0
}
KONDA
"$BIN" строка_имя_переменной.конда >"$TMP/стр_имя.log" 2>&1 || {
    cat "$TMP/стр_имя.log" >&2
    fail "«строка» как имя переменной (контекстное слово) не должно ломаться"
}
assert_eq "42" "$(./вывод/строка_имя_переменной.elf)" "«строка» — валидное имя переменной"

# П.4: вкси(с) — NUL-хелпер. Zero cost для литерала/f-строки (эмит «.данные»);
# для «выделить»-строки — стек-буфер с копией + NUL.
cat > строка_вкси.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    строка л = "литерал"
    printf("%s\n", вкси(л))                // из переменной-литерала → .данные
    printf("%s\n", вкси("прямой"))          // литерал сразу → .данные
    целое32 x = 42
    printf("%s\n", вкси("n=\(x)"))          // f-строка → .данные (snprintf с NUL)
    срез<символ> в = выделить(4)
    в[0] = 'a'; в[1] = 'b'; в[2] = 'c'
    printf("%s\n", вкси(в))                // владеющая → стек-буфер + NUL
    вернуть 0
}
KONDA
"$BIN" строка_вкси.конда >"$TMP/стр_вкси.log" 2>&1 || {
    cat "$TMP/стр_вкси.log" >&2; fail "«вкси» должно транспилироваться"; }
# Zero-cost на литерале-переменной И на прямом литерале — эмит «.данные» без буфера.
grep -q "((char\*)(л).данные)" вывод/строка_вкси.c || {
    cat вывод/строка_вкси.c >&2
    fail "вкси(переменной-литерала) должен быть zero-cost (эмит .данные)"
}
# Для владеющей — стек-буфер _kv0 + копия.
grep -q "_kv0" вывод/строка_вкси.c || {
    cat вывод/строка_вкси.c >&2
    fail "вкси(«выделить»-строки) должен использовать стек-буфер (нет с_нулем)"
}
assert_eq "литерал
прямой
n=42
abc" "$(./вывод/строка_вкси.elf)" "вкси: literal/f-string zero-cost, выделить — копия+NUL"

# ─── §37 п.6: выведенное «владеет-ли-возврат» (borrow-возврат строк) ─────────
# Функция, ВСЕ возвраты которой — литералы, классифицируется как заимствующая-
# возврат (пред-проход, ноль рантайма): вызывающий НЕ освобождает результат.
# Функция с возвратом из «выделить» — владеющая: вызывающий autofree'ит.
# Смешанная — ошибка (единообразие). Свойство пропагируется через «вернуть G()».

# Фабрика литералов: 0 free у вызывающего, результат borrow над .rodata.
cat > возврат_фабрика.конда <<'KONDA'
#содержит <stdio.h>
строка код(целое32 к)
{
    если (к == 0) { вернуть "OK" }
    если (к == 1) { вернуть "не найдено" }
    вернуть "неизвестно"
}
целое32 точка_входа(срез<символ*> аргументы)
{
    строка с = код(1)
    printf("%d %s\n", длина(с), вкси(с))
    вернуть 0
}
KONDA
"$BIN" возврат_фабрика.конда >"$TMP/возврат_фабрика.log" 2>&1 || {
    cat "$TMP/возврат_фабрика.log" >&2
    fail "фабрика строк-литералов должна компилироваться (borrow-возврат)"
}
# Результат заимствован → у вызывающего НЕТ free по нему (ноль рантайм-цены).
grep -q "free(с.данные)" вывод/возврат_фабрика.c && {
    cat вывод/возврат_фабрика.c >&2
    fail "заимствованный возврат (литералы) НЕ должен освобождаться вызывающим"; }
assert_eq "19 не найдено" "$(./вывод/возврат_фабрика.elf)" "borrow-фабрика: длина(байты)+значение"

# Владеющая фабрика (возврат из «выделить»): вызывающий autofree'ит (1 free).
cat > возврат_владеющая.конда <<'KONDA'
#содержит <stdio.h>
строка собрать()
{
    строка с = выделить(4)
    с[0] = 'h'; с[1] = 'i'
    вернуть с
}
целое32 точка_входа(срез<символ*> аргументы)
{
    строка с = собрать()
    printf("%d\n", длина(с))
    вернуть 0
}
KONDA
"$BIN" возврат_владеющая.конда >"$TMP/возврат_владеющая.log" 2>&1 || {
    cat "$TMP/возврат_владеющая.log" >&2; fail "владеющая фабрика должна компилироваться"; }
grep -q "free(с.данные)" вывод/возврат_владеющая.c || {
    cat вывод/возврат_владеющая.c >&2
    fail "владеющий возврат («выделить») должен освобождаться вызывающим (autofree)"; }
assert_eq "4" "$(./вывод/возврат_владеющая.elf)" "владеющая фабрика: длина"

# Пропагация через «вернуть G()»: обёртка над borrow-фабрикой — тоже borrow.
cat > возврат_пропагация.конда <<'KONDA'
#содержит <stdio.h>
строка низ() { вернуть "низ" }
строка обёртка(целое32 к)
{
    если (к == 0) { вернуть низ() }
    вернуть "верх"
}
целое32 точка_входа(срез<символ*> аргументы)
{
    строка с = обёртка(0)
    printf("%s\n", вкси(с))
    вернуть 0
}
KONDA
"$BIN" возврат_пропагация.конда >"$TMP/возврат_пропагация.log" 2>&1 || {
    cat "$TMP/возврат_пропагация.log" >&2; fail "пропагация borrow через вернуть G()"; }
grep -q "free(с.данные)" вывод/возврат_пропагация.c && {
    cat вывод/возврат_пропагация.c >&2
    fail "обёртка над borrow-фабрикой должна быть borrow (нет free)"; }
assert_eq "низ" "$(./вывод/возврат_пропагация.elf)" "пропагация borrow: значение"

# Смешанный возврат (литерал + владеющий) — ошибка (единообразие; ноль рантайма).
cat > возврат_смешанный.конда <<'KONDA'
строка м(целое32 к)
{
    если (к == 0) { вернуть "по умолчанию" }
    строка с = выделить(4)
    с[0] = 'x'
    вернуть с
}
целое32 точка_входа(срез<символ*> аргументы) { вернуть 0 }
KONDA
if "$BIN" возврат_смешанный.конда >"$TMP/возврат_смешанный.log" 2>&1; then
    fail "смешанный возврат (владеющий+заимствованный) должен быть ошибкой"
fi
grep -q "и ВЛАДЕЮЩИЙ, и ЗАИМСТВОВАННЫЙ" "$TMP/возврат_смешанный.log" || {
    cat "$TMP/возврат_смешанный.log" >&2
    fail "ошибка смешанного возврата должна объяснять единообразие"; }

# Возврат f-строки — всегда ошибка (стек умрёт), независимо от классификации.
cat > возврат_f_ошибка.конда <<'KONDA'
строка т() { целое32 x = 1; вернуть "n=\(x)" }
целое32 точка_входа(срез<символ*> аргументы) { вернуть 0 }
KONDA
if "$BIN" возврат_f_ошибка.конда >"$TMP/возврат_f.log" 2>&1; then
    fail "возврат f-строки должен быть ошибкой (стек)"
fi
grep -q "живёт на стеке" "$TMP/возврат_f.log" || {
    cat "$TMP/возврат_f.log" >&2; fail "ошибка возврата f-строки должна объяснять стек"; }

# ─── §42: срезы строк как в Python «s[a:b]» (заимствованный вид) ─────────────

# База: s[a:b] / s[a:] / s[:b] / s[:] по ASCII-строке — заимствованный вид,
# 0 аллокаций (в C — вызов срез_подсрез, autofree НЕ регистрируется).
cat > срез_строки_база.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    строка с = "hello world"
    printf("%s|%s|%s|%s\n", вкси(с[0:5]), вкси(с[6:]), вкси(с[:5]), вкси(с[:]))
    вернуть 0
}
KONDA
"$BIN" срез_строки_база.конда >"$TMP/срез_база.log" 2>&1 || {
    cat "$TMP/срез_база.log" >&2; fail "срез строки s[a:b] должен транспилироваться"; }
assert_eq "hello|world|hello|hello world" "$(./вывод/срез_строки_база.elf)" \
    "§42 база: s[a:b]/s[a:]/s[:b]/s[:]"
# Вид — заимствованный: никакого free для под-строк (autofree их не трогает).
grep -q "срез_подсрез" вывод/срез_строки_база.c || {
    cat вывод/срез_строки_база.c >&2; fail "§42: ожидался вызов срез_подсрез"; }

# Отрицательные индексы: отсчёт с конца (s[-3:], s[:-2]).
cat > срез_строки_отриц.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    строка с = "abcdefg"
    printf("%s|%s\n", вкси(с[-3:]), вкси(с[:-2]))
    вернуть 0
}
KONDA
"$BIN" срез_строки_отриц.конда >"$TMP/срез_отриц.log" 2>&1 || {
    cat "$TMP/срез_отриц.log" >&2; fail "срез с отрицательными индексами должен работать"; }
assert_eq "efg|abcde" "$(./вывод/срез_строки_отриц.elf)" "§42 отрицательные: s[-3:] / s[:-2]"

# Владеющая копия подстроки — клон(s[a:b]); её МОЖНО вернуть (передача владения).
cat > срез_строки_клон.конда <<'KONDA'
#содержит <stdio.h>
строка префикс(строка с)
{
    строка т = клон(с[0:3])
    вернуть т
}
целое32 точка_входа(срез<символ*> аргументы)
{
    строка р = префикс("hello")
    printf("%s %d\n", вкси(р), как<целое32>(длина(р)))
    вернуть 0
}
KONDA
"$BIN" срез_строки_клон.конда >"$TMP/срез_клон.log" 2>&1 || {
    cat "$TMP/срез_клон.log" >&2; fail "клон(s[a:b]) должен давать владеющую копию"; }
assert_eq "hel 3" "$(./вывод/срез_строки_клон.elf)" "§42 клон(вида): владеющая подстрока, возврат ОК"

# Вид над срез<целое32> (не строка): utf8-проверки нет, foreach по виду.
cat > срез_чисел.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> ч = выделить(5)
    ч[0] = 10
    ч[1] = 20
    ч[2] = 30
    ч[3] = 40
    ч[4] = 50
    срез<целое32> середина = ч[1:4]
    для_каждого э из середина { printf("%d ", э) }
    printf("\n")
    вернуть 0
}
KONDA
"$BIN" срез_чисел.конда >"$TMP/срез_чисел.log" 2>&1 || {
