grep -q "конда_чек_делителя" вывод/деление_рантайм_ноль.c || {
    cat вывод/деление_рантайм_ноль.c >&2
    fail "неконстантное деление должно идти через рантайм-guard"
}
./вывод/деление_рантайм_ноль.elf >/dev/null 2>"$TMP/деление_рантайм.err" && rc=0 || rc=$?
assert_eq "134" "$rc" "деление на ноль в рантайме прерывает программу"
