    fail "рантайм-сообщение о делении на ноль должно быть понятным"
}
assert_eq "10" "$(./вывод/деление_рантайм_ноль.elf x)" "деление с ненулевым делителем работает"

# Константный делитель не порождает рантайм-guard (минимум рантайма).
cat > деление_константа.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
