    printf("%d\n", 1 << с)
    вернуть 0
}
KONDA

"$BIN" сдвиг_рантайм.конда >"$TMP/сдвиг_рантайм.log" 2>&1 || {
    cat "$TMP/сдвиг_рантайм.log" >&2
    fail "сдвиг с неконстантным числом бит должен транспилироваться"
