# Регресс корректности: рантайм-guard считает операцию в РОДНОМ типе (typeof),
# а не в знаковом long. Раньше отладка молча портила результат (release был прав).
# 1) Беззнаковое 64-бит деление: (2^64-1)/2 = 2^63-1, а не 0.
cat > деление_беззнак64.конда <<'KONDA'
#содержит <stdio.h>
неподписанный целое64 дел(неподписанный целое64 a, неподписанный целое64 b) { вернуть a / b }
целое32 точка_входа(срез<символ*> аргументы)
{
    неподписанный целое64 x = 18446744073709551615
    неподписанный целое64 y = как<неподписанный целое64>(длина(аргументы)) + 1
    printf("%llu\n", дел(x, y))
    вернуть 0
}
KONDA
"$BIN" деление_беззнак64.конда >"$TMP/деление_беззнак64.log" 2>&1 || {
    cat "$TMP/деление_беззнак64.log" >&2; fail "беззнаковое деление должно транспилироваться"; }
assert_eq "9223372036854775807" "$(./вывод/деление_беззнак64.elf)" \
    "беззнаковое 64-бит деление в отладке даёт верный результат (не знаковый long)"

# 2) Беззнаковый сдвиг вправо — ЛОГИЧЕСКИЙ (знак не размножается): 2^63 >> 1 = 2^62.
cat > сдвиг_беззнак64.конда <<'KONDA'
#содержит <stdio.h>
неподписанный целое64 сдв(неподписанный целое64 x, неподписанный целое64 n) { вернуть x >> n }
целое32 точка_входа(срез<символ*> аргументы)
{
    неподписанный целое64 x = 9223372036854775808
    неподписанный целое64 один = как<неподписанный целое64>(длина(аргументы))
    printf("%llu\n", сдв(x, один))
    вернуть 0
}
KONDA
"$BIN" сдвиг_беззнак64.конда >"$TMP/сдвиг_беззнак64.log" 2>&1 || {
    cat "$TMP/сдвиг_беззнак64.log" >&2; fail "беззнаковый сдвиг должен транспилироваться"; }
# Без доп. аргументов длина(аргументы)==1 → сдвиг на 1: 2^63 >> 1 = 2^62.
# Арифметический (знаковый) сдвиг дал бы 2^63+2^62 — вот его и ловим.
assert_eq "4611686018427387904" "$(./вывод/сдвиг_беззнак64.elf)" \
    "беззнаковый сдвиг вправо в отладке логический, а не арифметический"

# 3) Вещественное деление НЕ гейтится рантайм-guard'ом (÷0 определено: inf/nan)
#    и считается в double: 7.0/2.0 = 3.5, а не усечённое целое.
cat > деление_вещ.конда <<'KONDA'
#содержит <stdio.h>
вещественное64 дел(вещественное64 a, вещественное64 b) { вернуть a / b }
целое32 точка_входа(срез<символ*> аргументы)
{
    вещественное64 x = 7.0
    вещественное64 y = как<вещественное64>(длина(аргументы)) + 1.0
    printf("%.1f\n", дел(x, y))
    вернуть 0
}
KONDA
"$BIN" деление_вещ.конда >"$TMP/деление_вещ.log" 2>&1 || {
    cat "$TMP/деление_вещ.log" >&2; fail "вещественное деление должно транспилироваться"; }
if grep -q "конда_чек_делителя" вывод/деление_вещ.c; then
    cat вывод/деление_вещ.c >&2
    fail "вещественное деление не должно идти через целочисленный guard"
fi
assert_eq "3.5" "$(./вывод/деление_вещ.elf)" "вещественное деление считается в double (не усекается)"

# ─── Смешанная арифметика: результат — «старший» тип ────────────────────────
# Раньше «целое8 + целое64» типизировался по левому операнду (целое8), из-за
# чего присваивание суммы в целое32 молча усекалось. Теперь результат — целое64
# (старший операнд), поэтому «целое32 в = целое8 + целое64» ловится как сужение.
cat > арифметика_старший_тип.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    целое8  а = как<целое8>(длина(аргументы))
    целое64 б = как<целое64>(длина(аргументы))
    целое32 в = а + б
    printf("%d\n", в)
    вернуть 0
}
KONDA

if "$BIN" арифметика_старший_тип.конда >"$TMP/арифметика_старший_тип.log" 2>&1; then
    cat "$TMP/арифметика_старший_тип.log" >&2
    fail "сумма целое8+целое64 в целое32 — сужение, должна быть ошибка"
fi
grep -q "сужение" "$TMP/арифметика_старший_тип.log" || {
    cat "$TMP/арифметика_старший_тип.log" >&2
    fail "должно диагностироваться неявное сужение старшего типа"
}

# Явное «как<целое32>(…)» разрешает сужение результата — компилируется.
cat > арифметика_старший_каст.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    целое8  а = как<целое8>(длина(аргументы))
    целое64 б = 20
    целое32 в = как<целое32>(а + б)
    printf("%d\n", в)
    вернуть 0
}
KONDA

"$BIN" арифметика_старший_каст.конда >"$TMP/арифметика_старший_каст.log" 2>&1 || {
    cat "$TMP/арифметика_старший_каст.log" >&2
    fail "явный каст суммы к целое32 должен компилироваться"
}
assert_eq "21" "$(./вывод/арифметика_старший_каст.elf)" "старший тип с кастом: вывод"

# ─── Знаковое переполнение +/-/*: рантайм-guard (стиль Rust) ─────────────────
# Неконстантное знаковое сложение/вычитание/умножение может переполниться (UB
# в C). Кодоген вставляет checked-builtin: при переполнении — сообщение и abort,
# вместо тихого оборачивания.
cat > переполнение_рантайм.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 а = как<целое32>(длина(аргументы)) + 2000000000
    целое32 б = а + 2000000000
    printf("%d\n", б)
    вернуть 0
}
KONDA

"$BIN" переполнение_рантайм.конда >"$TMP/переполнение_рантайм.log" 2>&1 || {
    cat "$TMP/переполнение_рантайм.log" >&2
    fail "неконстантная арифметика должна транспилироваться"
}
grep -q "арифметика_безопасно" вывод/переполнение_рантайм.c || {
    cat вывод/переполнение_рантайм.c >&2
    fail "неконстантное знаковое +/-/* должно идти через рантайм-guard"
}
./вывод/переполнение_рантайм.elf >/dev/null 2>"$TMP/переполнение_рантайм.err" && rc=0 || rc=$?
assert_eq "134" "$rc" "переполнение целого в рантайме прерывает программу (SIGABRT)"
grep -q "переполнение целого" "$TMP/переполнение_рантайм.err" || {
    cat "$TMP/переполнение_рантайм.err" >&2
    fail "рантайм-сообщение о переполнении должно быть понятным"
}

# Значения без переполнения работают штатно.
cat > переполнение_норма.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 а = как<целое32>(длина(аргументы))
    целое32 б = а * 3 + 1
