}
assert_eq "4" "$(./вывод/переполнение_норма.elf)" "арифметика без переполнения: вывод"

# Константное «+/-/*» проверяется статически, без рантайм-guard.
cat > переполнение_константа.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 а = 100 * 100
    printf("%d\n", а)
    вернуть 0
}
KONDA

"$BIN" переполнение_константа.конда >"$TMP/переполнение_константа.log" 2>&1 || {
    cat "$TMP/переполнение_константа.log" >&2
    fail "константное умножение без переполнения должно компилироваться"
}
if grep -q "арифметика_безопасно" вывод/переполнение_константа.c; then
    cat вывод/переполнение_константа.c >&2
    fail "константная арифметика не должна проверяться в рантайме"
fi
assert_eq "10000" "$(./вывод/переполнение_константа.elf)" "константное умножение: вывод"

# Беззнаковое переполнение определено в C (wrap) — без guard.
cat > переполнение_беззнак.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    неподписанный целое32 а = как<неподписанный целое32>(длина(аргументы))
    неподписанный целое32 б = а + а
    printf("%u\n", б)
    вернуть 0
}
KONDA

"$BIN" переполнение_беззнак.конда >"$TMP/переполнение_беззнак.log" 2>&1 || {
    cat "$TMP/переполнение_беззнак.log" >&2
    fail "беззнаковая арифметика должна компилироваться"
}
if grep -q "арифметика_безопасно" вывод/переполнение_беззнак.c; then
    cat вывод/переполнение_беззнак.c >&2
    fail "беззнаковый перенос определён в C — рантайм-guard не нужен"
fi

# ─── Релизная сборка: рантайм-проверки снимаются (скорость уровня C) ─────────
# Тот же исходник, что переполнял в дебаге, в релизе идёт без guard и не
# прерывается. Благодаря -fwrapv переполнение ОПРЕДЕЛЕНО (обёртка по 2^32), а не
# UB: результат детерминирован. a=1+2000000000=2000000001;
# b=2000000001+2000000000=4000000001 → как int32 = 4000000001-2^32 = -294967295.
"$BIN" --релиз переполнение_рантайм.конда >"$TMP/релиз_переполнение.log" 2>&1 || {
    cat "$TMP/релиз_переполнение.log" >&2
    fail "релизная сборка переполняющего кода должна компилироваться"
}
if grep -q "арифметика_безопасно" вывод/переполнение_рантайм.c; then
    cat вывод/переполнение_рантайм.c >&2
    fail "в релизе не должно быть guard-а переполнения"
fi
rel_out=$(./вывод/переполнение_рантайм.elf 2>/dev/null) && rc=0 || rc=$?
assert_eq "0" "$rc" "релиз: переполнение не прерывает программу (проверок нет)"
assert_eq "-294967295" "$rel_out" "релиз: знаковое переполнение оборачивается детерминированно (-fwrapv, не UB)"

# --release как синоним --релиз.
"$BIN" --release переполнение_рантайм.конда >/dev/null 2>&1 || fail "--release должен работать"
if grep -q "арифметика_безопасно" вывод/переполнение_рантайм.c; then
    fail "--release тоже снимает guard"
fi

# Проверка границ среза остаётся и в релизе (безопасность памяти — как в Rust);
# в релизе снимается только арифметический guard переполнения.
cat > релиз_срез.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> с = выделить(1)
    с[0] = 42
    целое32 и = длина(аргументы) - 1
    printf("%d\n", с[и])
    вернуть 0
}
KONDA

# В дебаге — проверка границ (срез_доступ) есть.
"$BIN" релиз_срез.конда >"$TMP/дебаг_срез.log" 2>&1 || {
    cat "$TMP/дебаг_срез.log" >&2
    fail "срез с динамическим индексом должен транспилироваться (дебаг)"
}
# «срез_доступ(с,» — именно вызов (в прологе определение — «срез_доступ(Срез с»).
grep -q "срез_доступ(с," вывод/релиз_срез.c || {
    cat вывод/релиз_срез.c >&2
    fail "дебаг: динамический доступ к срезу должен идти через срез_доступ"
}
# В релизе — проверка границ среза сохраняется (в отличие от арифм. guard).
"$BIN" --релиз релиз_срез.конда >"$TMP/релиз_срез.log" 2>&1 || {
    cat "$TMP/релиз_срез.log" >&2
    fail "срез с динамическим индексом должен транспилироваться (релиз)"
}
grep -q "срез_доступ(с," вывод/релиз_срез.c || {
    cat вывод/релиз_срез.c >&2
    fail "релиз: проверка границ среза должна оставаться (срез_доступ)"
}
# Но арифметический guard (вычитание) в релизе снят.
if grep -q "арифметика_безопасно" вывод/релиз_срез.c; then
    cat вывод/релиз_срез.c >&2
    fail "релиз: арифметический guard должен быть снят"
fi
assert_eq "42" "$(./вывод/релиз_срез.elf)" "релиз: доступ к срезу с проверкой даёт значение"

# Выход за границы среза в релизе — по-прежнему прерывание (SIGABRT), не UB.
"$BIN" --релиз релиз_срез.конда >/dev/null 2>&1
./вывод/релиз_срез.elf лишний_аргумент >/dev/null 2>"$TMP/релиз_срез_oob.err" && rc=0 || rc=$?
assert_eq "134" "$rc" "релиз: выход за границы среза прерывает программу (SIGABRT)"

# ─── f-строки: буфер на стеке (не static) + быстрый путь ────────────────────
cat > фстрока_опт.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    символ* имя = "Мир"
    целое32 год = 2026
    символ* прямая = "\(имя)"
    символ* формат = "Привет, \(имя)! Год \(год)."
    printf("%s\n", прямая)
    printf("%s\n", формат)
    вернуть 0
}
KONDA

"$BIN" фстрока_опт.конда >"$TMP/фстрока_опт.log" 2>&1 || {
    cat "$TMP/фстрока_опт.log" >&2
    fail "f-строки должны транспилироваться"
}
# static-буфера больше нет (потокобезопасность/реентерабельность).
if grep -q "static char _kf" вывод/фстрока_опт.c; then
    cat вывод/фстрока_опт.c >&2
    fail "буфер f-строки не должен быть static"
fi
# Буфер поднят в начало функции как обычная локальная переменная.
grep -q "char _kf0\[1024\];" вывод/фстрока_опт.c || {
    cat вывод/фстрока_опт.c >&2
    fail "буфер f-строки должен быть локальным (на стеке)"
}
# Быстрый путь: «\(имя)» без snprintf — присваивание напрямую.
grep -q "прямая = (имя)" вывод/фстрока_опт.c || {
    cat вывод/фстрока_опт.c >&2
    fail "одиночная строковая вставка должна идти без snprintf (быстрый путь)"
}
# Ровно один буфер: только сложная f-строка его требует (быстрый путь — нет).
if grep -q "char _kf1\[1024\];" вывод/фстрока_опт.c; then
    cat вывод/фстрока_опт.c >&2
    fail "быстрый путь не должен потреблять буфер f-строки"
fi
printf 'Мир\nПривет, Мир! Год 2026.\n' > "$TMP/фстрока_опт.ожид"
./вывод/фстрока_опт.elf > "$TMP/фстрока_опт.вывод"
if ! cmp -s "$TMP/фстрока_опт.вывод" "$TMP/фстрока_опт.ожид"; then
    cat "$TMP/фстрока_опт.вывод" >&2
    fail "вывод f-строк неверен"
fi

# Две сложные f-строки в одном выражении — разные буферы (не затирают).
cat > фстрока_две.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 а = 1
    целое32 б = 2
    printf("%s | %s\n", "первое=\(а)", "второе=\(б)")
    вернуть 0
}
KONDA

"$BIN" фстрока_две.конда >"$TMP/фстрока_две.log" 2>&1 || {
    cat "$TMP/фстрока_две.log" >&2
    fail "две f-строки должны транспилироваться"
}
assert_eq "первое=1 | второе=2" "$(./вывод/фстрока_две.elf)" "две f-строки не затирают друг друга"

# Право-размерные буферы: буфер f-строки — статически посчитанной длины (сумма
# верхних оценок вставок + сырые чанки + NUL), а не общих 1024. Числовая/
# символьная f-строка получает КОМПАКТНЫЙ буфер, строковая (%s) — прежние 1024.
cat > фстрока_размер.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 г = 2026
    символ* имя = "Мир"
    символ* числа = "год \(г) и \(г)"
    символ* строка = "привет \(имя)"
    printf("%s | %s\n", числа, строка)
    вернуть 0
}
KONDA

"$BIN" фстрока_размер.конда >"$TMP/фстрока_размер.log" 2>&1 || {
    cat "$TMP/фстрока_размер.log" >&2
    fail "f-строка с right-sizing должна транспилироваться"
}
# Числовая f-строка: буфер меньше 1024 (не общий дефолт), и это НЕ 1024.
if grep -qE "char _kf0\[1024\];" вывод/фстрока_размер.c; then
    cat вывод/фстрока_размер.c >&2
    fail "числовая f-строка не должна брать буфер 1024 (нужен right-sizing)"
fi
grep -qE "char _kf0\[[0-9]+\];" вывод/фстрока_размер.c || {
    cat вывод/фстрока_размер.c >&2
    fail "буфер числовой f-строки должен быть статического размера"
}
# Строковая (%s) вставка — безразмерна → прежний буфер 1024.
grep -qE "char _kf1\[1024\];" вывод/фстрока_размер.c || {
    cat вывод/фстрока_размер.c >&2
    fail "строковая f-строка (%s) должна сохранять буфер 1024"
}
assert_eq "год 2026 и 2026 | привет Мир" "$(./вывод/фстрока_размер.elf)" \
    "right-sizing: числовая и строковая f-строки выводятся верно"

# Быстрый путь срез-контекста: одиночная строковая вставка «\(символ*)» в
# срез<символ> — заимствованный ВИД {указатель, strlen}, БЕЗ буфера и БЕЗ
# snprintf-копии (§37 + §50 п.2). Прежде такой случай шёл через snprintf в _kfN.
cat > фстрока_срез_быстро.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    символ* имя = "Мир"
    срез<символ> в = "\(имя)"
    для_каждого с из в { printf("%c", с) }
    printf("\n")
    вернуть 0
}
KONDA

"$BIN" фстрока_срез_быстро.конда >"$TMP/фстрока_срез_быстро.log" 2>&1 || {
    cat "$TMP/фстрока_срез_быстро.log" >&2
    fail "быстрый срез-путь f-строки должен транспилироваться"
}
# Заимствованный вид: strlen над самой строкой, НЕ snprintf/буфер.
grep -q "strlen(_s)" вывод/фстрока_срез_быстро.c || {
    cat вывод/фстрока_срез_быстро.c >&2
    fail "срез-контекст одиночной вставки должен давать {указатель, strlen} (borrow)"
}
if grep -qE "snprintf\(_kf|char _kf" вывод/фстрока_срез_быстро.c; then
    cat вывод/фстрока_срез_быстро.c >&2
    fail "быстрый срез-путь не должен заводить буфер/snprintf"
fi
assert_eq "Мир" "$(./вывод/фстрока_срез_быстро.elf)" \
    "быстрый срез-путь: заимствованный вид выводится верно"

# Пустая интерполяция «\()» — программист открыл вставку, но ничего не встроил →
# ошибка транспиляции с ПОЗИЦИЕЙ самой строки (не «строка 0, колонка 0»).
cat > фстрока_пусто.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    символ* с = "привет \()"
    printf("%s\n", с)
    вернуть 0
}
KONDA

if "$BIN" --только-си фстрока_пусто.конда >"$TMP/фстрока_пусто.log" 2>&1; then
    cat "$TMP/фстрока_пусто.log" >&2
    fail "пустая интерполяция «\\()» должна быть ошибкой"
fi
grep -q "пустая интерполяция" "$TMP/фстрока_пусто.log" || {
    cat "$TMP/фстрока_пусто.log" >&2
    fail "ошибка пустой интерполяции должна быть понятной"
}
# Позиция — не нулевая (диагностика указывает на строку исходника).
grep -qE "строка 5, колонка" "$TMP/фстрока_пусто.log" || {
    cat "$TMP/фстрока_пусто.log" >&2
    fail "ошибка пустой интерполяции должна нести верную позицию"
}
# Пробельная интерполяция «\(  )» — тоже ничего не встроено → та же ошибка.
cat > фстрока_пробел.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    символ* с = "привет \(  )"
    printf("%s\n", с)
    вернуть 0
}
KONDA
if "$BIN" --только-си фстрока_пробел.конда >"$TMP/фстрока_пробел.log" 2>&1; then
    cat "$TMP/фстрока_пробел.log" >&2
    fail "пробельная интерполяция «\\(  )» должна быть ошибкой"
fi
grep -q "пустая интерполяция" "$TMP/фстрока_пробел.log" || {
    cat "$TMP/фстрока_пробел.log" >&2
    fail "ошибка пробельной интерполяции должна быть понятной"
}

# ─── Логические операторы «и»/«или» (русские &&/||) ─────────────────────────
# «и»/«или» — логические операторы в условиях; «и» при этом остаётся валидным
# именем переменной (контекстное ключевое слово: оператор только в инфиксной
# позиции). Приоритет: «и» связывает крепче «или», как &&/|| в C.
cat > логические.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 а = 5
    целое32 б = 10
    целое32 и = 0
    пока (и < 3)
    {
        и = и + 1
    }
    целое32 итог = 0
    если (а > 0 и б > 0)
    {
        итог = итог + 1
    }
    если (а > 100 или б > 5)
    {
        итог = итог + 10
    }
    если (а > 100 и б > 100 или и == 3)
    {
        итог = итог + 100
    }
    printf("%d\n", итог)
    вернуть 0
}
KONDA

"$BIN" логические.конда >"$TMP/логические.log" 2>&1 || {
    cat "$TMP/логические.log" >&2
    fail "логические и/или должны транспилироваться"
}
# «и» как переменная сохранена (счётчик цикла).
grep -q "while ((и < 3))" вывод/логические.c || {
    cat вывод/логические.c >&2
    fail "«и» должно оставаться именем переменной-счётчика"
}
# «и»/«или» скомпилированы в && / ||.
grep -q "(а > 0) && (б > 0)" вывод/логические.c || {
    cat вывод/логические.c >&2
    fail "«и» в условии должно давать &&"
}
grep -q "(а > 100) || (б > 5)" вывод/логические.c || {
    cat вывод/логические.c >&2
    fail "«или» в условии должно давать ||"
}
# Приоритет: «и» крепче «или» — ((..&&..)||..).
grep -q "((а > 100) && (б > 100)) || (и == 3)" вывод/логические.c || {
    cat вывод/логические.c >&2
    fail "«и» должно связывать крепче «или»"
}
assert_eq "111" "$(./вывод/логические.elf)" "логические и/или: результат"

# C-запись && / || тоже принимается.
cat > логические_си.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 а = 1
    целое32 б = 0
    если (а == 1 && б == 0)
    {
        printf("да\n")
    }
    если (а == 2 || б == 0)
    {
        printf("или\n")
    }
    вернуть 0
}
KONDA

"$BIN" логические_си.конда >"$TMP/логические_си.log" 2>&1 || {
    cat "$TMP/логические_си.log" >&2
    fail "C-запись &&/|| должна работать"
}
printf 'да\nили\n' > "$TMP/логические_си.ожид"
./вывод/логические_си.elf > "$TMP/логические_си.вывод"
if ! cmp -s "$TMP/логические_си.вывод" "$TMP/логические_си.ожид"; then
    cat "$TMP/логические_си.вывод" >&2
    fail "вывод &&/|| неверен"
fi

# Многострочное условие в скобках: перевод строки — продолжение.
cat > логические_многострочно.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 а = 3
    целое32 б = 4
    если (а > 0 и
          б > 0)
    {
        printf("ок\n")
    }
    вернуть 0
}
KONDA

"$BIN" логические_многострочно.конда >"$TMP/логические_многострочно.log" 2>&1 || {
    cat "$TMP/логические_многострочно.log" >&2
    fail "многострочное логическое условие в скобках должно работать"
}
assert_eq "ок" "$(./вывод/логические_многострочно.elf)" "многострочное и: результат"

# ─── Сборка библиотеки (--библиотека): .so + заголовок .h, без точки входа ───
cat > библиотека_матем.конда <<'KONDA'
целое32 сложить(целое32 а, целое32 б)
{
    вернуть а + б
}

целое32 умножить(целое32 а, целое32 б)
{
    вернуть а * б
}

статический целое32 внутренняя(целое32 х)
{
    вернуть х + 1
}
KONDA

"$BIN" --библиотека библиотека_матем.конда >"$TMP/библиотека.log" 2>&1 || {
    cat "$TMP/библиотека.log" >&2
    fail "библиотека без точки входа должна собираться"
}
# Артефакты .so и .h созданы.
[ -f вывод/библиотека_матем.so ] || fail "должен быть создан .so"
[ -f вывод/библиотека_матем.h ]  || fail "должен быть создан заголовок .h"
# Заголовок: pragma once + публичные прототипы, БЕЗ static-функции и без тел.
grep -q "#pragma once" вывод/библиотека_матем.h || {
    cat вывод/библиотека_матем.h >&2
    fail "заголовок должен иметь защиту от повторного включения"
}
grep -q "int32_t сложить(int32_t а, int32_t б);" вывод/библиотека_матем.h || {
    cat вывод/библиотека_матем.h >&2
    fail "заголовок должен содержать прототип публичной функции"
}
if grep -q "внутренняя" вывод/библиотека_матем.h; then
    cat вывод/библиотека_матем.h >&2
    fail "static-функция не должна попадать в публичный заголовок"
fi
if grep -q "return" вывод/библиотека_матем.h; then
    cat вывод/библиотека_матем.h >&2
    fail "заголовок не должен содержать тела функций"
fi
# .so реально линкуется и вызывается из C через сгенерированный заголовок.
cat > "$TMP/потребитель.c" <<C_EOF
#include <stdio.h>
#include "$TMP/вывод/библиотека_матем.h"
int main(void){ printf("%d %d\n", сложить(3, 4), умножить(5, 6)); return 0; }
C_EOF
cc -std=gnu23 "$TMP/потребитель.c" -L вывод -l:библиотека_матем.so \
   -Wl,-rpath,"$TMP/вывод" -o "$TMP/потребитель.elf" 2>"$TMP/потребитель.err" || {
    cat "$TMP/потребитель.err" >&2
    fail "C-программа должна линковаться против собранной .so"
}
assert_eq "7 30" "$("$TMP/потребитель.elf")" "вызов функций библиотеки из C"

# Библиотека со срезом: заголовок содержит тип Срез.
cat > библиотека_срез.конда <<'KONDA'
целое32 сумма_среза(срез<целое32> данные)
{
    целое32 итог = 0
    для_каждого э из данные    {
        итог = итог + э
    }
    вернуть итог
}
KONDA

"$BIN" --библиотека библиотека_срез.конда >"$TMP/библиотека_срез.log" 2>&1 || {
    cat "$TMP/библиотека_срез.log" >&2
    fail "библиотека со срезом должна собираться"
}
grep -q "} Срез;" вывод/библиотека_срез.h || {
    cat вывод/библиотека_срез.h >&2
    fail "заголовок библиотеки со срезом должен определять тип Срез"
}

# §37 п.6: бит «возврат заимствован» переносится через «.и» (cross-library).
# Библиотека со строковыми фабриками: borrow-фабрика → «Ф имя 1», владеющая → 0.
cat > библиотека_строки.конда <<'KONDA'
строка приветствие() { вернуть "привет" }
строка построить()
{
    строка с = выделить(3)
    с[0] = 'a'
    вернуть с
}
KONDA
"$BIN" --библиотека библиотека_строки.конда >"$TMP/библиотека_строки.log" 2>&1 || {
    cat "$TMP/библиотека_строки.log" >&2
    fail "библиотека строковых фабрик должна собираться"
}
grep -q "^Ф приветствие 1$" вывод/библиотека_строки.и || {
    cat вывод/библиотека_строки.и >&2
    fail "borrow-фабрика в «.и» должна нести бит 1 (потребитель не освобождает)"
}
grep -q "^Ф построить 0$" вывод/библиотека_строки.и || {
    cat вывод/библиотека_строки.и >&2
    fail "владеющая фабрика в «.и» должна нести бит 0 (потребитель освобождает)"
}

# Библиотека + релиз: компиляция -shared с -O2.
"$BIN" --библиотека --релиз библиотека_матем.конда >"$TMP/библиотека_релиз.log" 2>&1 || {
    cat "$TMP/библиотека_релиз.log" >&2
    fail "релизная библиотека должна собираться"
}
grep -q -- "-shared -fPIC" "$TMP/библиотека_релиз.log" || {
    cat "$TMP/библиотека_релиз.log" >&2
    fail "библиотека должна компилироваться как разделяемая (-shared -fPIC)"
}
[ -f вывод/библиотека_матем.so ] || fail "релизный .so должен быть создан"

# ─── Компиляция без shell (execvp напрямую) — имя файла не интерпретируется ──
# Компилятор C запускается через execvp с готовым argv, а не через system()
# со строкой команды: символ «"» в имени файла — просто байты имени, а не
# завершение shell-кавычки (регрессия для command injection).
cat > 'кавычка"внутри.конда' <<'KONDA'
целое32 точка_входа(срез<символ*> аргументы)
{
    вернуть 0
}
KONDA

"$BIN" 'кавычка"внутри.конда' >"$TMP/кавычка.log" 2>&1 || {
    cat "$TMP/кавычка.log" >&2
    fail "имя файла с кавычкой должно транспилироваться и компилироваться"
}
[ -f 'вывод/кавычка"внутри.elf' ] || fail "бинарник с кавычкой в имени должен быть создан"

# ─── Защита от переполнения стека компилятора на патологическом выражении ───
# Раньше глубоко вложенное/длинное выражение (~10000 «+» подряд) валило сам
# транспилятор через SIGSEGV (рекурсивные разбор/типизация/кодоген строят и
# обходят дерево без ограничения глубины). Теперь — понятная ошибка вместо
# краха. Генерируем цепочку из 5000 «+» через printf (компактнее heredoc).
{
    printf '#содержит <stdio.h>\n\nцелое32 точка_входа(срез<символ*> аргументы)\n{\n    целое32 а = 1'
    i=1
    while [ "$i" -le 5000 ]; do
        printf ' + 1'
        i=$((i + 1))
    done
    printf '\n    вернуть 0\n}\n'
} > выражение_переполнение.конда

"$BIN" выражение_переполнение.конда >"$TMP/выражение_переполнение.log" 2>&1 && rc=0 || rc=$?
if [ "$rc" -eq 0 ]; then
    cat "$TMP/выражение_переполнение.log" >&2
    fail "патологически сложное выражение должно быть отклонено, а не скомпилировано"
fi
if [ "$rc" -ge 128 ]; then
    fail "транспилятор не должен падать по сигналу (SIGSEGV) на сложном выражении, код $rc"
fi
grep -q "выражение слишком сложное" "$TMP/выражение_переполнение.log" || {
    cat "$TMP/выражение_переполнение.log" >&2
    fail "ошибка о переполнении лимита выражения должна быть понятной"
}

# То же для глубоко вложенных скобок (другой путь рекурсии в разборе).
{
    printf '#содержит <stdio.h>\n\nцелое32 точка_входа(срез<символ*> аргументы)\n{\n    целое32 а = '
    i=1
    while [ "$i" -le 3000 ]; do printf '('; i=$((i + 1)); done
    printf '1'
    i=1
    while [ "$i" -le 3000 ]; do printf ')'; i=$((i + 1)); done
    printf '\n    вернуть 0\n}\n'
} > скобки_переполнение.конда

if "$BIN" скобки_переполнение.конда >"$TMP/скобки_переполнение.log" 2>&1; then
    cat "$TMP/скобки_переполнение.log" >&2
    fail "глубоко вложенные скобки должны быть отклонены, а не скомпилированы"
fi
grep -q "выражение слишком сложное" "$TMP/скобки_переполнение.log" || {
    cat "$TMP/скобки_переполнение.log" >&2
    fail "ошибка о переполнении лимита выражения (скобки) должна быть понятной"
}

# Умеренно сложное (но реалистичное) выражение по-прежнему компилируется.
cat > выражение_умеренное.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 а = (1 + 2) * (3 + 4) - 5 / (1 + 1) + ((6 - 2) * 3)
    printf("%d\n", а)
    вернуть 0
}
KONDA

"$BIN" выражение_умеренное.конда >"$TMP/выражение_умеренное.log" 2>&1 || {
    cat "$TMP/выражение_умеренное.log" >&2
    fail "умеренно сложное выражение должно компилироваться без ограничений"
}
assert_eq "31" "$(./вывод/выражение_умеренное.elf)" "умеренное выражение: результат"

# ─── CLI: --version, неизвестный флаг, диагностика отсутствия точка_входа ────
assert_eq "Konda 0.1.0" "$("$BIN" --version)" "--version печатает версию"
assert_eq "Konda 0.1.0" "$("$BIN" -v)" "-v печатает версию"

cat > флаг_проверка.конда <<'KONDA'
целое32 точка_входа(срез<символ*> аргументы)
{
    вернуть 0
}
KONDA
"$BIN" --неизвестный-флаг флаг_проверка.конда >"$TMP/неизвестный_флаг.log" 2>&1 && rc=0 || rc=$?
[ "$rc" -ne 0 ] || fail "неизвестный флаг должен быть отклонён"
grep -q "Неизвестный флаг" "$TMP/неизвестный_флаг.log" || {
