    fail "неизвестный флаг должен давать понятную ошибку, а не «файл не найден»"
}

cat > без_точки_входа.конда <<'KONDA'
целое32 сложить(целое32 а, целое32 б)
{
    вернуть а + б
}
KONDA

"$BIN" без_точки_входа.конда >"$TMP/без_точки_входа.log" 2>&1 && rc=0 || rc=$?
[ "$rc" -ne 0 ] || fail "программа без точка_входа не должна собираться в исполняемый файл"
grep -q "точка_входа" "$TMP/без_точки_входа.log" || {
    cat "$TMP/без_точки_входа.log" >&2
    fail "ошибка отсутствия точка_входа должна быть понятной (не сырая ошибка линковки)"
}
