# ─── Возврат перечисления/структуры из функции по значению ──────────────────

# Перечисление по значению: обычный случай, никаких вопросов владения.
cat > возврат_перечисления.конда <<'KONDA'
#содержит <stdio.h>

перечисление Цвет {
    КРАСНЫЙ
    ЗЕЛЁНЫЙ
    СИНИЙ
}

Цвет любимый_цвет()
{
    вернуть ЗЕЛЁНЫЙ
}

целое32 точка_входа(срез<символ*> аргументы)
{
    Цвет ц = любимый_цвет()
    если (ц == ЗЕЛЁНЫЙ) {
        printf("зелёный\n")
    }
    вернуть 0
}
KONDA

"$BIN" возврат_перечисления.конда >"$TMP/возврат_перечисления.log" 2>&1 || {
    cat "$TMP/возврат_перечисления.log" >&2
    fail "возврат перечисления по значению должен транспилироваться"
}
assert_eq "зелёный" "$(./вывод/возврат_перечисления.elf)" "возврат перечисления: результат"

# Структура без деструктора по значению: обычное копирование (как в C).
cat > возврат_структуры.конда <<'KONDA'
#содержит <stdio.h>

структура Точка {
    целое32 х
    целое32 у
}

Точка создать(целое32 а, целое32 б)
{
    Точка п = { х = а, у = б }
    вернуть п
}

целое32 точка_входа(срез<символ*> аргументы)
{
    Точка т = создать(3, 4)
    printf("%d,%d\n", т.х, т.у)
    вернуть 0
}
KONDA

"$BIN" возврат_структуры.конда >"$TMP/возврат_структуры.log" 2>&1 || {
    cat "$TMP/возврат_структуры.log" >&2
    fail "возврат структуры без деструктора должен транспилироваться"
}
assert_eq "3,4" "$(./вывод/возврат_структуры.elf)" "возврат структуры: результат"

# Прямой вызов функции, возвращающей структуру, до её текстового определения
# (forward-прототип должен покрывать и такой тип возврата).
cat > возврат_структуры_forward.конда <<'KONDA'
#содержит <stdio.h>

структура Точка {
    целое32 х
}

целое32 точка_входа(срез<символ*> аргументы)
{
    Точка т = создать_точку()
    printf("%d\n", т.х)
    вернуть 0
}

Точка создать_точку()
{
    Точка п = { х = 99 }
    вернуть п
}
KONDA

"$BIN" возврат_структуры_forward.конда >"$TMP/возврат_структуры_forward.log" 2>&1 || {
    cat "$TMP/возврат_структуры_forward.log" >&2
    fail "вызов функции со структурным возвратом до её определения должен работать"
}
assert_eq "99" "$(./вывод/возврат_структуры_forward.elf)" "forward-вызов структурного возврата"

# Структуру, которой нужна деструкция (собственная или транзитивная), нельзя
# возвращать по значению — явная ошибка вместо риска двойного освобождения.
cat > возврат_структуры_деструктор.конда <<'KONDA'
#содержит <stdio.h>

[удалить = закрыть]
структура Ресурс {
    целое32 дескриптор
}

целое32 закрыть(Ресурс* р)
{
    printf("закрыто %d\n", р.дескриптор)
    вернуть 0
}

Ресурс создать()
{
    Ресурс р
    р.дескриптор = 42
    вернуть р
}

целое32 точка_входа(срез<символ*> аргументы)
{
    Ресурс р = создать()
    вернуть 0
}
KONDA

if "$BIN" возврат_структуры_деструктор.конда >"$TMP/возврат_структуры_деструктор.log" 2>&1; then
    cat "$TMP/возврат_структуры_деструктор.log" >&2
    fail "возврат структуры с деструктором по значению должен быть ошибкой"
fi
grep -q "нельзя возвращать по значению" "$TMP/возврат_структуры_деструктор.log" || {
    cat "$TMP/возврат_структуры_деструктор.log" >&2
    fail "ошибка возврата деструктор-структуры должна быть понятной"
}

# Многофайловый случай: функция в одном файле возвращает структуру,
# объявленную там же, вызывается из другого файла.
cat > возврат_структуры_файл_а.конда <<'KONDA'
структура Точка {
