}

Точка создать_точку(целое32 а, целое32 б)
{
    Точка п = { х = а, у = б }
    вернуть п
}
KONDA
cat > возврат_структуры_файл_б.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    Точка т = создать_точку(7, 8)
    printf("%d,%d\n", т.х, т.у)
    вернуть 0
}
KONDA

"$BIN" возврат_структуры_файл_б.конда возврат_структуры_файл_а.конда \
    >"$TMP/возврат_структуры_multifile.log" 2>&1 || {
