}
assert_eq "7,8" "$(./вывод/возврат_структуры_файл_б.elf)" "multi-file возврат структуры"

# ─── срез<T> как поле структуры (владение, autofree, запрет копирования) ────

# Базовый случай: литерал со срез-полем, «длина» и «для_каждого» по полю.
cat > поле_среза_базовое.конда <<'KONDA'
#содержит <stdio.h>

структура Буфер {
    срез<целое32> данные
    целое32 метка
}

целое32 точка_входа(срез<символ*> аргументы)
{
    Буфер б = { данные = выделить(4), метка = 42 }
    printf("%d %d\n", длина(б.данные), б.метка)
    вернуть 0
}
KONDA

"$BIN" поле_среза_базовое.конда >"$TMP/поле_среза_базовое.log" 2>&1 || {
    cat "$TMP/поле_среза_базовое.log" >&2
    fail "срез-поле структуры (литерал «выделить») должно транспилироваться"
}
assert_eq "4 42" "$(./вывод/поле_среза_базовое.elf)" "срез-поле: длина и соседнее поле"
grep -q "free(б.данные.данные)" вывод/поле_среза_базовое.c || {
    cat вывод/поле_среза_базовое.c >&2
    fail "срез-поле должно освобождаться при выходе структуры из области"
}

# Заимствование поля целиком как параметра функции (борроу, без move) + запись
# в срез внутри функции + для_каждого — типичный сценарий использования без
# прямого «структура.поле[индекс]» (структурное ограничение синтаксиса
# индексации, отдельное от владения — задокументировано как известное).
cat > поле_среза_заимствование.конда <<'KONDA'
#содержит <stdio.h>

структура Буфер {
    срез<целое32> данные
}

целое32 заполнить(срез<целое32> с)
{
    для целое32 к = 0; к < длина(с); к = к + 1 {
        с[к] = к * 10
    }
    вернуть 0
}

целое32 сумма(срез<целое32> с)
{
    целое32 итог = 0
    для_каждого э из с {
        итог = итог + э
    }
    вернуть итог
}

целое32 точка_входа(срез<символ*> аргументы)
{
    Буфер б = { данные = выделить(3) }
    заполнить(б.данные)
    printf("%d\n", сумма(б.данные))
    вернуть 0
}
KONDA

"$BIN" поле_среза_заимствование.конда >"$TMP/поле_среза_заимствование.log" 2>&1 || {
    cat "$TMP/поле_среза_заимствование.log" >&2
    fail "заимствование срез-поля как параметра функции должно работать"
}
assert_eq "30" "$(./вывод/поле_среза_заимствование.elf)" "срез-поле: заимствование в функции (0+10+20)"

# Структуру со срез-полем нельзя копировать/присваивать (двойной free).
cat > поле_среза_копия.конда <<'KONDA'
