# Инициализация поля структуры значением ДРУГОЙ владеющей структуры скопировала
# бы дескриптор владения (срез) → double-free при выходе из области. Должно
# отклоняться (регрессия: раньше компилировалось и падало с double-free в ASan).
cat > поле_копия_владельца.конда <<'KONDA'
структура Внутр {
    срез<целое32> данные
}
структура Внешн {
    Внутр в
}
целое32 точка_входа(срез<символ*> аргументы)
{
    Внутр вн = { данные = выделить(4) }
    Внешн о = { в = вн }
    вернуть 0
}
KONDA

if "$BIN" поле_копия_владельца.конда >"$TMP/поле_копия_владельца.log" 2>&1; then
    cat "$TMP/поле_копия_владельца.log" >&2
    fail "инициализация поля владеющей структурой должна отклоняться (иначе double-free)"
fi
grep -q "двойн" "$TMP/поле_копия_владельца.log" || {
    cat "$TMP/поле_копия_владельца.log" >&2
