}

# Копирование ОБЫЧНОЙ структуры (без владения) при объявлении «Тип б = а» —
# должно работать (регрессия: раньше объявление допускало только литерал/вызов,
# и естественная копия структуры-переменной отклонялась, хотя присваивание
# «б = а» её разрешало — несимметрично).
cat > копия_структуры_объявление.конда <<'KONDA'
#содержит <stdio.h>
структура Точка {
    целое32 х
    целое32 у
}
целое32 точка_входа(срез<символ*> аргументы)
{
    Точка а = { х = 3, у = 4 }
    Точка б = а
    printf("%d %d\n", б.х, б.у)
    вернуть 0
}
KONDA

"$BIN" копия_структуры_объявление.конда >"$TMP/копия_структуры_объявление.log" 2>&1 || {
    cat "$TMP/копия_структуры_объявление.log" >&2
