}
assert_eq "3 4" "$(./вывод/копия_структуры_объявление.elf)" "копия структуры при объявлении"

# Позиционный литерал структуры «{ выражение, … }» (значения в порядке полей) —
# наравне с именованным «{ поле = выражение, … }». Элементы могут быть любыми
# выражениями (в т.ч. «а.х + б.х»). Кодоген раскрывает их в designated-инициа-
# лизатор по индексу поля.
cat > литерал_позиционный.конда <<'KONDA'
#содержит <stdio.h>
структура Точка {
    целое32 х
    целое32 у
    целое32 з
}
Точка сложить(Точка а, Точка б)
{
    Точка р = { а.х + б.х, а.у + б.у, а.з + б.з }
    вернуть р
}
целое32 точка_входа(срез<символ*> аргументы)
{
    Точка а = { 1, 2, 3 }
    Точка б = { 10, 20, 30 }
    Точка в = сложить(а, б)
    printf("%d %d %d\n", в.х, в.у, в.з)
    вернуть 0
}
KONDA

"$BIN" литерал_позиционный.конда >"$TMP/литерал_позиционный.log" 2>&1 || {
    cat "$TMP/литерал_позиционный.log" >&2
    fail "позиционный литерал структуры должен компилироваться"
}
grep -q ".х = 1, .у = 2, .з = 3" вывод/литерал_позиционный.c || {
    cat вывод/литерал_позиционный.c >&2
    fail "позиционный литерал → designated-инициализатор по индексу поля"
}
assert_eq "11 22 33" "$(./вывод/литерал_позиционный.elf)" "позиционный литерал структуры"

# Позиционный литерал со СЛИШКОМ большим числом значений — ошибка (позиция > число полей).
