# ─── LSP / IDE API: konda_анализ через libkonda.so ──────────────────────────
# Компилируем C-потребителя, линкуем с библиотекой, проверяем: диагностики
# (предупреждение о неизвестной функции), список функций (Konda + внешние),
# список типов. Анализ идёт в памяти, без записи файлов и без вызова cc.
cat > "$TMP/ide_потребитель.c" <<'C_EOF'
#include <string.h>
#include <stdio.h>
#include "libkonda_ide.h"

int main(void) {
    const char *ист =
        "#содержит <stdio.h>\n"
        "структура Точка {\n    целое32 х\n}\n"
        "перечисление Цвет {\n    КРАСНЫЙ\n}\n"
        "целое32 удвоить(целое32 н)\n{\n    вернуть н + н\n}\n"
        "целое32 точка_входа(срез<символ*> аргументы)\n{\n"
        "    printf(\"%d\", удвоить(21))\n"
        "    неизвестная_фн_zzz(1)\n"
        "    вернуть 0\n}\n";
    КдРезультат *р = konda_анализ(ист, strlen(ист), NULL);
    int предупр = 0;
    for (size_t i = 0; i < р->число_диагностик; i++)
        if (р->диагностики[i].уровень == КД_ПРЕДУПРЕЖДЕНИЕ) предупр++;
    int есть_удвоить = 0, есть_printf = 0, есть_вход = 0;
    for (size_t i = 0; i < р->число_функций; i++) {
        if (!strcmp(р->функции[i].имя, "удвоить")
            && р->функции[i].вид == КД_ФУНКЦИЯ_KONDA
            && р->функции[i].строка > 0) есть_удвоить = 1;
        if (!strcmp(р->функции[i].имя, "printf")
            && р->функции[i].вид == КД_ФУНКЦИЯ_ВНЕШНЯЯ) есть_printf = 1;
        if (!strcmp(р->функции[i].имя, "точка_входа")) есть_вход = 1;
    }
    int есть_структура = 0, есть_перечисление = 0;
    for (size_t i = 0; i < р->число_типов; i++) {
        if (р->типы[i].вид == КД_ТИП_СТРУКТУРА) есть_структура = 1;
        if (р->типы[i].вид == КД_ТИП_ПЕРЕЧИСЛЕНИЕ) есть_перечисление = 1;
    }
    printf("%d %d %d %d %d %d\n", предупр, есть_удвоить, есть_printf,
           есть_вход, есть_структура, есть_перечисление);
    konda_освободить_результат(р);
    return 0;
}
C_EOF

cc -std=gnu23 -I "$ROOT" "$TMP/ide_потребитель.c" \
   -L "$ROOT/Собранное" -lkonda-transpiler -Wl,-rpath,"$ROOT/Собранное" \
   -o "$TMP/ide_потребитель" 2>"$TMP/ide_сборка.log" || {
    cat "$TMP/ide_сборка.log" >&2
    fail "C-потребитель LSP-API должен линковаться с libkonda"
}
# Ожидаем: 1 предупреждение, удвоить видна (Konda, с позицией), printf видна
# (внешняя), точка_входа видна, структура и перечисление в типах.
assert_eq "1 1 1 1 1 1" "$("$TMP/ide_потребитель")" "LSP-API: диагностики + функции + типы"

# ─── Батч-ошибки: все ошибки за один прогон (CLI + API) ─────────────────────
# Транспилятор не останавливается на первой семантической ошибке, а собирает
# все — чтобы IDE подсветила их разом, а CLI показал списком.
cat > многоошибок.конда <<'KONDA'
целое32 точка_входа(срез<символ*> аргументы)
{
    х = 5
    у = неизвестная + 3
    вернуть z
}
KONDA

"$BIN" многоошибок.конда >"$TMP/многоошибок.log" 2>&1 || true
# Все три необъявленные переменные (х, у, z) должны попасть в вывод.
grep -q "«х»" "$TMP/многоошибок.log" && \
grep -q "«у»" "$TMP/многоошибок.log" && \
grep -q "«z»" "$TMP/многоошибок.log" || {
    cat "$TMP/многоошибок.log" >&2
    fail "CLI должен показывать все ошибки за прогон, а не только первую"
}
grep -q "Всего ошибок: 3" "$TMP/многоошибок.log" || {
    cat "$TMP/многоошибок.log" >&2
    fail "CLI должен подытоживать общее число ошибок (3)"
}

# То же через LSP-API: три диагностики уровня ошибки за один анализ.
cat > "$TMP/батч_потребитель.c" <<'C_EOF'
#include <string.h>
#include <stdio.h>
#include "libkonda_ide.h"

int main(void) {
    const char *ист =
        "целое32 точка_входа(срез<символ*> аргументы)\n{\n"
        "    х = 5\n"
        "    у = неизвестная + 3\n"
        "    вернуть z\n}\n";
    КдРезультат *р = konda_анализ(ист, strlen(ист), NULL);
    int ошибок = 0;
    for (size_t i = 0; i < р->число_диагностик; i++)
        if (р->диагностики[i].уровень == КД_ОШИБКА) ошибок++;
    printf("%d\n", ошибок);
    konda_освободить_результат(р);
    return 0;
}
C_EOF

cc -std=gnu23 -I "$ROOT" "$TMP/батч_потребитель.c" \
   -L "$ROOT/Собранное" -lkonda-transpiler -Wl,-rpath,"$ROOT/Собранное" \
   -o "$TMP/батч_потребитель" 2>"$TMP/батч_сборка.log" || {
    cat "$TMP/батч_сборка.log" >&2
    fail "C-потребитель батч-API должен линковаться с libkonda"
}
assert_eq "3" "$("$TMP/батч_потребитель")" "LSP-API: все ошибки за один анализ (3)"

