# ─── Тип «логический» (bool) + литералы истина/ложь ─────────────────────────
# логический → C bool (C23); истина/ложь → true/false; годен как тип возврата,
# в условиях и как переменная.
cat > булев.конда <<'KONDA'
#содержит <stdio.h>

логический чётное(целое32 н)
{
    если (н % 2 == 0) { вернуть истина }
    иначе { вернуть ложь }
}

целое32 точка_входа(срез<символ*> аргументы)
{
    логический ф = чётное(10)
    если (ф) { printf("да\n") }
    иначе { printf("нет\n") }
    вернуть 0
}
KONDA

"$BIN" булев.конда >"$TMP/булев.log" 2>&1 || {
    cat "$TMP/булев.log" >&2
    fail "логический (bool) должен транспилироваться"
}
