    cat вывод/булев.c >&2
    fail "логический должен давать bool в C"
}
grep -q "return true" вывод/булев.c && grep -q "return false" вывод/булев.c || {
    cat вывод/булев.c >&2
    fail "истина/ложь должны давать true/false в C"
}
assert_eq "да" "$(./вывод/булев.elf)" "логический: чётное(10) = истина"

# ─── Операторы «прервать»/«продолжить» (break/continue) ─────────────────────
# Управление циклом: продолжить пропускает итерацию, прервать выходит из цикла.
cat > прервать_продолжить.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 сумма = 0
    для целое32 и = 0; и < 10; и = и + 1 {
        если (и == 3) { продолжить }
        если (и == 7) { прервать }
        сумма = сумма + и
    }
    printf("%d\n", сумма)
    вернуть 0
}
KONDA

"$BIN" прервать_продолжить.конда >"$TMP/прерв.log" 2>&1 || {
    cat "$TMP/прерв.log" >&2
    fail "прервать/продолжить должны транспилироваться"
}
grep -q "break;" вывод/прервать_продолжить.c && grep -q "continue;" вывод/прервать_продолжить.c || {
    cat вывод/прервать_продолжить.c >&2
    fail "прервать/продолжить должны давать break/continue в C"
}
# 0+1+2 (и=3 пропущено) +4+5+6 (и=7 обрывает) = 18
assert_eq "18" "$(./вывод/прервать_продолжить.elf)" "прервать/продолжить: сумма 0..6 без 3 = 18"

# Негатив: «прервать» вне цикла — ошибка семантики с позицией.
cat > прервать_вне_цикла.конда <<'KONDA'
целое32 точка_входа(срез<символ*> аргументы)
{
    прервать
    вернуть 0
}
KONDA

if "$BIN" прервать_вне_цикла.конда >"$TMP/прерв_вне.log" 2>&1; then
    cat "$TMP/прерв_вне.log" >&2
    fail "«прервать» вне цикла должно быть ошибкой"
fi
