    fail "ошибка «прервать вне цикла» должна быть понятной"
}

# «пока (истина)» с «прервать» не считается расходящимся: non-void функция без
# гарантированного возврата после такого цикла — ошибка all-paths.
cat > пока_с_прервать.конда <<'KONDA'
целое32 ф(целое32 н)
{
    пока (истина) {
        если (н > 0) { прервать }
        н = н + 1
    }
}
KONDA

if "$BIN" пока_с_прервать.конда >"$TMP/пока_прерв.log" 2>&1; then
    cat "$TMP/пока_прерв.log" >&2
    fail "«пока(истина)» с «прервать» не расходящийся — нужен возврат после"
fi
grep -q "не возвращает значение по всем путям" "$TMP/пока_прерв.log" || {
    cat "$TMP/пока_прерв.log" >&2
    fail "цикл с прервать не должен считаться гарантирующим возврат"
}

# ─── «цикл { … }» — бесконечный цикл (Rust `loop`); десугар в «пока истина» ──
# База: счётчик с выходом через «прервать» + «продолжить».
cat > цикл_база.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 сумма = 0
    целое32 и = 0
    цикл {
        и = и + 1
        если и > 10 { прервать }
        если и % 2 == 1 { продолжить }
        сумма = сумма + и
    }
    printf("%d\n", сумма)
    вернуть 0
}
KONDA
"$BIN" цикл_база.конда >"$TMP/цикл_база.log" 2>&1 || {
    cat "$TMP/цикл_база.log" >&2; fail "«цикл { }» должен транспилироваться"; }
grep -q "while (true)" вывод/цикл_база.c || {
    cat вывод/цикл_база.c >&2; fail "«цикл» должен давать while(true) в C"; }
assert_eq "30" "$(./вывод/цикл_база.elf)" "цикл: сумма чётных 2..10 = 30"

# Дивергенция как в Rust: функция с возвратом ТОЛЬКО внутри «цикл» (без «прервать»)
# не требует возврата после — цикл не завершается нормально.
cat > цикл_дивергенция.конда <<'KONDA'
#содержит <stdio.h>
целое32 первый_чётный(целое32 старт)
{
    целое32 и = старт
    цикл {
        если и % 2 == 0 { вернуть и }
        и = и + 1
    }
}
целое32 точка_входа(срез<символ*> аргументы)
{
    printf("%d\n", первый_чётный(7))
    вернуть 0
}
KONDA
"$BIN" цикл_дивергенция.конда >"$TMP/цикл_див.log" 2>&1 || {
    cat "$TMP/цикл_див.log" >&2
    fail "«цикл» с возвратом внутри (без прервать) должен расходиться — возврат после не нужен"; }
assert_eq "8" "$(./вывод/цикл_дивергенция.elf)" "цикл: дивергенция, возврат изнутри"

# «цикл» — контекстное слово: остаётся валидным ИМЕНЕМ переменной.
cat > цикл_имя.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
