# ─── CLI «--код=<исходник>» — исходник строкой-аргументом (быстрые тесты) ─────
# Транслируется без временного файла; вывод в вывод/код.* (имя по --имя).
SRC='#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    printf("инлайн %d\n", 7)
    вернуть 0
