# ─── Обобщённые функции (generics, мономорфизация) ──────────────────────────
# «имя<T>(…)» разворачивается в специализацию под каждый конкретный тип-аргумент
# (максимум_целое32, максимум_вещественное64) ещё до семантики.
cat > обобщённая_максимум.конда <<'KONDA'
#содержит <stdio.h>

T максимум<T>(T а, T б)
{
    если (а > б) { вернуть а }
    иначе { вернуть б }
}

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 ц = максимум<целое32>(3, 9)
    вещественное64 в = максимум<вещественное64>(2.5, 1.5)
    printf("%d %f\n", ц, в)
    вернуть 0
}
KONDA

"$BIN" обобщённая_максимум.конда >"$TMP/обобщ.log" 2>&1 || {
    cat "$TMP/обобщ.log" >&2
    fail "обобщённая функция должна транспилироваться"
}
grep -q "int32_t максимум_целое32" вывод/обобщённая_максимум.c \
    && grep -q "double максимум_вещественное64" вывод/обобщённая_максимум.c || {
    cat вывод/обобщённая_максимум.c >&2
    fail "мономорфизация должна создать специализации под каждый тип"
}
assert_eq "9 2.500000" "$(./вывод/обобщённая_максимум.elf)" "generics: максимум на двух типах"

# Транзитивность: обобщённая функция вызывает другую обобщённую; тип-аргумент —
# пользовательская структура.
cat > обобщённая_транзит.конда <<'KONDA'
#содержит <stdio.h>

структура Точка {
    целое32 х
    целое32 у
}

T тождество<T>(T значение) { вернуть значение }

T обёртка<T>(T з) { вернуть тождество<T>(з) }

целое32 точка_входа(срез<символ*> аргументы)
{
    Точка п = { х = 3, у = 7 }
    Точка р = обёртка<Точка>(п)
    printf("%d %d\n", р.х, р.у)
    вернуть 0
}
KONDA

