# ─── Вывод тип-аргументов (generics, гибрид: семантика аннотирует) ───────────
# «макс(1, 2)» ≡ «макс<целое32>(1, 2)»: тип-аргумент выводится из КОНКРЕТНЫХ
# типов аргументов ещё до мономорфизации (проход вывода типизирует аргументы
# реальным типизатором и дописывает «<>»). Иначе — нужны явные тип-аргументы.
cat > вывод_типоаргументов.конда <<'KONDA'
#содержит <stdio.h>

структура Точка { }

T максимум<T>(T а, T б)
{
    если (а > б) { вернуть а }
    иначе { вернуть б }
}

T тождество<T>(T з) { вернуть з }

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 ц = максимум(3, 9)              // вывод T=целое32 из литералов
    вещественное64 д = 2.5
    вещественное64 е = 1.5
    вещественное64 в = максимум(д, е)        // вывод T=вещественное64 из переменных
    целое32 н = тождество(тождество(7))      // вложенный вывод
    printf("%d %f %d\n", ц, в, н)
    вернуть 0
}
KONDA

"$BIN" вывод_типоаргументов.конда >"$TMP/вывод_та.log" 2>&1 || {
    cat "$TMP/вывод_та.log" >&2
    fail "вывод тип-аргументов должен транспилироваться"
}
grep -q "максимум_целое32" вывод/вывод_типоаргументов.c \
    && grep -q "максимум_вещественное64" вывод/вывод_типоаргументов.c \
    && grep -q "тождество_целое32" вывод/вывод_типоаргументов.c || {
    cat вывод/вывод_типоаргументов.c >&2
    fail "вывод должен создать специализации под выведенные типы"
}
assert_eq "9 2.500000 7" "$(./вывод/вывод_типоаргументов.elf)" \
    "generics: вывод тип-аргументов (литералы, переменные, вложенность)"

# Смешанно: часть вызовов с явными «<>», часть — с выводом (совместимо).
cat > вывод_смешанный.конда <<'KONDA'
#содержит <stdio.h>

T тождество<T>(T з) { вернуть з }

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 x = тождество<целое32>(5)   // явный
    целое32 y = тождество(8)            // выведенный
    printf("%d\n", x + y)
    вернуть 0
}
KONDA

"$BIN" вывод_смешанный.конда >"$TMP/вывод_см.log" 2>&1 || {
    cat "$TMP/вывод_см.log" >&2
    fail "смешанные явные/выведенные тип-аргументы должны транспилироваться"
}
assert_eq "13" "$(./вывод/вывод_смешанный.elf)" "generics: явные + выведенные вместе"

# Негатив: вывести T нельзя (T только в типе возврата, в аргументах его нет) —
# понятная ошибка «укажите явно», а не смутное «функция не объявлена».
cat > вывод_невозможен.конда <<'KONDA'
целое32 сделать<T>(целое32 к) { вернуть к }
целое32 точка_входа(срез<символ*> аргументы)
{
    вернуть сделать(5)
}
KONDA

