# ─── Обобщённые структуры (generics, мономорфизация типов) ───────────────────
# «структура Пара<T> { … }» разворачивается в отдельный C-тип под каждый набор
# тип-аргументов (Пара_целое32, Пара_вещественное) ещё до семантики. Поля —
# примитивы/указатели (срез<T> в v1 не поддержан). Проверяем две инстанции,
# передачу в функции по значению и корректность полей.
cat > обобщённая_структура.конда <<'KONDA'
#содержит <stdio.h>

структура Пара<T> {
    T первый
    T второй
}

целое32 сумма(Пара<целое32> п) { вернуть п.первый + п.второй }
вещественное площадь(Пара<вещественное> п) { вернуть п.первый * п.второй }

целое32 точка_входа(срез<символ*> аргументы)
{
    Пара<целое32> ц
    ц.первый = 3
    ц.второй = 4
    Пара<вещественное> в
    в.первый = 2.0
    в.второй = 5.0
    printf("%d %.1f\n", сумма(ц), площадь(в))
    вернуть 0
}
KONDA

"$BIN" обобщённая_структура.конда >"$TMP/обобщ_с.log" 2>&1 || {
    cat "$TMP/обобщ_с.log" >&2
    fail "обобщённая структура должна транспилироваться"
}
grep -q "Пара_целое32" вывод/обобщённая_структура.c \
    && grep -q "Пара_вещественное" вывод/обобщённая_структура.c || {
    cat вывод/обобщённая_структура.c >&2
    fail "мономорфизация структуры должна создать тип под каждый тип-аргумент"
}
grep -q "struct Пара" вывод/обобщённая_структура.c && {
    cat вывод/обобщённая_структура.c >&2
    fail "шаблон структуры (с тип-параметром) не должен попадать в C"
}
assert_eq "7 10.0" "$(./вывод/обобщённая_структура.elf)" "generics: обобщённая структура на двух типах"

# Обобщённая ФУНКЦИЯ над обобщённой СТРУКТУРОЙ: «первый_из<T>(Пара<T>)» —
# специализация функции подставляет T в тип-аргумент структуры, затем
# порождается сама специализация структуры. Указательный тип-аргумент тоже.
cat > обобщённая_структура_функция.конда <<'KONDA'
#содержит <stdio.h>

структура Пара<T> {
    T первый
    T второй
}

T первый_из<T>(Пара<T> п) { вернуть п.первый }

целое32 точка_входа(срез<символ*> аргументы)
{
    Пара<целое32> ц
    ц.первый = 42
    ц.второй = 7
    Пара<символ*> с
    с.первый = "привет"
    с.второй = "мир"
    printf("%d %s\n", первый_из<целое32>(ц), с.первый)
    вернуть 0
}
KONDA

"$BIN" обобщённая_структура_функция.конда >"$TMP/обобщ_сф.log" 2>&1 || {
    cat "$TMP/обобщ_сф.log" >&2
    fail "обобщённая функция над обобщённой структурой должна транспилироваться"
}
grep -q "первый_из_целое32(Пара_целое32" вывод/обобщённая_структура_функция.c || {
    cat вывод/обобщённая_структура_функция.c >&2
    fail "специализация функции должна ссылаться на специализацию структуры"
}
grep -q "Пара_символ_у" вывод/обобщённая_структура_функция.c || {
    cat вывод/обобщённая_структура_функция.c >&2
    fail "указательный тип-аргумент должен давать Пара_символ_у"
}
