# ─── Указательный тип возврата «Тип*» (безопасный borrow) ───────────────────
# Вернуть можно только указатель на память, которая переживёт возврат и
# принадлежит вызывающему/статике: параметр-указатель, «аргументы», строковый
# литерал, «нуль». Локальные данные и результаты C-функций — ошибка (иначе
# висячий указатель / ручное управление памятью).
cat > возврат_указателя.конда <<'KONDA'
#содержит <stdio.h>
#содержит <string.h>

символ* подлиннее(символ* а, символ* б)
{
    если (strlen(а) >= strlen(б)) { вернуть а }
    иначе { вернуть б }
}

символ* или_нуль(символ* с, логический есть)
{
    если (есть) { вернуть с }
    вернуть нуль
}

целое32 точка_входа(срез<символ*> аргументы)
{
    символ* р = подлиннее("привет", "мир")
    printf("%s\n", р)
    вернуть 0
}
KONDA

"$BIN" возврат_указателя.конда >"$TMP/возвук.log" 2>&1 || {
    cat "$TMP/возвук.log" >&2
    fail "возврат указателя-параметра (borrow) должен транспилироваться"
}
grep -q "char\* подлиннее" вывод/возврат_указателя.c || {
    cat вывод/возврат_указателя.c >&2
    fail "указательный тип возврата должен давать «char*» в C"
}
assert_eq "привет" "$(./вывод/возврат_указателя.elf)" "возврат указателя-параметра работает"

# Негатив 1: возврат локального массива (decay → висячий указатель).
cat > возврат_локмассив.конда <<'KONDA'
символ* опасно()
{
    символ буфер[8]
    вернуть буфер
}
целое32 точка_входа(срез<символ*> аргументы) { вернуть 0 }
KONDA
