# ─── Союзы (union) ──────────────────────────────────────────────────────────
# «союз Имя { … }» → «typedef union»; поля разделяют память. Доступ к члену
# союза — type confusion, поэтому разрешён только в «небезопасно { }».
cat > союз_базовый.конда <<'KONDA'
#содержит <stdio.h>
союз Значение {
    целое32 ц
    вещественное в
}
целое32 точка_входа(срез<символ*> аргументы)
{
    Значение з = { ц = 42 }
    небезопасно {
        printf("%d\n", з.ц)
        з.в = 3.5
        printf("%f\n", з.в)
    }
    вернуть 0
}
KONDA
"$BIN" союз_базовый.конда >"$TMP/союз.log" 2>&1 || {
    cat "$TMP/союз.log" >&2
    fail "союз должен транспилироваться"
