3.500000" "$(./вывод/союз_базовый.elf)" "союз: доступ к полям через общую память"

# «небезопасно» для доступа к союзу не имеет рантайм-цены (обычный C-блок).
grep -q ")срез_доступ(" вывод/союз_базовый.c && {
