# ─── Указатели на функцию (типфункции) ──────────────────────────────────────
# «типфункции RET Имя(типы)» → typedef; присваивание функции по совпадающей
# сигнатуре; вызов через указатель; передача функции как аргумента (колбэк).
cat > функуказатель.конда <<'KONDA'
#содержит <stdio.h>
типфункции целое32 БинарОп(целое32, целое32)

целое32 сложить(целое32 а, целое32 б) { вернуть а + б }
целое32 умножить(целое32 а, целое32 б) { вернуть а * б }
целое32 применить(БинарОп ф, целое32 х, целое32 у) { вернуть ф(х, у) }

целое32 точка_входа(срез<символ*> аргументы)
{
    БинарОп оп = сложить
    printf("%d\n", оп(3, 4))
    оп = умножить
    printf("%d\n", оп(3, 4))
    printf("%d\n", применить(сложить, 10, 20))
    вернуть 0
}
KONDA
"$BIN" функуказатель.конда >"$TMP/фук.log" 2>&1 || {
    cat "$TMP/фук.log" >&2
    fail "указатель на функцию должен транспилироваться"
}
grep -q "typedef int32_t (\*БинарОп)(int32_t, int32_t)" вывод/функуказатель.c || {
    cat вывод/функуказатель.c >&2
    fail "типфункции должно давать typedef указателя на функцию"
}
