# ─── Параметры по ссылке: «изменяемый» (ref) и «вывод» (out) ────────────────
# Как C# ref/out — безопасно: программист не пишет «&»/«*», заимствование заперто
# внутри вызова. Кодоген передаёт Тип*, авто-разыменовывает в теле, ставит «&».
cat > ссылочные_параметры.конда <<'KONDA'
#содержит <stdio.h>
ничего удвоить(изменяемый целое32 х) { х = х + х }
ничего разделить(целое32 а, целое32 б, вывод целое32 частное, вывод целое32 остаток)
{
    частное = а / б
    остаток = а % б
}
целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 н = 21
    удвоить(н)
    целое32 ч
    целое32 о
    разделить(17, 5, ч, о)
    printf("%d %d %d\n", н, ч, о)
    вернуть 0
}
KONDA
"$BIN" ссылочные_параметры.конда >"$TMP/рефаут.log" 2>&1 || {
    cat "$TMP/рефаут.log" >&2
    fail "ref/out параметры должны транспилироваться"
}
grep -q "void удвоить(int32_t \*х)" вывод/ссылочные_параметры.c \
    && grep -q "удвоить(&н)" вывод/ссылочные_параметры.c || {
    cat вывод/ссылочные_параметры.c >&2
    fail "ref/out параметр → Тип* и «&» на вызове"
}
assert_eq "42 3 2" "$(./вывод/ссылочные_параметры.elf)" "ref мутирует, out возвращает несколько значений"

