# ─── Пространства имён ──────────────────────────────────────────────────────
# «пространство Имя { … }» → имена квалифицируются «Имя::…» и манглятся в C как
# «Имя__…». Квалифицированный доступ «Имя::член», внутри — неквалифицированный.
cat > пространство_квалиф.конда <<'KONDA'
#содержит <stdio.h>
пространство Графика {
    структура Точка {
        целое32 х
        целое32 у
    }
    целое32 площадь(Точка п) { вернуть п.х * п.у }
}

целое32 точка_входа(срез<символ*> аргументы)
{
    Графика::Точка т = { х = 3, у = 4 }
    printf("%d\n", Графика::площадь(т))
    вернуть 0
}
KONDA
"$BIN" пространство_квалиф.конда >"$TMP/прк.log" 2>&1 || {
    cat "$TMP/прк.log" >&2
    fail "пространство с квалифицированным доступом должно транспилироваться"
}
grep -q "Графика__Точка" вывод/пространство_квалиф.c \
    && grep -q "Графика__площадь" вывод/пространство_квалиф.c || {
    cat вывод/пространство_квалиф.c >&2
    fail "имена пространства должны манглиться как Имя__член"
}
assert_eq "12" "$(./вывод/пространство_квалиф.elf)" "пространство: квалиф. тип и вызов"

# «использовать» — импорт: неквалифицированные обращения к членам пространства,
# и вызовы соседних членов внутри пространства.
cat > пространство_импорт.конда <<'KONDA'
#содержит <stdio.h>
пространство Матем {
    целое32 квадрат(целое32 х) { вернуть х * х }
    целое32 сумма_квадратов(целое32 а, целое32 б) { вернуть квадрат(а) + квадрат(б) }
}

использовать Матем

целое32 точка_входа(срез<символ*> аргументы)
{
    printf("%d\n", сумма_квадратов(3, 4))
    вернуть 0
}
KONDA
"$BIN" пространство_импорт.конда >"$TMP/при.log" 2>&1 || {
    cat "$TMP/при.log" >&2
    fail "использовать (импорт) должен транспилироваться"
}
grep -q "Матем__сумма_квадратов" вывод/пространство_импорт.c || {
    cat вывод/пространство_импорт.c >&2
    fail "импорт должен резолвить неквалифицированные обращения"
}
assert_eq "25" "$(./вывод/пространство_импорт.elf)" "пространство: импорт + вызов соседа"

# Два пространства с одинаковым именем типа не конфликтуют (разные C-имена).
cat > пространство_разделение.конда <<'KONDA'
#содержит <stdio.h>
пространство А {
    структура Т { целое32 з }
    целое32 дай(Т т) { вернуть т.з }
}
пространство Б {
    структура Т { целое32 ж }
    целое32 дай(Т т) { вернуть т.ж + 100 }
}
целое32 точка_входа(срез<символ*> аргументы)
{
    А::Т х = { з = 5 }
    Б::Т у = { ж = 7 }
    printf("%d %d\n", А::дай(х), Б::дай(у))
    вернуть 0
}
KONDA
"$BIN" пространство_разделение.конда >"$TMP/прр.log" 2>&1 || {
    cat "$TMP/прр.log" >&2
    fail "одноимённые типы в разных пространствах не должны конфликтовать"
}
assert_eq "5 107" "$(./вывод/пространство_разделение.elf)" "пространства: изоляция одноимённых типов"

# ─── Гейт сырых указателей: «небезопасно { }» ───────────────────────────────
# Арифметика указателей и индексация сырого указателя запрещены в безопасном
# коде статически (без рантайм-цены) и разрешены только внутри «небезопасно».

# Негатив: арифметика указателя вне «небезопасно» — ошибка компиляции.
cat > гейт_арифметика.конда <<'KONDA'
целое32 точка_входа(срез<символ*> аргументы)
{
    символ* с = аргументы[0]
    символ* д = с + 1
    вернуть 0
}
KONDA
if "$BIN" гейт_арифметика.конда >"$TMP/гейт_ар.log" 2>&1; then
    fail "арифметика указателя вне «небезопасно» должна быть ошибкой"
fi
grep -q "арифметика указателей запрещена" "$TMP/гейт_ар.log" || {
    cat "$TMP/гейт_ар.log" >&2; fail "понятная ошибка арифметики указателя"; }

# Негатив: индексация сырого (ненулевого) указателя вне «небезопасно» — ошибка.
cat > гейт_индекс.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    символ* с = "abc"
    printf("%c\n", с[1])
    вернуть 0
}
KONDA
if "$BIN" гейт_индекс.конда >"$TMP/гейт_ин.log" 2>&1; then
    fail "индексация сырого указателя вне «небезопасно» должна быть ошибкой"
fi
grep -q "индексация сырого указателя" "$TMP/гейт_ин.log" || {
    cat "$TMP/гейт_ин.log" >&2; fail "понятная ошибка индексации сырого указателя"; }

# Позитив: те же операции внутри «небезопасно» — компилируются и работают.
cat > гейт_ок.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    небезопасно {
        символ* с = "abcd"
        символ* д = с + 2
        printf("%c%c\n", с[1], д[0])
    }
    вернуть 0
}
KONDA
"$BIN" гейт_ок.конда >"$TMP/гейт_ок.log" 2>&1 || {
    cat "$TMP/гейт_ок.log" >&2; fail "операции с указателями внутри «небезопасно»"; }
assert_eq "bc" "$(./вывод/гейт_ок.elf)" "небезопасно: арифметика+индексация работают"

# «небезопасно» не имеет рантайм-цены: в C — обычный блок, никаких проверок.
grep -q ")срез_доступ(" вывод/гейт_ок.c && {
    cat вывод/гейт_ок.c >&2; fail "«небезопасно» не должно добавлять рантайм-проверок"; }
grep -q "^    {$" вывод/гейт_ок.c || {
    cat вывод/гейт_ок.c >&2; fail "«небезопасно» должно эмитить обычный C-блок"; }

# Релиз ничего не меняет для гейта (проверка статическая): та же ошибка.
if "$BIN" --релиз гейт_индекс.конда >"$TMP/гейт_рел.log" 2>&1; then
    fail "гейт указателей действует и в релизе (статическая проверка)"
fi
grep -q "индексация сырого указателя" "$TMP/гейт_рел.log" || { cat "$TMP/гейт_рел.log" >&2; fail "гейт_индекс_релиз: ожидалась конкретная диагностика, не любая ошибка"; }

# ─── Гейт небезопасных функций libc (переполнение буфера) ───────────────────
# strcpy/gets/sprintf и подобные с неограниченной записью запрещены в безопасном
# коде статически; разрешены только в «небезопасно { }».
cat > гейт_libc.конда <<'KONDA'
#содержит <stdio.h>
#содержит <string.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    символ* д = "буфер______"
    strcpy(д, "текст")
    вернуть 0
}
KONDA
if "$BIN" гейт_libc.конда >"$TMP/гейт_libc.log" 2>&1; then
    fail "вызов strcpy вне «небезопасно» должен быть ошибкой"
fi
grep -q "небезопасна (возможно переполнение" "$TMP/гейт_libc.log" || {
    cat "$TMP/гейт_libc.log" >&2; fail "понятная ошибка о небезопасной функции libc"; }

# Позитив: тот же вызов внутри «небезопасно» — транспилируется и компилируется.
cat > гейт_libc_ок.конда <<'KONDA'
#содержит <stdio.h>
#содержит <string.h>
целое32 точка_входа(срез<символ*> аргументы)
{
