        printf("%s\n", д)
    }
    вернуть 0
}
KONDA
"$BIN" гейт_libc_ок.конда >"$TMP/гейт_libc_ок.log" 2>&1 || {
    cat "$TMP/гейт_libc_ок.log" >&2; fail "strcpy внутри «небезопасно» должен компилироваться"; }
assert_eq "текст" "$(./вывод/гейт_libc_ок.elf)" "небезопасно: strcpy работает"

# Гейт статический — та же ошибка и в релизе, нулевая рантайм-цена.
if "$BIN" --релиз гейт_libc.конда >"$TMP/гейт_libc_рел.log" 2>&1; then
    fail "гейт libc действует и в релизе (статическая проверка)"
fi
grep -q "небезопасна" "$TMP/гейт_libc_рел.log" || { cat "$TMP/гейт_libc_рел.log" >&2; fail "гейт_libc_релиз: ожидалась конкретная диагностика, не любая ошибка"; }

# Безопасные функции libc (printf, strlen) НЕ затронуты гейтом.
