KONDA
if "$BIN" конст_изменяемый.конда >"$TMP/конст_изменяемый.log" 2>&1; then
    fail "передача конст в «изменяемый» должна быть ошибкой"
fi
grep -q "«конст»-переменную нельзя передать" "$TMP/конст_изменяемый.log" || {
    cat "$TMP/конст_изменяемый.log" >&2; fail "понятная ошибка передачи конст в изменяемый"; }

# Негатив: мутация элемента конст-среза — ошибка.
cat > конст_срез.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    конст срез<целое32> д = выделить(3)
    д[0] = 1
    вернуть 0
}
KONDA
if "$BIN" конст_срез.конда >"$TMP/конст_срез.log" 2>&1; then
    fail "мутация элемента конст-среза должна быть ошибкой"
fi
grep -q "неизменяема" "$TMP/конст_срез.log" || {
    cat "$TMP/конст_срез.log" >&2; fail "понятная ошибка мутации конст-среза"; }

# Гейт статический — та же ошибка и в релизе.
if "$BIN" --релиз конст_переприсв.конда >"$TMP/конст_рел.log" 2>&1; then
    fail "иммутабельность действует и в релизе (статическая проверка)"
fi
grep -q "неизменяема" "$TMP/конст_рел.log" || { cat "$TMP/конст_рел.log" >&2; fail "конст_переприсв_релиз: ожидалась конкретная диагностика, не любая ошибка"; }

# ─── Устранение проверки границ по охраннику «если (и < длина(с))» ───────────
# Беззнаковый индекс под охранником «если (и < длина(с))» доказанно в границах
# (и ≥ 0 из беззнаковости, и < длина из условия) → прямой доступ без рантайм-
# проверки. Безопасность не теряется, а код быстрее.
cat > граница_охранник.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> д = выделить(5)
    д[0] = 10
    д[1] = 20
    неподписанный целое32 и = как<неподписанный целое32>(длина(аргументы))
    если (и < длина(д)) {
        printf("%d\n", д[и])
    } иначе {
        printf("вне\n")
    }
    вернуть 0
}
KONDA
"$BIN" граница_охранник.конда >"$TMP/граница_охранник.log" 2>&1 || {
    cat "$TMP/граница_охранник.log" >&2; fail "охранник границ должен компилироваться"; }
assert_eq "20" "$(./вывод/граница_охранник.elf)" "охранник: д[и] при и=1 = 20 (корректно)"
# Доступ под охранником — прямой, без рантайм-проверки среза. Грепаем именно
# ВЫЗОВ «…)срез_доступ(» (определение-хелпер «void *срез_доступ(» есть всегда).
grep -q ")срез_доступ(" вывод/граница_охранник.c && {
    cat вывод/граница_охранник.c >&2
    fail "доступ под охранником «и < длина(с)» должен быть без рантайм-проверки"; }

# Контраст: ЗНАКОВЫЙ индекс под тем же охранником НЕ устраняется (и мог бы быть
# отрицательным) — рантайм-проверка сохраняется (безопасность важнее скорости).
cat > граница_охранник_знак.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> д = выделить(5)
    д[1] = 20
    целое32 и = как<целое32>(длина(аргументы))
    если (и < длина(д)) {
        printf("%d\n", д[и])
    }
    вернуть 0
}
KONDA
"$BIN" граница_охранник_знак.конда >"$TMP/граница_охранник_знак.log" 2>&1 || {
    cat "$TMP/граница_охранник_знак.log" >&2; fail "знаковый охранник должен компилироваться"; }
assert_eq "20" "$(./вывод/граница_охранник_знак.elf)" "знаковый охранник: корректный вывод"
grep -q ")срез_доступ(" вывод/граница_охранник_знак.c || {
    cat вывод/граница_охранник_знак.c >&2
    fail "знаковый индекс должен сохранять рантайм-проверку границ"; }

# ─── Безопасный путь 2: интерфейс Konda-библиотек ───────────────────────────
# --библиотека эмитит «.и» с полными сигнатурами; потребитель авто-грузит его
# рядом с «.h» и проверяет вызовы по типам/владению; «.so» линкуется сам.
cat > либа.конда <<'KONDA'
целое32 сумма(срез<целое32> с)
{
    целое32 итог = 0
    для_каждого в из с { итог = итог + в }
    вернуть итог
}
ничего утроить(изменяемый целое32 х)
{
    х = х * 3
}
KONDA
"$BIN" --библиотека либа.конда >"$TMP/либа.log" 2>&1 || { cat "$TMP/либа.log" >&2; fail "сборка библиотеки"; }
[ -f вывод/либа.и ] || fail "интерфейс .и должен быть создан"
grep -q "^Ф сумма" вывод/либа.и || fail ".и: функция сумма"
grep -q "^П целое32 0 0 1 0 0 0" вывод/либа.и || fail ".и: параметр-срез (срез=1)"
grep -q "^П целое32 0 0 0 0 0 1" вывод/либа.и || fail ".и: изменяемый (по_ссылке=1)"

# Потребитель: корректный вызов → транспиляция + автолинковка + запуск.
cat > потр.конда <<'KONDA'
#содержит <stdio.h>
#содержит "вывод/либа.h"
целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> с = выделить(3)
    с[0] = 10
    с[1] = 20
    с[2] = 30
    целое32 р = сумма(с)
    целое32 х = 5
    утроить(х)
    printf("%d %d\n", р, х)
    вернуть 0
}
KONDA
"$BIN" потр.конда >"$TMP/потр.log" 2>&1 || { cat "$TMP/потр.log" >&2; fail "потребитель должен транспилироваться и линковаться"; }
grep -q "либа.so" "$TMP/потр.log" || { cat "$TMP/потр.log" >&2; fail "должна быть автолинковка либа.so"; }
assert_eq "60 15" "$(./вывод/потр.elf)" "путь 2: сквозной прогон с автолинковкой"

# Главный выигрыш: владение (изменяемый) проверяется ЧЕРЕЗ границу библиотеки.
cat > потр_плохо.конда <<'KONDA'
#содержит "вывод/либа.h"
целое32 точка_входа(срез<символ*> аргументы)
{
    утроить(5)
    вернуть 0
}
KONDA
if "$BIN" потр_плохо.конда >"$TMP/потр_плохо.log" 2>&1; then
    fail "передача не-lvalue в «изменяемый» библиотеки должна быть ошибкой"
fi
grep -q "должен быть переменной" "$TMP/потр_плохо.log" || {
    cat "$TMP/потр_плохо.log" >&2; fail "ожидалась Konda-ошибка ref/out через границу"; }

# Fallback: без «.и» вызов библиотеки — непрозрачный внешний C (проверка ref/out
# НЕ срабатывает); интерфейс её и включает.
mv вывод/либа.и вывод/либа.и.скрыт
"$BIN" потр_плохо.конда >"$TMP/потр_fb.log" 2>&1 || true
if grep -q "должен быть переменной" "$TMP/потр_fb.log"; then
    fail "без .и ref/out-проверки быть не должно (fallback к непрозрачному C)"
fi
mv вывод/либа.и.скрыт вывод/либа.и

# ─── Именованные типы через «.и»: структуры и sum-перечисления ───────────────
# v2: библиотека экспортирует структуры (примитивные поля) и sum-перечисления
# с payload; потребитель РЕКОНСТРУИРУЕТ их как полноценные типы (литералы,
# выбор, доступ к полям, RAII-деструктор), а C-определения приходят из «.h».
cat > либа2.конда <<'KONDA'
[удалить = _закрыть]
структура Файл {
    целое32 фд
}
целое32 _закрыть(Файл* ф)
{
    ф.фд = -1
    вернуть 0
}
перечисление Результат {
    Успех(целое64 значение)
    Провал(целое32 код)
}
Результат проверить(изменяемый Файл ф, изменяемый целое32 фд_копия)
{
    фд_копия = ф.фд
    вернуть Успех(7)
}
KONDA
"$BIN" --библиотека либа2.конда >"$TMP/либа2.log" 2>&1 || { cat "$TMP/либа2.log" >&2; fail "сборка либы с типами"; }
[ -f вывод/либа2.и ] || fail "либа2: должен быть .и"
grep -q "^С Файл _закрыть" вывод/либа2.и || fail "либа2: .и структура с деструктором"
grep -q "^Поле целое32 0 0 0 0 - фд" вывод/либа2.и || fail "либа2: .и поле структуры"
grep -q "^Е Результат" вывод/либа2.и || fail "либа2: .и sum-перечисление"
grep -q "^ВП целое64 0 0 0 - значение" вывод/либа2.и || fail "либа2: .и payload варианта"
grep -q "^П структура 0 1 0 0 0 0 Файл" вывод/либа2.и || fail "либа2: .и параметр-структура"
grep -q "^В перечисление 0 0 0 Результат" вывод/либа2.и || fail "либа2: .и возврат-перечисление"

# Потребитель: структура из библиотеки объявляется/конструируется/передаётся,
# sum-тип обрабатывается выбором, деструктор зовётся автоматически.
cat > потр2.конда <<'KONDA'
#содержит "вывод/либа2.h"
#содержит <stdio.h>
структура ЧужойФайл {
    целое32 фд
}
целое32 точка_входа(срез<символ*> аргументы)
{
    Файл ф = { фд = 42 }
    целое32 копия = 0
    Результат р = проверить(ф, копия)
    целое64 итог = 0
    выбор (р) {
        Успех(значение) {
            итог = значение + копия
        }
        Провал(код) {
            итог = как<целое64>(код)
        }
    }
    printf("%lld\n", итог)
    вернуть 0
}
KONDA
"$BIN" потр2.конда >"$TMP/потр2.log" 2>&1 || { cat "$TMP/потр2.log" >&2; fail "потребитель с типами из .и должен собраться"; }
[ -f вывод/потр2.elf ] || fail "потр2: нет elf"
assert_eq "49" "$(./вывод/потр2.elf)" "путь 2: структуры и sum-типы через границу"
grep -q "typedef" вывод/потр2.c && grep -q "либа2" вывод/потр2.c || true
# C-определения библиотечных типов у потребителя НЕ эмитятся (typedef из .h):
if grep -q "typedef struct {.*фд" вывод/потр2.c; then
    fail "потребитель не должен эмитить typedef библиотечной структуры"
fi
# А вот деструктор библиотечной структуры RAII-вызывается у потребителя:
grep -q "_закрыть(&ф)" вывод/потр2.c || {
    cat вывод/потр2.c >&2; fail "деструктор структуры из .и должен вызываться у потребителя"; }

# Чужая структура в «изменяемый Файл» библиотеки — ошибка (сверка индекса типа).
cat > потр2_чужой.конда <<'KONDA'
#содержит "вывод/либа2.h"
структура Чужой {
    целое32 фд
}
целое32 точка_входа(срез<символ*> аргументы)
{
    Чужой ч = { фд = 1 }
    Результат р = проверить(ч, 0)
    вернуть 0
}
KONDA
if "$BIN" потр2_чужой.конда >"$TMP/потр2_чужой.log" 2>&1; then
    fail "передача чужой структуры в «изменяемый Файл» должна быть ошибкой"
fi
grep -q "не совпадает" "$TMP/потр2_чужой.log" || {
    cat "$TMP/потр2_чужой.log" >&2; fail "ожидалась ошибка несовпадения типа структуры"; }

# ─── Индексация произвольного lvalue (структура.поле[i], цепочки) ────────────
# Поле-срез структуры индексируется «на месте» — чтение и запись; проверка
# границ через срез_доступ (длина в самом срезе), autofree освобождает поле.
cat > lvindex_поле.конда <<'KONDA'
#содержит <stdio.h>
структура Буфер {
    срез<целое32> данные
}
целое32 точка_входа(срез<символ*> аргументы)
{
    Буфер б = { данные = выделить(3) }
    б.данные[0] = 100
    б.данные[1] = 200
    б.данные[2] = б.данные[0] + б.данные[1]
    printf("%d %d %d\n", б.данные[0], б.данные[1], б.данные[2])
    вернуть 0
}
KONDA
"$BIN" lvindex_поле.конда >"$TMP/lvindex_поле.log" 2>&1 || {
    cat "$TMP/lvindex_поле.log" >&2; fail "индексация поля-среза на месте должна компилироваться"; }
assert_eq "100 200 300" "$(./вывод/lvindex_поле.elf)" "структура.поле[i] — чтение и запись"

# Проверка границ поля-среза сохраняется (доказанно-небезопасный индекс → abort).
cat > lvindex_границы.конда <<'KONDA'
#содержит <stdio.h>
структура Б { срез<целое32> д }
целое32 точка_входа(срез<символ*> аргументы)
{
    Б б = { д = выделить(2) }
    целое32 и = как<целое32>(длина(аргументы) + 50)
    б.д[и] = 1
    printf("недостижимо\n")
    вернуть 0
}
KONDA
"$BIN" lvindex_границы.конда >"$TMP/lvindex_границы.log" 2>&1 || {
    cat "$TMP/lvindex_границы.log" >&2; fail "индексация поля-среза с границей должна транспилироваться"; }
./вывод/lvindex_границы.elf >/dev/null 2>&1 && rc=0 || rc=$?
assert_eq "134" "$rc" "выход за границу поля-среза прерывает программу (SIGABRT)"

# Негатив: индексация на месте среза из результата вызова запрещена (утечка
# владеющего временного) — присвоить в переменную.
cat > lvindex_вызов.конда <<'KONDA'
#содержит <stdio.h>
срез<целое32> сделать()
{
    срез<целое32> с = выделить(2)
    с[0] = 1
    вернуть с
}
целое32 точка_входа(срез<символ*> аргументы)
{
    printf("%d\n", сделать()[0])
    вернуть 0
}
KONDA
if "$BIN" lvindex_вызов.конда >"$TMP/lvindex_вызов.log" 2>&1; then
    fail "индексация результата вызова на месте должна быть ошибкой (утечка)"
fi
grep -q "владеющий временный" "$TMP/lvindex_вызов.log" || {
    cat "$TMP/lvindex_вызов.log" >&2; fail "понятная ошибка об утечке при индексации вызова"; }

# Негатив: индексировать на месте не-срез (напр. поле-указатель) нельзя.
cat > lvindex_несрез.конда <<'KONDA'
#содержит <stdio.h>
структура С { символ* имя }
целое32 точка_входа(срез<символ*> аргументы)
{
    С с = { имя = "abc" }
    небезопасно { printf("%c\n", с.имя[0]) }
    вернуть 0
}
KONDA
if "$BIN" lvindex_несрез.конда >"$TMP/lvindex_несрез.log" 2>&1; then
    fail "индексация поля-указателя на месте должна быть ошибкой"
fi
grep -q "только для среза" "$TMP/lvindex_несрез.log" || {
    cat "$TMP/lvindex_несрез.log" >&2; fail "понятная ошибка про не-срез базу"; }

# ─── Безопасные макросы: условная компиляция (#if/#ifdef/#ifndef/#else/#endif) ─
# Выбор ветки на этапе компиляции: неактивная ветка НЕ попадает в C (не рантайм).
cat > мак_условие.конда <<'KONDA'
#содержит <stdio.h>
#define ВЕРСИЯ 3
целое32 точка_входа(срез<символ*> аргументы)
{
#if ВЕРСИЯ >= 3
    printf("новая\n")
#else
    printf("старая\n")
#endif
#ifndef ОТЛАДКА
    printf("релиз\n")
#endif
    вернуть 0
}
KONDA
"$BIN" мак_условие.конда >"$TMP/мак_условие.log" 2>&1 || {
    cat "$TMP/мак_условие.log" >&2; fail "условная компиляция должна транспилироваться"; }
assert_eq "новая
релиз" "$(./вывод/мак_условие.elf)" "макросы: выбор ветки #if/#ifndef"
# Неактивная ветка отсутствует в сгенерированном C (это не рантайм-условие).
if grep -q "старая" вывод/мак_условие.c; then
    cat вывод/мак_условие.c >&2; fail "неактивная ветка #else не должна попадать в C"; fi
# #содержит проходит через препроцессор Konda как есть.
grep -q "include <stdio.h>" вывод/мак_условие.c || {
    cat вывод/мак_условие.c >&2; fail "#содержит должен проходить сквозь условную компиляцию"; }

# Флаг CLI «-D ИМЯ» включает #ifdef-ветку.
"$BIN" -D ОТЛАДКА мак_условие.конда >"$TMP/мак_D.log" 2>&1 || {
    cat "$TMP/мак_D.log" >&2; fail "-D должен компилироваться"; }
assert_eq "новая" "$(./вывод/мак_условие.elf)" "макросы: -D ОТЛАДКА гасит #ifndef-ветку"

# Русские директивы + #иначе_если + вложенность.
cat > мак_русские.конда <<'KONDA'
#содержит <stdio.h>
#определить УРОВЕНЬ 2
целое32 точка_входа(срез<символ*> аргументы)
{
#если УРОВЕНЬ == 1
    printf("один\n")
#иначе_если УРОВЕНЬ == 2
    printf("два\n")
#иначе
    printf("другое\n")
#конец
    вернуть 0
}
KONDA
"$BIN" мак_русские.конда >"$TMP/мак_русские.log" 2>&1 || {
    cat "$TMP/мак_русские.log" >&2; fail "русские директивы должны компилироваться"; }
assert_eq "два" "$(./вывод/мак_русские.elf)" "макросы: #если/#иначе_если/#конец"

# ─── Предопределённые макросы: режим сборки и платформа (§40) ────────────────
# Разработчик пишет разный код для дебаг/релиз и для ОС/архитектуры без -D:
# транспилятор сам определяет «дебаг»/«релиз», «линукс»/«макось»/«бсд»,
# «x86_64»/«арм64», «бит64»/«бит32». Плюс слова-операторы «не»/«и»/«или» в #если.
cat > мак_режим.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
#если релиз
    printf("Р\n")
#иначе
    printf("Д\n")
#конец
#если не релиз
    printf("отладка\n")
#конец
    вернуть 0
}
KONDA
# Дебаг (по умолчанию): активны «дебаг» и «не релиз».
"$BIN" мак_режим.конда >"$TMP/мак_режим_д.log" 2>&1 || {
    cat "$TMP/мак_режим_д.log" >&2; fail "предопред. макросы (дебаг) должны компилироваться"; }
assert_eq "Д
отладка" "$(./вывод/мак_режим.elf)" "предопред.: #если релиз=ложь в дебаге, «не релиз»=истина"
# Релиз: активен «релиз», «не релиз» гаснет.
"$BIN" --релиз мак_режим.конда >"$TMP/мак_режим_р.log" 2>&1 || {
    cat "$TMP/мак_режим_р.log" >&2; fail "предопред. макросы (релиз) должны компилироваться"; }
assert_eq "Р" "$(./вывод/мак_режим.elf)" "предопред.: #если релиз=истина в --релиз"

# Платформа хоста (тесты гоняются на Linux): «линукс» определён, «макось» — нет.
cat > мак_ос.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
#если линукс
    printf("linux\n")
#иначе_если макось
    printf("macos\n")
#иначе
    printf("other\n")
#конец
#если бит64
    printf("64\n")
#конец
    вернуть 0
}
KONDA
case "$(uname -s)" in
Linux)
    "$BIN" мак_ос.конда >"$TMP/мак_ос.log" 2>&1 || {
        cat "$TMP/мак_ос.log" >&2; fail "предопред. ОС-макросы должны компилироваться"; }
    # На Linux первая строка вывода — «linux» (ветка «линукс» активна, «макось» нет).
    os_line="$(./вывод/мак_ос.elf | head -1)"
    [ "$os_line" = "linux" ] || fail "предопред.: на Linux активна ветка «линукс» (получено: $os_line)"
    ;;
esac

# Кросс-триплет задаёт ПЛАТФОРМУ ЦЕЛИ, а не хоста: darwin → ветка «макось».
cat > мак_кросс.конда <<'KONDA'
целое32 точка_входа(срез<символ*> аргументы)
{
#если макось
    вернуть 7
#иначе_если линукс
    вернуть 8
#иначе
    вернуть 9
#конец
}
KONDA
