# Слова-операторы «не»/«и»/«или» в #если — синонимы !/&&/|| (язык русскоязычный).
cat > мак_словоопер.конда <<'KONDA'
#содержит <stdio.h>
#определить А 1
#определить Б 0
целое32 точка_входа(срез<символ*> аргументы)
{
#если А и не Б
    printf("да\n")
#конец
#если Б или А
    printf("или\n")
#конец
    вернуть 0
}
KONDA
"$BIN" мак_словоопер.конда >"$TMP/мак_словоопер.log" 2>&1 || {
    cat "$TMP/мак_словоопер.log" >&2; fail "слова-операторы не/и/или должны компилироваться"; }
assert_eq "да
или" "$(./вывод/мак_словоопер.elf)" "макросы: «не»/«и»/«или» как !/&&/||"

# ─── C23 «выровнять(N)» (alignas) и «встроить(файл)» (#embed) (§41) ──────────
# «выровнять(N)» — выравнивание объявления/поля структуры (→ C23 alignas(N)).
cat > выровнять_база.конда <<'KONDA'
#содержит <stdio.h>

структура Кэш {
    выровнять(64) целое32 счётчик
    целое32 флаг
}

выровнять(16) конст целое32 таблица[4] = { 1, 2, 3, 4 }

целое32 точка_входа(срез<символ*> аргументы)
{
    выровнять(32) целое8 буфер[8]
    буфер[0] = 9
    printf("%d %d %d\n", размер_обьекта(Кэш), таблица[0], буфер[0])
    вернуть 0
}
KONDA
"$BIN" выровнять_база.конда >"$TMP/выровнять_база.log" 2>&1 || {
    cat "$TMP/выровнять_база.log" >&2; fail "«выровнять(N)» должно транспилироваться"; }
grep -q "alignas(64) int32_t счётчик" вывод/выровнять_база.c || {
    cat вывод/выровнять_база.c >&2; fail "выровнять на поле структуры → alignas(64)"; }
grep -q "alignas(32) int8_t буфер" вывод/выровнять_база.c || {
    cat вывод/выровнять_база.c >&2; fail "выровнять на локальном массиве → alignas(32)"; }
grep -q "alignas(16)" вывод/выровнять_база.c || {
    cat вывод/выровнять_база.c >&2; fail "выровнять на глобальном конст-массиве → alignas(16)"; }
# Кэш выровнена по 64 → размер кратен 64; таблица[0]=1; буфер[0]=9.
assert_eq "64 1 9" "$(./вывод/выровнять_база.elf)" "выровнять: размер структуры кратен выравниванию, доступ работает"

# Негатив: выравнивание не степень двойки — ошибка компиляции.
