    вернуть x
}
KONDA
if "$BIN" --только-си выровнять_негатив.конда >"$TMP/выровнять_нег.log" 2>&1; then
    fail "выровнять(7) (не степень двойки) должно быть ошибкой"
fi
grep -q "двойки" "$TMP/выровнять_нег.log" || {
    cat "$TMP/выровнять_нег.log" >&2; fail "ошибка выравнивания должна объяснять «степень двойки»"; }

# «встроить("файл")» (C23 #embed): содержимое файла как байтовый массив с
# выводимым размером. Файл кладём и рядом с исходником (для --embed-dir основной
# сборки), и в «вывод/» — там его найдёт прямой пересбор санитайзер-прогоном
# (он компилирует вывод/*.c без --embed-dir; #embed ищет файл рядом с .c).
mkdir -p вывод
printf 'Konda!' > встроен.bin
printf 'Konda!' > вывод/встроен.bin
cat > встроить_база.конда <<'KONDA'
#содержит <stdio.h>

конст неподписанный целое8 данные[] = встроить("встроен.bin")

целое32 точка_входа(срез<символ*> аргументы)
{
    printf("%d %d\n", данные[0], данные[5])
    вернуть 0
}
KONDA
"$BIN" встроить_база.конда >"$TMP/встроить_база.log" 2>&1 || {
    cat "$TMP/встроить_база.log" >&2; fail "«встроить(файл)» должно транспилироваться"; }
grep -q "#embed \"встроен.bin\"" вывод/встроить_база.c || {
    cat вывод/встроить_база.c >&2; fail "встроить → директива #embed"; }
grep -q "static const uint8_t данные\[\]" вывод/встроить_база.c || {
    cat вывод/встроить_база.c >&2; fail "встроить → static const uint8_t имя[] (выводимый размер)"; }
# Команда компиляции должна нести --embed-dir (иначе #embed не найдёт файл).
grep -q -- "--embed-dir=" "$TMP/встроить_база.log" || {
    cat "$TMP/встроить_база.log" >&2; fail "для встроить компилятору нужен --embed-dir"; }
# «Konda!»: байт0='K'=75, байт5='!'=33.
assert_eq "75 33" "$(./вывод/встроить_база.elf)" "встроить: байты файла доступны по индексу"

