# ─── Побитовые операции (& | ^ ~ << >>) ─────────────────────────────────────
# Целочисленные, нулевая рантайм-цена, статически безопасны. Приоритеты как в C:
# «|» < «^» < «&» < сравнение < сдвиг < «+/-» < «*/%».
cat > побитовые.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 х = 12
    целое32 у = 10
    printf("%d\n", х & у)
    printf("%d\n", х | у)
    printf("%d\n", х ^ у)
    printf("%d\n", ~х)
    printf("%d\n", х << 2)
    printf("%d\n", х >> 1)
    printf("%d\n", х | у & 6)
    printf("%d\n", 1 << 4 | 1)
    вернуть 0
}
KONDA
"$BIN" побитовые.конда >"$TMP/побитовые.log" 2>&1 || {
    cat "$TMP/побитовые.log" >&2; fail "побитовые операции должны транспилироваться"; }
assert_eq "8
14
6
-13
48
6
14
17" "$(./вывод/побитовые.elf)" "побитовые & | ^ ~ << >> и приоритеты"

