# ─── Потоки: модель «передача владения» (гонки невозможны по построению) ────
# Поток получает данные только по значению или перемещением владения.
# Разделяемого изменяемого состояния выразить нельзя → гонок нет статически.
cat > поток_базовый.конда <<'KONDA'
#содержит <stdio.h>

целое32 сумма(владеет срез<целое32> с)
{
    целое32 итог = 0
    для целое32 и = 0; и < длина(с); и = и + 1 {
        итог = итог + с[и]
    }
    вернуть итог
}

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> данные = выделить(4)
    для целое32 и = 0; и < 4; и = и + 1 {
        данные[и] = и + 1
    }
    поток<целое32> п = запустить(сумма, данные)
    целое32 итог = присоединить(п)
    printf("%d\n", итог)
    вернуть 0
}
KONDA
"$BIN" поток_базовый.конда >"$TMP/поток_базовый.log" 2>&1 || {
    cat "$TMP/поток_базовый.log" >&2; fail "базовый поток должен транспилироваться"; }
assert_eq "10" "$(./вывод/поток_базовый.elf)" "поток: сумма 1+2+3+4 через перемещение среза"

# Негатив: использование среза после перемещения в поток — ошибка (гонка/UAF).
cat > поток_после_move.конда <<'KONDA'
#содержит <stdio.h>
целое32 сумма(владеет срез<целое32> с) { вернуть длина(с) }
целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> данные = выделить(4)
    поток<целое32> п = запустить(сумма, данные)
    printf("%d\n", данные[0])
    вернуть присоединить(п)
}
KONDA
if "$BIN" поток_после_move.конда >"$TMP/поток_после_move.log" 2>&1; then
    fail "использование среза после перемещения в поток должно быть ошибкой"
fi
grep -q "после передачи владения" "$TMP/поток_после_move.log" || {
    cat "$TMP/поток_после_move.log" >&2; fail "понятная ошибка use-after-move в поток"; }

# Негатив: «изменяемый»/«вывод» в функции потока — указатель в чужой кадр.
cat > поток_ссылка.конда <<'KONDA'
#содержит <stdio.h>
ничего испортить(изменяемый целое32 х) { х = 5 }
целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 з = 1
    поток<ничего> п = запустить(испортить, з)
    присоединить(п)
    вернуть 0
}
KONDA
if "$BIN" поток_ссылка.конда >"$TMP/поток_ссылка.log" 2>&1; then
    fail "«изменяемый» в функции потока должен быть ошибкой"
fi
grep -q "изменяемый\|вывод" "$TMP/поток_ссылка.log" || {
    cat "$TMP/поток_ссылка.log" >&2; fail "понятная ошибка ref/out в потоке"; }

# Негатив: срез-параметр без «владеет» — запускающий сохранил бы доступ (гонка).
cat > поток_заимствование.конда <<'KONDA'
#содержит <stdio.h>
целое32 сумма(срез<целое32> с) { вернуть длина(с) }
целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> данные = выделить(4)
    поток<целое32> п = запустить(сумма, данные)
    вернуть присоединить(п)
}
KONDA
if "$BIN" поток_заимствование.конда >"$TMP/поток_заимствование.log" 2>&1; then
    fail "срез в поток без «владеет» должен быть ошибкой"
fi
grep -q "владеет" "$TMP/поток_заимствование.log" || {
    cat "$TMP/поток_заимствование.log" >&2; fail "понятная ошибка заимствования в поток"; }

# Негатив: двойное присоединение — дескриптор потребляется (use-after-move).
cat > поток_двойной_join.конда <<'KONDA'
#содержит <stdio.h>
целое32 работа(целое32 х) { вернуть х * 2 }
целое32 точка_входа(срез<символ*> аргументы)
{
    поток<целое32> п = запустить(работа, 21)
    целое32 а1 = присоединить(п)
    целое32 а2 = присоединить(п)
    вернуть а1 + а2
}
KONDA
if "$BIN" поток_двойной_join.конда >"$TMP/поток_двойной_join.log" 2>&1; then
    fail "двойное присоединение должно быть ошибкой"
fi
grep -q "уже присоединён" "$TMP/поток_двойной_join.log" || { cat "$TMP/поток_двойной_join.log" >&2; fail "поток_двойной_join: ожидалась конкретная диагностика, не любая ошибка"; }

# Поток по значению (без срезов) — копия, гонок нет.
cat > поток_значение.конда <<'KONDA'
#содержит <stdio.h>
целое32 удвоить(целое32 х) { вернуть х * 2 }
целое32 точка_входа(срез<символ*> аргументы)
{
    поток<целое32> п1 = запустить(удвоить, 21)
    поток<целое32> п2 = запустить(удвоить, 50)
    printf("%d %d\n", присоединить(п1), присоединить(п2))
    вернуть 0
}
KONDA
"$BIN" поток_значение.конда >"$TMP/поток_значение.log" 2>&1 || {
    cat "$TMP/поток_значение.log" >&2; fail "поток по значению должен транспилироваться"; }
assert_eq "42 100" "$(./вывод/поток_значение.elf)" "два потока по значению"

# Авто-join: поток без явного «присоединить» присоединяется сам при выходе из
# области (RAII, как autofree срезов) — иначе поток остался бы отсоединённым,
# а его кадр утёк.
cat > поток_автоjoin.конда <<'KONDA'
#содержит <stdio.h>
ничего работник(целое32 н) { printf("работник %d\n", н) }
целое32 точка_входа(срез<символ*> аргументы)
{
    поток<ничего> п1 = запустить(работник, 1)
    поток<ничего> п2 = запустить(работник, 2)
    вернуть 0
}
KONDA
"$BIN" поток_автоjoin.конда >"$TMP/поток_автоjoin.log" 2>&1 || {
    cat "$TMP/поток_автоjoin.log" >&2; fail "авто-join должен транспилироваться"; }
grep -c "поток_присоединить_в(п" вывод/поток_автоjoin.c | grep -q "^2$" || {
    cat вывод/поток_автоjoin.c >&2; fail "оба потока должны присоединиться автоматически"; }
"./вывод/поток_автоjoin.elf" >/dev/null || fail "авто-join: программа должна отработать"

# Регрессия: явный «присоединить» снимает дескриптор с авто-join (иначе второй
# join при выходе из области — UB).
grep -c "поток_присоединить_в(п" вывод/поток_базовый.c | grep -q "^1$" || {
    cat вывод/поток_базовый.c >&2; fail "явный join не должен дублироваться авто-join'ом"; }

# Регрессия (double-free): срез, перемещённый в поток, НЕ освобождается
# запускающим — иначе free и в потоке («владеет»), и в области.
grep -q "free(данные.данные)" вывод/поток_базовый.c && {
    cat вывод/поток_базовый.c >&2
    fail "перемещённый в поток срез не должен освобождаться запускающим (double-free)"; }

# ─── «параллельно для»: параллелизм данных без разделяемого состояния ────────
# Диапазон дробится на непересекающиеся куски → гонок нет по построению.
cat > парал_базовый.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> с = выделить(8)
    для целое32 и = 0; и < 8; и = и + 1 { с[и] = и }
    целое32 множитель = 10
    параллельно для целое32 и = 0; и < 8; и = и + 1 {
        с[и] = с[и] * множитель
    }
    для целое32 и = 0; и < 8; и = и + 1 { printf("%d ", с[и]) }
    printf("\n")
    вернуть 0
}
KONDA
"$BIN" парал_базовый.конда >"$TMP/парал_базовый.log" 2>&1 || {
    cat "$TMP/парал_базовый.log" >&2; fail "«параллельно для» должен транспилироваться"; }
assert_eq "0 10 20 30 40 50 60 70 " "$(./вывод/парал_базовый.elf)" \
    "параллельно для: каждый элемент умножен, захвачены срез и скаляр"
# Шим обязан быть на уровне файла: вложенная функция GNU потребовала бы
# трамплина на исполняемом стеке (SEGV на hardened-сборках).
grep -q "auto void" вывод/парал_базовый.c && {
    fail "шим «параллельно для» не должен быть вложенной функцией (трамплин→SEGV)"; }
grep -q "Срез с;" вывод/парал_базовый.c || {
    cat вывод/парал_базовый.c >&2; fail "срез должен попасть в кадр захвата"; }

# Негатив: запись во внешнюю переменную — гонка.
cat > парал_гонка.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> с = выделить(8)
    целое32 сумма = 0
    параллельно для целое32 и = 0; и < 8; и = и + 1 { сумма = сумма + с[и] }
    вернуть сумма
}
KONDA
if "$BIN" парал_гонка.конда >"$TMP/парал_гонка.log" 2>&1; then
    fail "запись во внешнюю переменную из «параллельно для» должна быть ошибкой"
fi
grep -q "гонка" "$TMP/парал_гонка.log" || {
    cat "$TMP/парал_гонка.log" >&2; fail "понятная ошибка гонки"; }

# Негатив: запись по чужому индексу — непересечение не доказать.
cat > парал_индекс.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> с = выделить(8)
    параллельно для целое32 и = 0; и < 7; и = и + 1 { с[и + 1] = 5 }
    вернуть 0
}
KONDA
if "$BIN" парал_индекс.конда >"$TMP/парал_индекс.log" 2>&1; then
    fail "запись по индексу, отличному от переменной цикла, должна быть ошибкой"
fi
grep -q "писать можно только в" "$TMP/парал_индекс.log" || { cat "$TMP/парал_индекс.log" >&2; fail "парал_индекс: ожидалась конкретная диагностика, не любая ошибка"; }

# Негатив: «прервать» из параллельного цикла.
cat > парал_прервать.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> с = выделить(8)
    параллельно для целое32 и = 0; и < 8; и = и + 1 { прервать }
