}
KONDA
if "$BIN" парал_прервать.конда >"$TMP/парал_прервать.log" 2>&1; then
    fail "«прервать» в «параллельно для» должен быть ошибкой"
fi
grep -q "запрещены в" "$TMP/парал_прервать.log" || { cat "$TMP/парал_прервать.log" >&2; fail "парал_прервать: ожидалась конкретная диагностика, не любая ошибка"; }

# ─── Редукция в «параллельно для» ───────────────────────────────────────────
# У каждого куска СВОЙ аккумулятор в своём кадре; общей ячейки не существует,
# свёртка — после join в одном потоке. Гонок нет по построению, цены нет.
cat > ред_сумма.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> с = выделить(1000)
    для целое32 и = 0; и < 1000; и = и + 1 { с[и] = и }
    целое32 итог = 0
    параллельно для целое32 и = 0; и < 1000; и = и + 1 редукция(итог) {
        итог = итог + с[и]
    }
    целое32 эталон = 0
    для целое32 и = 0; и < 1000; и = и + 1 { эталон = эталон + с[и] }
    printf("%d %d\n", итог, эталон)
    вернуть 0
}
KONDA
"$BIN" ред_сумма.конда >"$TMP/ред_сумма.log" 2>&1 || {
    cat "$TMP/ред_сумма.log" >&2; fail "редукция должна транспилироваться"; }
assert_eq "499500 499500" "$(./вывод/ред_сумма.elf)" \
    "редукция: сумма совпадает с последовательным эталоном"
# Детерминизм — то, ради чего вещественные исключены: 3 запуска = одно число.
assert_eq "499500 499500" "$(./вывод/ред_сумма.elf)" "редукция: детерминизм (2)"
assert_eq "499500 499500" "$(./вывод/ред_сумма.elf)" "редукция: детерминизм (3)"
# Аккумулятор инициализируется ЕДИНИЦЕЙ операции (не копией внешней), а
# свёртка идёт после join — иначе куски делили бы одну ячейку.
grep -q "_пк\[_т\].итог = 0;" вывод/ред_сумма.c || {
    cat вывод/ред_сумма.c >&2; fail "редукция: аккумулятор кадра = единица операции"; }
grep -q "pthread_join" вывод/ред_сумма.c || fail "редукция: join обязателен"

# Прочие ассоциативно-коммутативные операции и их единицы.
cat > ред_опы.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> д = выделить(10)
    для целое32 и = 0; и < 10; и = и + 1 { д[и] = 2 }
    целое32 пр = 1
    параллельно для целое32 и = 0; и < 10; и = и + 1 редукция(пр) { пр = пр * д[и] }

    срез<целое32> б = выделить(4)
    б[0] = 1
    б[1] = 2
    б[2] = 4
    б[3] = 8
    целое32 ил = 0
    параллельно для целое32 и = 0; и < 4; и = и + 1 редукция(ил) { ил = ил | б[и] }

    срез<целое32> к2 = выделить(5)
    для целое32 и = 0; и < 5; и = и + 1 { к2[и] = и }
    целое32 кс = 0
    параллельно для целое32 и = 0; и < 5; и = и + 1 редукция(кс) { кс = кс ^ к2[и] }

    срез<целое32> м = выделить(6)
    для целое32 и = 0; и < 6; и = и + 1 { м[и] = 7 }
    целое32 ит = 15
    параллельно для целое32 и = 0; и < 6; и = и + 1 редукция(ит) { ит = ит & м[и] }

    printf("%d %d %d %d\n", пр, ил, кс, ит)
    вернуть 0
}
KONDA
"$BIN" ред_опы.конда >"$TMP/ред_опы.log" 2>&1 || {
    cat "$TMP/ред_опы.log" >&2; fail "редукция: операции * | ^ &"; }
assert_eq "1024 15 4 7" "$(./вывод/ред_опы.elf)" "редукция: * | ^ & и их единицы"
# Единица «&» — все биты; иначе свёртка обнулила бы результат.
grep -q "ит = ~" вывод/ред_опы.c || grep -q "\.ит = (int32_t)~0" вывод/ред_опы.c || {
    cat вывод/ред_опы.c >&2; fail "редукция: единица «&» должна быть ~0"; }

# Пустой диапазон: единица сворачивается в no-op, начальное значение цело.
cat > ред_пусто.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 итог = 42
    параллельно для целое32 и = 0; и < 0; и = и + 1 редукция(итог) { итог = итог + 1 }
    printf("%d\n", итог)
    вернуть 0
}
KONDA
"$BIN" ред_пусто.конда >"$TMP/ред_пусто.log" 2>&1 || {
    cat "$TMP/ред_пусто.log" >&2; fail "редукция: пустой диапазон"; }
assert_eq "42" "$(./вывод/ред_пусто.elf)" "редукция: пустой диапазон не меняет значение"

# Негатив: вещественная цель — сложение float не ассоциативно, результат зависел
# бы от числа ядер (недетерминизм). Отвергаем, как и в побитовых операциях.
cat > ред_float.конда <<'KONDA'
целое32 точка_входа(срез<символ*> аргументы)
{
    срез<вещественное> с = выделить(4)
    вещественное итог = 0
    параллельно для целое32 и = 0; и < 4; и = и + 1 редукция(итог) { итог = итог + с[и] }
    вернуть 0
}
KONDA
if "$BIN" ред_float.конда >"$TMP/ред_float.log" 2>&1; then
    fail "редукция по вещественному должна быть ошибкой (недетерминизм)"
fi
grep -q "детермин" "$TMP/ред_float.log" || {
    cat "$TMP/ред_float.log" >&2; fail "редукция: ошибка должна объяснять недетерминизм"; }

# Негатив: чтение частичного аккумулятора — его значение зависит от раскладки
# кусков, то есть недетерминировано.
cat > ред_чтение.конда <<'KONDA'
целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> с = выделить(8)
    целое32 итог = 0
    параллельно для целое32 и = 0; и < 8; и = и + 1 редукция(итог) {
        если (итог > 5) { итог = итог + 1 }
    }
    вернуть 0
}
KONDA
if "$BIN" ред_чтение.конда >"$TMP/ред_чтение.log" 2>&1; then
    fail "чтение частичного аккумулятора должно быть ошибкой"
fi
grep -q "аккумулятор редукции читается" "$TMP/ред_чтение.log" || { cat "$TMP/ред_чтение.log" >&2; fail "ред_чтение: ожидалась конкретная диагностика, не любая ошибка"; }

# Негатив: два разных оператора редукции — свёртка неоднозначна.
cat > ред_два_опа.конда <<'KONDA'
целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> с = выделить(8)
    целое32 итог = 0
    параллельно для целое32 и = 0; и < 8; и = и + 1 редукция(итог) {
        итог = итог + с[и]
        итог = итог * с[и]
    }
    вернуть 0
}
KONDA
if "$BIN" ред_два_опа.конда >"$TMP/ред_два_опа.log" 2>&1; then
