# ─── Вызовы чистых функций в «параллельно для» ──────────────────────────────
# Глобалов в языке нет → эффект наружу возможен только через изменяемый/вывод,
# запись в срез-параметр, указатель, «небезопасно» или вызов нечистой. Отсюда
# чистота ВЫВОДИТСЯ, без новых ключевых слов.
cat > чист_позитив.конда <<'KONDA'
#содержит <stdio.h>
целое32 обработать(целое32 х) { вернуть х * х + 1 }
целое32 взять(срез<целое32> д, целое32 к) { вернуть д[к] }
целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> с = выделить(8)
    для целое32 и = 0; и < 8; и = и + 1 { с[и] = и }
    срез<целое32> р = выделить(8)
    параллельно для целое32 и = 0; и < 8; и = и + 1 {
        р[и] = обработать(взять(с, и))
    }
    для целое32 и = 0; и < 8; и = и + 1 { printf("%d ", р[и]) }
    printf("\n")
    вернуть 0
}
KONDA
"$BIN" чист_позитив.конда >"$TMP/чист_позитив.log" 2>&1 || {
    cat "$TMP/чист_позитив.log" >&2; fail "вызов чистой функции в «параллельно для»"; }
assert_eq "1 2 5 10 17 26 37 50 " "$(./вывод/чист_позитив.elf)" \
    "чистые вызовы: работают, срез-параметр только на чтение — можно"

# Взаимно рекурсивные чистые функции: оптимистичный fixpoint обязан оставить их
# чистыми (наивный обход пометил бы нечистыми).
cat > чист_рекурсия.конда <<'KONDA'
#содержит <stdio.h>
целое32 чёт(целое32 н) { если (н == 0) { вернуть 1 } вернуть нечёт(н - 1) }
целое32 нечёт(целое32 н) { если (н == 0) { вернуть 0 } вернуть чёт(н - 1) }
целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> с = выделить(6)
    параллельно для целое32 и = 0; и < 6; и = и + 1 { с[и] = чёт(и) }
    для целое32 и = 0; и < 6; и = и + 1 { printf("%d", с[и]) }
    printf("\n")
    вернуть 0
}
KONDA
"$BIN" чист_рекурсия.конда >"$TMP/чист_рекурсия.log" 2>&1 || {
    cat "$TMP/чист_рекурсия.log" >&2; fail "взаимно рекурсивные чистые функции"; }
assert_eq "101010" "$(./вывод/чист_рекурсия.elf)" "чистые вызовы: взаимная рекурсия чистой остаётся чистой"

# Негатив: «изменяемый»-параметр — запись в кадр вызывающего.
cat > чист_ref.конда <<'KONDA'
ничего испортить(изменяемый целое32 х) { х = 5 }
целое32 точка_входа(срез<символ*> аргументы)
{
