# ─── Диагностика: поток, объявленный в цикле, идёт последовательно ──────────
# Авто-join срабатывает в конце итерации, поэтому «потоки» выполняются строго
# по очереди: код выглядит параллельным, компилируется — и не ускоряет ничего.
cat > поток_в_цикле.конда <<'KONDA'
#содержит <stdio.h>
целое32 работа(целое32 н) { вернуть н * н }
целое32 точка_входа(срез<символ*> аргументы)
{
    для целое32 и = 0; и < 3; и = и + 1 {
        поток<целое32> п = запустить(работа, и)
        printf("%d ", присоединить(п))
    }
    printf("\n")
    вернуть 0
}
KONDA
"$BIN" поток_в_цикле.конда >"$TMP/поток_в_цикле.log" 2>&1 || {
    cat "$TMP/поток_в_цикле.log" >&2; fail "поток в цикле — предупреждение, не ошибка"; }
grep -q "Предупреждение" "$TMP/поток_в_цикле.log" || {
    cat "$TMP/поток_в_цикле.log" >&2; fail "поток в цикле должен давать предупреждение"; }
grep -q "последовательно" "$TMP/поток_в_цикле.log" || {
    cat "$TMP/поток_в_цикле.log" >&2; fail "предупреждение должно объяснять последовательность"; }
assert_eq "0 1 4 " "$(./вывод/поток_в_цикле.elf)" "поток в цикле: программа корректна (но не параллельна)"

# Поток вне цикла — предупреждения быть не должно (ложных срабатываний нет).
cat > поток_вне_цикла.конда <<'KONDA'
#содержит <stdio.h>
целое32 работа2(целое32 н) { вернуть н + 1 }
целое32 точка_входа(срез<символ*> аргументы)
{
    поток<целое32> п = запустить(работа2, 41)
    printf("%d\n", присоединить(п))
    вернуть 0
}
KONDA
"$BIN" поток_вне_цикла.конда >"$TMP/поток_вне.log" 2>&1 || {
    cat "$TMP/поток_вне.log" >&2; fail "поток вне цикла"; }
grep -q "Предупреждение" "$TMP/поток_вне.log" && {
    cat "$TMP/поток_вне.log" >&2; fail "поток вне цикла не должен предупреждать"; }
assert_eq "42" "$(./вывод/поток_вне_цикла.elf)" "поток вне цикла: без предупреждения"

# ─── Векторизация шима «параллельно для» ────────────────────────────────────
# В шиме границы куска — рантайм-значения. Если сравнивать счётчик «целое32» с
# границей типа long, то под -fwrapv компилятор обязан допустить перенос счётчика
# → число итераций недоказуемо → SIMD отключается, и параллельный цикл проигрывал
# однопоточному в разы. Приведение границы к типу счётчика перенос исключает и
# ВОССТАНАВЛИВАЕТ семантику: обычный «для» и так сравнивает в типе счётчика.
cat > вект_шим.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 н = 64
    срез<целое32> с = выделить(н)
    параллельно для целое32 и = 0; и < длина(с); и = и + 1 { с[и] = и * 2 }
    printf("%d %d\n", с[0], с[63])
    вернуть 0
}
KONDA
"$BIN" --релиз вект_шим.конда >"$TMP/вект.log" 2>&1 || {
    cat "$TMP/вект.log" >&2; fail "«параллельно для» с границей «длина(с)»"; }
assert_eq "0 126" "$(./вывод/вект_шим.elf)" "векторизация: результат не изменился"
# Граница обязана сравниваться в типе счётчика, а не в long.
grep -qE "и = \(int32_t\)_к->_нач; и < \(int32_t\)_к->_кон" вывод/вект_шим.c || {
    grep -n "_к->_нач" вывод/вект_шим.c >&2
    fail "шим: границы куска должны приводиться к типу счётчика (иначе нет SIMD)"; }

# Граница ШИРЕ счётчика: приведение изменило бы сравнение (C расширяет до
# целое64) — тогда кодоген обязан оставить long и пожертвовать SIMD.
cat > вект_шире.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    целое64 предел = 8
    срез<целое32> с = выделить(8)
    параллельно для целое32 и = 0; и < предел; и = и + 1 { с[и] = и }
    printf("%d\n", с[7])
    вернуть 0
}
KONDA
"$BIN" --релиз вект_шире.конда >"$TMP/вект_ш.log" 2>&1 || {
    cat "$TMP/вект_ш.log" >&2; fail "«параллельно для» с границей целое64"; }
assert_eq "7" "$(./вывод/вект_шире.elf)" "широкая граница: результат верен"
grep -qE "и = \(int32_t\)_к->_нач" вывод/вект_шире.c && {
    fail "граница целое64 не должна сужаться до типа счётчика (смена семантики)"; }

# ─── Регрессия: мутация через «изменяемый»/«вывод» ломала элиминацию границ ──
# «изменяемый»/«вывод» меняют переменную БЕЗ видимого присваивания. Если это не
# учесть, её значение остаётся «известной константой», проверка границ снимается
# по ложному основанию — и получается настоящий выход за границы кучи (ASan
# ловил heap-buffer-overflow) в языке, где это должно быть невозможно.
cat > мутация_вывод.конда <<'KONDA'
#содержит <stdio.h>
ничего испортить(вывод целое32 х) { х = 100 }
целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 н = 8
    срез<целое32> с = выделить(8)
    испортить(н)
    для целое32 и = 0; и < н; и = и + 1 { с[и] = и }
    printf("%d\n", с[0])
    вернуть 0
}
KONDA
"$BIN" --релиз мутация_вывод.конда >"$TMP/мут.log" 2>&1 || {
    cat "$TMP/мут.log" >&2; fail "мутация через «вывод» должна транспилироваться"; }
grep -q "срез_доступ(с, и" вывод/мутация_вывод.c || {
    cat вывод/мутация_вывод.c >&2
    fail "после мутации «н» через «вывод» проверка границ обязана остаться (иначе выход за границы кучи)"; }
# То же для «изменяемый».
cat > мутация_изм.конда <<'KONDA'
#содержит <stdio.h>
ничего поднять(изменяемый целое32 х) { х = 100 }
целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 н = 8
    срез<целое32> с = выделить(8)
    поднять(н)
    для целое32 и = 0; и < н; и = и + 1 { с[и] = и }
    printf("%d\n", с[0])
    вернуть 0
}
KONDA
"$BIN" --релиз мутация_изм.конда >"$TMP/мут2.log" 2>&1 || {
    cat "$TMP/мут2.log" >&2; fail "мутация через «изменяемый» должна транспилироваться"; }
grep -q "срез_доступ(с, и" вывод/мутация_изм.c || {
    fail "после мутации «н» через «изменяемый» проверка границ обязана остаться"; }

# ─── Ссылки на проекции: «ф(изменяемый т.х)», «ф(вывод с[и])» ────────────────
# Second-class reference: база в кадре вызывающего заморожена на время вызова,
# границы среза проверяются при ФОРМИРОВАНИИ ссылки (тот же срез_доступ),
# утечь ссылке некуда (нет сырого «&», глобалов, замыканий).
cat > реф_проекции.конда <<'KONDA'
#содержит <stdio.h>
структура Точка { целое32 х; целое32 у }
ничего инк(изменяемый целое32 в) { в = в + 1 }
ничего дай(вывод целое32 в) { в = 42 }
целое32 точка_входа(срез<символ*> аргументы)
{
    Точка т = { х = 1, у = 2 }
    инк(т.х)
    срез<целое32> с = выделить(длина(аргументы) + 2)
    дай(с[0])
    инк(с[0])
    целое32 м[3] = { 7, 8, 9 }
    инк(м[1])
    неподписанный целое32 и = как<неподписанный целое32>(длина(аргументы))
    если (и < длина(с)) { инк(с[и]) } иначе { }
    printf("%d %d %d %d\n", т.х, с[0], м[1], с[и])
    вернуть 0
}
KONDA
"$BIN" реф_проекции.конда >"$TMP/рефп.log" 2>&1 || {
    cat "$TMP/рефп.log" >&2; fail "ссылки на проекции должны транспилироваться"; }
grep -q "инк(&т.х)" вывод/реф_проекции.c || {
    cat вывод/реф_проекции.c >&2; fail "поле по ссылке: ожидалось «&т.х»"; }
grep -q "дай(&(\*(int32_t \*)срез_доступ(с, 0" вывод/реф_проекции.c || {
    cat вывод/реф_проекции.c >&2
    fail "элемент среза по ссылке: границы проверяются при формировании (&срез_доступ)"; }
grep -q "инк(&м\[1\])" вывод/реф_проекции.c || {
    cat вывод/реф_проекции.c >&2; fail "элемент массива по ссылке: ожидалось «&м[1]»"; }
grep -q "инк(&((int32_t \*)с.данные)\[и\])" вывод/реф_проекции.c || {
    cat вывод/реф_проекции.c >&2
    fail "охранник должен снимать проверку и у ссылки (BCE: прямой адрес)"; }
assert_eq "2 43 9 1" "$(./вывод/реф_проекции.elf)" "ссылки на проекции: значения записаны"

# Негативы: каждый канал утечки/ошибки закрыт понятной диагностикой.
cat > реф_конст.конда <<'KONDA'
ничего инк(изменяемый целое32 в) { в = в + 1 }
