    cat "$TMP/рефв.log" >&2; fail "ошибка про владеет+ссылку должна быть понятной"; }

cat > реф_временное.конда <<'KONDA'
срез<целое32> дай() { срез<целое32> с = выделить(3); вернуть с }
ничего инк(изменяемый целое32 в) { в = в + 1 }
