    cat "$TMP/рефт.log" >&2; fail "ошибка про временное должна быть понятной"; }

cat > реф_поле_срез.конда <<'KONDA'
структура Б { срез<целое32> данные }
ничего жри(изменяемый целое32 в) { }
целое32 точка_входа(срез<символ*> аргументы)
{
    Б б = { данные = выделить(3) }
    жри(б.данные)
    вернуть 0
}
KONDA
if "$BIN" реф_поле_срез.конда >"$TMP/рефпс.log" 2>&1; then
    fail "поле-срез по ссылке должно отвергаться (дескриптор владеет памятью)"
fi
grep -q "поле-срез" "$TMP/рефпс.log" || {
    cat "$TMP/рефпс.log" >&2; fail "ошибка про поле-срез должна быть понятной"; }

# Рантайм: динамический индекс вне границ при формировании ссылки → abort
# с сообщением (проверка живёт в срез_доступ — та же, что у чтения).
cat > реф_границы.конда <<'KONDA'
#содержит <stdio.h>
ничего инк(изменяемый целое32 в) { в = в + 1 }
целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> с = выделить(2)
    целое32 и = длина(аргументы) + 10
    инк(с[и])
    вернуть 0
}
KONDA
"$BIN" реф_границы.конда >"$TMP/рефг.log" 2>&1 || {
    cat "$TMP/рефг.log" >&2; fail "реф_границы должен транспилироваться"; }
if ./вывод/реф_границы.elf >"$TMP/рефг.out" 2>&1; then
    fail "формирование ссылки вне границ должно прерывать программу"
fi
grep -q "выход за границы среза" "$TMP/рефг.out" || {
    cat "$TMP/рефг.out" >&2; fail "abort при формировании ссылки должен назвать причину"; }

# ─── Связь «выделить(н)» → «длина(с) == н» ──────────────────────────────────
# Если срез создан из «выделить(н)», а «н» после этого не менялась, то
# «длина(с) == н», значит «и < н» доказывает попадание в границы так же, как
# «и < длина(с)» — проверку можно снять статически (нулевая рантайм-цена).
cat > длина_связь.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 н = 16
    если (длина(аргументы) > 99) { н = 8 }
    срез<целое32> с = выделить(н)
    для целое32 и = 0; и < н; и = и + 1 { с[и] = и }
    printf("%d\n", с[15])
    вернуть 0
}
KONDA
"$BIN" --релиз длина_связь.конда >"$TMP/длсв.log" 2>&1 || {
    cat "$TMP/длсв.log" >&2; fail "связь выделить(н) → длина(с)"; }
assert_eq "15" "$(./вывод/длина_связь.elf)" "связь длины: результат верен"
# Доступ ИЗ ЦИКЛА обязан стать прямым (вне цикла «с[15]» при неизвестной длине
# проверку сохраняет законно — 15 < н не доказать).
grep -q "((int32_t \*)с.данные)\[и\] = и;" вывод/длина_связь.c || {
    grep -n "и\]" вывод/длина_связь.c >&2
    fail "«и < н» при «с = выделить(н)» — проверка границ в цикле должна сниматься"; }

# Негатив: если «н» изменилась ПОСЛЕ выделения, связь неверна → проверка остаётся.
cat > длина_связь_сброс.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 н = 8
    срез<целое32> с = выделить(н)
    н = 100
    для целое32 и = 0; и < н; и = и + 1 { с[и] = и }
    printf("%d\n", с[0])
    вернуть 0
}
KONDA
"$BIN" длина_связь_сброс.конда >"$TMP/длсв2.log" 2>&1 || {
    cat "$TMP/длсв2.log" >&2; fail "переприсваивание н должно транспилироваться"; }
grep -q "срез_доступ(с, и" вывод/длина_связь_сброс.c || {
    cat вывод/длина_связь_сброс.c >&2
    fail "после переприсваивания «н» связь неверна — проверка в цикле обязана остаться"; }

# ─── Поле варианта перечисления обязано быть именованным ────────────────────
# «Вариант(тип)» без имени поля раньше молча давал НЕВАЛИДНЫЙ C
# («struct { int32_t ; }») — ошибку выдавал компилятор C, а не Konda. Это ломало
# обещание «диагностики на русском с позицией». Теперь — ошибка Konda.
cat > вариант_без_имени.конда <<'KONDA'
перечисление Е { А(целое32) }
целое32 точка_входа(срез<символ*> аргументы)
{
    Е е = А(1)
    вернуть 0
}
KONDA
if "$BIN" вариант_без_имени.конда >"$TMP/вбим.log" 2>&1; then
    fail "вариант с безымянным полем должен быть ошибкой Konda, а не битым C"
fi
grep -q "имя" "$TMP/вбим.log" || {
    cat "$TMP/вбим.log" >&2; fail "ошибка должна объяснять, что полю варианта нужно имя"; }
grep -q "строка 1" "$TMP/вбим.log" || {
    cat "$TMP/вбим.log" >&2; fail "ошибка должна нести позицию в .конда"; }

# Позитив-регрессия: именованное поле по-прежнему работает (в т.ч. несколько).
cat > вариант_с_именем.конда <<'KONDA'
#содержит <stdio.h>
перечисление Событие {
    Клик
    Загружено(целое32 сколько)
    Точка(целое32 х, целое32 у)
}
целое32 разобрать(Событие е)
{
    выбор е {
        Клик { вернуть 1 }
        Загружено(н) { вернуть н }
        Точка(а, б) { вернуть а + б }
    }
    вернуть 0
}
целое32 точка_входа(срез<символ*> аргументы)
{
    printf("%d %d %d\n", разобрать(Клик), разобрать(Загружено(41)), разобрать(Точка(3, 4)))
    вернуть 0
}
KONDA
"$BIN" вариант_с_именем.конда >"$TMP/вcим.log" 2>&1 || {
    cat "$TMP/вcим.log" >&2; fail "именованные поля вариантов должны работать"; }
assert_eq "1 41 7" "$(./вывод/вариант_с_именем.elf)" "варианты: именованные поля (одно и несколько)"

# Безымянные параметры «типфункции» — законны и НЕ должны задеваться правкой.
cat > тф_без_имён.конда <<'KONDA'
типфункции целое32 Оп(целое32, целое32)
целое32 сложить(целое32 а, целое32 б) { вернуть а + б }
целое32 точка_входа(срез<символ*> аргументы)
{
    Оп о = сложить
    вернуть о(2, 3) - 5
}
KONDA
"$BIN" тф_без_имён.конда >"$TMP/тфби.log" 2>&1 || {
    cat "$TMP/тфби.log" >&2; fail "типфункции без имён параметров должны остаться законны"; }

# «возможно<T*>» как тип ВОЗВРАТА функции верхнего уровня: разобрать_функцию
# это умел, но диспетчер верхнего уровня не признавал «возможно» началом
# объявления — функция была недостижима («ожидалась директива, функция или
# пространство»). Регрессия на исправление.
cat > возможно_возврат.конда <<'KONDA'
#содержит <stdio.h>

возможно<символ*> выбрать(целое32 флаг, символ* а)
{
    если (флаг > 0) {
        вернуть а
    }
    вернуть нуль
}

целое32 точка_входа(срез<символ*> аргументы)
{
    возможно<символ*> р = выбрать(1, "есть")
    если (р != нуль) {
        printf("%s\n", р)
    } иначе {
        printf("нет\n")
    }
    вернуть 0
}
KONDA
"$BIN" возможно_возврат.конда >"$TMP/возможно_возврат.log" 2>&1 || {
    cat "$TMP/возможно_возврат.log" >&2
    fail "функция с типом возврата «возможно<T*>» должна разбираться на верхнем уровне"
}
assert_eq "есть" "$(./вывод/возможно_возврат.elf)" "возможно<T*> как тип возврата функции"

# «внешняя» — прототип C-функции с «изменяемый»/«вывод»: мутация переменной
# вызывающего через границу C без сырого «&» (кодоген ставит «&» сам).
cat > внешлиб.h <<'CH'
#pragma once
#include <stdint.h>
static inline void удвоить_в(int32_t *х) { *х = *х * 2; }
static inline void дать_пять(int32_t *х) { *х = 5; }
CH
cat > внешняя_функция.конда <<'KONDA'
#содержит <stdio.h>
#содержит "внешлиб.h"

внешняя ничего удвоить_в(изменяемый целое32 х)
внешняя ничего дать_пять(вывод целое32 х)

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 а = 21
    удвоить_в(а)
    целое32 б
    дать_пять(б)
    printf("%d %d\n", а, б)
    вернуть 0
}
KONDA
"$BIN" внешняя_функция.конда >"$TMP/внешняя.log" 2>&1 || {
    cat "$TMP/внешняя.log" >&2
    fail "«внешняя» с изменяемый/вывод должна компилироваться"
}
assert_eq "42 5" "$(./вывод/внешняя_функция.elf)" "внешняя: изменяемый и вывод через границу C"

# «внешний тип» — непрозрачный C-тип: только указатель, by-value — ошибка.
cat > внешлиб2.h <<'CH'
#pragma once
#include <stdint.h>
#include <stdlib.h>
struct _холст { int32_t ш; };
typedef struct _холст холст;
static inline холст *холст_создать(int32_t ш) { холст *х = malloc(sizeof *х); х->ш = ш; return х; }
static inline int32_t холст_ширина(холст *х) { return х->ш; }
static inline void холст_удалить(холст *х) { free(х); }
CH
cat > внешний_тип.конда <<'KONDA'
#содержит <stdio.h>
#содержит "внешлиб2.h"

внешний тип холст
внешняя холст* холст_создать(целое32 ш)
внешняя целое32 холст_ширина(холст* х)
внешняя ничего холст_удалить(холст* х)

целое32 точка_входа(срез<символ*> аргументы)
{
    холст* х = холст_создать(640)
    printf("%d\n", холст_ширина(х))
    холст_удалить(х)
    вернуть 0
}
KONDA
"$BIN" внешний_тип.конда >"$TMP/втип.log" 2>&1 || {
    cat "$TMP/втип.log" >&2
    fail "«внешний тип» через указатель должен компилироваться"
}
assert_eq "640" "$(./вывод/внешний_тип.elf)" "внешний тип: работа через указатель"

cat > внешний_тип_знач.конда <<'KONDA'
внешний тип холст
целое32 точка_входа(срез<символ*> аргументы)
{
    холст х
    вернуть 0
}
KONDA
if "$BIN" внешний_тип_знач.конда >"$TMP/втз.log" 2>&1; then
    fail "внешний тип by-value должен отвергаться"
fi
grep -q "внешний тип" "$TMP/втз.log" || {
    cat "$TMP/втз.log" >&2
    fail "ошибка о внешнем типе должна быть понятной"
}

# «внешний тип Имя { поля }» — доступ к ПОЛЯМ системной C-структуры (§54): поля
# нужны для проверки типов, C-определение даёт заголовок (транспилятор его НЕ
# эмитит), доступ через указатель «п.поле» → «п->поле».
cat > внешполя.h <<'CH'
#pragma once
#include <stdint.h>
typedef struct { int32_t ino; char имя[8]; } Зпс;
static Зпс _з = { 42, "dot" };
static inline Зпс *дать(void) { return &_з; }
CH
cat > внешний_тип_поля.конда <<'KONDA'
#содержит <stdio.h>
#содержит "внешполя.h"

внешний тип Зпс { целое32 ino; символ имя[8] }
внешняя возможно<Зпс*> дать()

целое32 точка_входа(срез<символ*> аргументы)
{
    возможно<Зпс*> з = дать()
    если (з != нуль) {
        printf("%d %c\n", з.ino, з.имя[0])
    }
    вернуть 0
}
KONDA
"$BIN" внешний_тип_поля.конда >"$TMP/втп.log" 2>&1 || {
    cat "$TMP/втп.log" >&2
    fail "«внешний тип» с полями должен компилироваться"
}
assert_eq "42 d" "$(./вывод/внешний_тип_поля.elf)" "внешний тип с полями: доступ через указатель"
# Определение внешнего типа НЕ эмитится (его даёт заголовок).
if grep -q "} Зпс;" вывод/внешний_тип_поля.c; then
    cat вывод/внешний_тип_поля.c >&2
    fail "определение внешнего типа не должно эмититься (его даёт заголовок)"
fi
grep -q "з->ino" вывод/внешний_тип_поля.c || {
    cat вывод/внешний_тип_поля.c >&2
    fail "доступ к полю внешнего типа должен идти через «->»"
}

# Неизвестное поле внешнего типа — ошибка.
cat > внешполя_неизв.конда <<'KONDA'
#содержит "внешполя.h"
внешний тип Зпс { целое32 ino }
внешняя возможно<Зпс*> дать()
целое32 точка_входа(срез<символ*> аргументы)
{
    возможно<Зпс*> з = дать()
    если (з != нуль) { вернуть з.нетполя }
    вернуть 0
}
KONDA
if "$BIN" внешполя_неизв.конда >"$TMP/втпн.log" 2>&1; then
