    fail "ошибка о неизвестном поле внешнего типа должна быть понятной"
}

# Батч-ошибки парсера: обе синтаксические ошибки видны за ОДИН прогон.
cat > синтаксис_батч.конда <<'KONDA'
целое32 ф(целое32 а) {
    вернуть а +
}

целое32 г(целое32 б) {
    вернуть б * @
}

целое32 точка_входа(срез<символ*> аргументы) {
    вернуть 0
}
KONDA
if "$BIN" синтаксис_батч.конда >"$TMP/батч.log" 2>&1; then
    fail "файл с синтаксическими ошибками должен отвергаться"
fi
[ "$(grep -c "Ошибка транспиляции" "$TMP/батч.log")" -ge 2 ] || {
    cat "$TMP/батч.log" >&2
    fail "парсер должен показать ОБЕ ошибки за один прогон (батч)"
}

# Батч ВНУТРИ одного тела функции: восстановление на границе оператора, а не
# только на границе верхнего уровня. Три битых оператора в одной функции — все
# три видны за прогон (раньше пропадали: тело пропускалось до след. объявления).
cat > синтаксис_батч_тело.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 а = 1 2
    целое32 б = 3 4
    целое32 в = 5 6
    вернуть 0
}
KONDA
if "$BIN" синтаксис_батч_тело.конда >"$TMP/батч_тело.log" 2>&1; then
    fail "функция с тремя синтаксическими ошибками должна отвергаться"
fi
[ "$(grep -c "Ошибка транспиляции" "$TMP/батч_тело.log")" -eq 3 ] || {
    cat "$TMP/батч_тело.log" >&2
    fail "парсер должен показать ВСЕ 3 ошибки внутри одного тела (батч операторов)"
}
grep -q "Всего ошибок: 3" "$TMP/батч_тело.log" || {
    cat "$TMP/батч_тело.log" >&2
    fail "итог «Всего ошибок: 3» для трёх ошибок в теле"
}

# Регресс: корректная функция ПОСЛЕ битой всё ещё разбирается (восстановление не
# съедает лишнего) — ошибка в теле локализована.
cat > синтаксис_батч_смешанный.конда <<'KONDA'
#содержит <stdio.h>

целое32 плохая(целое32 а)
{
    целое32 x = 1 2
    вернуть а
}

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 y = 7 8
    вернуть 0
}
KONDA
if "$BIN" синтаксис_батч_смешанный.конда >"$TMP/батч_смеш.log" 2>&1; then
    fail "файл с ошибками в двух телах должен отвергаться"
fi
[ "$(grep -c "Ошибка транспиляции" "$TMP/батч_смеш.log")" -eq 2 ] || {
    cat "$TMP/батч_смеш.log" >&2
    fail "ошибки в теле каждой из двух функций видны за один прогон"
}

# Глобальные «конст»: примитив (свёртка), строка, структура; чтение полей.
cat > глоб_конст.конда <<'KONDA'
#содержит <stdio.h>

конст целое32 РАЗМЕР = 8 * 4
конст символ* ПРИВЕТ = "привет"

структура Точка {
    целое32 х
    целое32 у
}
конст Точка НАЧАЛО = { х = 3, у = 4 }

целое32 точка_входа(срез<символ*> аргументы)
{
    printf("%d %s %d\n", РАЗМЕР, ПРИВЕТ, НАЧАЛО.х + НАЧАЛО.у)
    вернуть 0
}
KONDA
"$BIN" глоб_конст.конда >"$TMP/гк.log" 2>&1 || {
    cat "$TMP/гк.log" >&2
    fail "глобальные конст должны компилироваться"
}
assert_eq "32 привет 7" "$(./вывод/глоб_конст.elf)" "глобальные конст: примитив, строка, структура"

# Глобальный конст-МАССИВ: примитивы, строки (символ*), вещественные. Читается
# с проверкой границ; static const в C, нулевая рантайм-цена.
cat > глоб_конст_массив.конда <<'KONDA'
#содержит <stdio.h>

конст целое32 ТАБЛИЦА[4] = { 10, 20, 30, 40 }
конст символ* КУРСОРЫ[3] = { "watch", "hand", "arrow" }
конст вещественное ЦВЕТА[3] = { 0.5, 0.25, 1.0 }

целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 с = 0
    для целое32 и = 0; и < 4; и = и + 1 { с = с + ТАБЛИЦА[и] }
    printf("%d %s %s %.2f\n", с, КУРСОРЫ[0], КУРСОРЫ[2], ЦВЕТА[1])
    вернуть 0
}
KONDA
"$BIN" глоб_конст_массив.конда >"$TMP/гкм.log" 2>&1 || {
    cat "$TMP/гкм.log" >&2
    fail "глобальный конст-массив должен компилироваться"
}
grep -q "static const int32_t ТАБЛИЦА\[4\]" вывод/глоб_конст_массив.c || {
    cat вывод/глоб_конст_массив.c >&2
    fail "конст-массив → static const T ИМЯ[N]"
}
grep -q "static const char \*КУРСОРЫ\[3\]" вывод/глоб_конст_массив.c || {
    cat вывод/глоб_конст_массив.c >&2
    fail "конст-массив символ* → static const char *ИМЯ[N]"
}
assert_eq "100 watch arrow 0.25" "$(./вывод/глоб_конст_массив.elf)" \
    "конст-массив: примитив (сумма), символ*, вещественное"

