# «атом<T>» — единственный ИЗМЕНЯЕМЫЙ глобал: атомарный примитив (_Atomic T).
# Гонок данных нет (атомарный доступ) → инвариант №4 цел даже с потоками.
cat > атом_глобал.конда <<'KONDA'
#содержит <stdio.h>

атом<целое32> счётчик = 0

ничего тик()
{
    счётчик = счётчик + 1
}

целое32 точка_входа(срез<символ*> аргументы)
{
    тик()
    тик()
    тик()
    printf("%d\n", счётчик)
    вернуть 0
}
KONDA
"$BIN" атом_глобал.конда >"$TMP/атом.log" 2>&1 || {
    cat "$TMP/атом.log" >&2
    fail "атом<T>-глобал должен компилироваться"
}
grep -q "static _Atomic int32_t счётчик = 0;" вывод/атом_глобал.c || {
    cat вывод/атом_глобал.c >&2
    fail "атом<T> → static _Atomic T"
}
assert_eq "3" "$(./вывод/атом_глобал.elf)" "атом: изменяемый глобал, чтение/запись"

# TSan: атом-глобал разделяется двумя потоками — гонок ДАННЫХ быть НЕ должно.
if command -v cc >/dev/null 2>&1; then
cat > атом_поток.конда <<'KONDA'
#содержит <stdio.h>

атом<целое32> сч = 0

целое32 наращивать(целое32 раз)
{
    для целое32 и = 0; и < раз; и = и + 1 { сч = сч + 1 }
    вернуть 0
}

целое32 точка_входа(срез<символ*> аргументы)
{
    поток<целое32> п1 = запустить(наращивать, 50000)
    поток<целое32> п2 = запустить(наращивать, 50000)
    целое32 а = присоединить(п1)
    целое32 б = присоединить(п2)
    если (сч > 0 и сч <= 100000) { printf("ok\n") } иначе { printf("BAD\n") }
    вернуть 0
}
KONDA
    "$BIN" --только-си атом_поток.конда >/dev/null 2>&1 || fail "атом_поток должен транспилироваться"
    cc -std=gnu23 -O1 -g -fsanitize=thread -lpthread вывод/атом_поток.c -o "$TMP/атом_поток" 2>/dev/null
    if [ -x "$TMP/атом_поток" ]; then
        out="$("$TMP/атом_поток" 2>&1)"
        echo "$out" | grep -qE "WARNING: ThreadSanitizer|data race" \
            && { echo "$out" >&2; fail "атом-глобал: TSan нашёл гонку данных (не должно)"; }
        assert_eq "ok" "$out" "атом-глобал под TSan: гонок данных нет"
    fi
fi

# §49 Явные memory_order-операции: загрузить(а,п) / сохранить(а,знач,п) /
# обменять(а,знач,п) → atomic_*_explicit(&а, [знач,] memory_order_X). Синтаксис
# ФУНКЦИЙ (как длина/выделить), а не методов (методов в языке нет).
cat > атом_порядок.конда <<'KONDA'
#содержит <stdio.h>
атом<целое32> счётчик = 0
целое32 точка_входа(срез<символ*> аргументы)
{
    сохранить(счётчик, 10, расслабленный)
    целое32 старое = обменять(счётчик, 42, последовательный)
    целое32 текущее = загрузить(счётчик, получить)
    printf("%d %d\n", старое, текущее)
    вернуть 0
}
KONDA
"$BIN" атом_порядок.конда >"$TMP/атп.log" 2>&1 || {
    cat "$TMP/атп.log" >&2; fail "атом-операции с порядком должны транспилироваться"; }
assert_eq "10 42" "$(./вывод/атом_порядок.elf)" "загрузить/сохранить/обменять с порядком"
grep -q "atomic_store_explicit(&счётчик, 10, memory_order_relaxed)" вывод/атом_порядок.c || {
    cat вывод/атом_порядок.c >&2; fail "сохранить(_,_,расслабленный) → atomic_store_explicit relaxed"; }
grep -q "atomic_exchange_explicit(&счётчик, 42, memory_order_seq_cst)" вывод/атом_порядок.c || {
    cat вывод/атом_порядок.c >&2; fail "обменять(_,_,последовательный) → atomic_exchange_explicit seq_cst"; }
grep -q "atomic_load_explicit(&счётчик, memory_order_acquire)" вывод/атом_порядок.c || {
    cat вывод/атом_порядок.c >&2; fail "загрузить(_,получить) → atomic_load_explicit acquire"; }
grep -q "#include <stdatomic.h>" вывод/атом_порядок.c || {
    cat вывод/атом_порядок.c >&2; fail "атом-операции требуют <stdatomic.h>"; }

# Негатив: порядок, недопустимый для операции (load с release, store с acquire).
atneg() { # $1 тип, $2 тело, $3 ожидаемая-подстрока
    printf '#содержит <stdio.h>\nатом<целое32> с = 0\nцелое32 точка_входа(срез<символ*> аргументы)\n{\n    %s\n    вернуть 0\n}\n' "$2" > "$TMP/атн.конда"
    if "$BIN" --только-си --вывод="$TMP" "$TMP/атн.конда" >"$TMP/атн.log" 2>&1; then
        cat "$TMP/атн.log" >&2; fail "атом-негатив должен отвергаться: $2"; fi
    grep -q "$3" "$TMP/атн.log" || { cat "$TMP/атн.log" >&2; fail "ожидалось «$3» для: $2"; }
}
atneg целое32 'целое32 x = загрузить(с, освободить)' "допускает только"
atneg целое32 'сохранить(с, 1, получить)'            "допускает только"
atneg целое32 'целое32 x = загрузить(с, чепуха)'     "порядок памяти"

# Негатив: значение не помещается в тип атомика (константа).
cat > атом_сужение.конда <<'KONDA'
#содержит <stdio.h>
атом<целое8> с = 0
целое32 точка_входа(срез<символ*> аргументы)
{
    сохранить(с, 300, расслабленный)
    вернуть 0
}
KONDA
if "$BIN" --только-си атом_сужение.конда >"$TMP/атс.log" 2>&1; then
    cat "$TMP/атс.log" >&2; fail "значение вне диапазона атомика должно отвергаться"; fi
grep -q "не помещается в тип атомика" "$TMP/атс.log" || {
    cat "$TMP/атс.log" >&2; fail "ошибка о переполнении атомика должна быть понятной"; }

# Совместимость: голый доступ к атомику (seq_cst) — БЕЗ <stdatomic.h>.
cat > атом_голый.конда <<'KONDA'
