# TSan: инкремент атомика двумя потоками через обменять/загрузить с relaxed —
# гонок ДАННЫХ нет (атомарные операции).
if command -v cc >/dev/null 2>&1; then
cat > атом_порядок_поток.конда <<'KONDA'
#содержит <stdio.h>
атом<целое32> сч = 0
целое32 наращивать(целое32 раз)
{
    для целое32 и = 0; и < раз; и++ {
        целое32 c = загрузить(сч, расслабленный)
        сохранить(сч, c + 1, расслабленный)
    }
    вернуть 0
}
целое32 точка_входа(срез<символ*> аргументы)
{
    поток<целое32> п1 = запустить(наращивать, 20000)
    поток<целое32> п2 = запустить(наращивать, 20000)
    целое32 а = присоединить(п1)
    целое32 б = присоединить(п2)
    целое32 итог = загрузить(сч, последовательный)
    если (итог > 0 и итог <= 40000) { printf("ok\n") } иначе { printf("BAD\n") }
    вернуть 0
}
KONDA
    "$BIN" --только-си атом_порядок_поток.конда >/dev/null 2>&1 || fail "атом_порядок_поток должен транспилироваться"
    cc -std=gnu23 -O1 -g -fsanitize=thread -lpthread вывод/атом_порядок_поток.c -o "$TMP/атпп" 2>/dev/null
    if [ -x "$TMP/атпп" ]; then
        out="$("$TMP/атпп" 2>&1)"
        echo "$out" | grep -qE "WARNING: ThreadSanitizer|data race" \
            && { echo "$out" >&2; fail "атом-порядок: TSan нашёл гонку данных (не должно)"; }
        assert_eq "ok" "$out" "атом-операции relaxed под TSan: гонок данных нет"
    fi
fi

# Глобальная ПЕРЕМЕННАЯ (без конст/атом) — ошибка: инвариант «глобалов нет».
