# Listener-паттерн: конст-структура с колбэком + «чтение»-параметр внешней.
cat > слушлиб.h <<'CH'
#pragma once
static inline void зарегистрировать(const Слушатель *с, int32_t н) { с->на_событие(н); }
CH
cat > слушатель.конда <<'KONDA'
#содержит <stdio.h>
#содержит "слушлиб.h"

типфункции ничего Колбэк(целое32)

структура Слушатель {
    Колбэк на_событие
}

ничего печать_события(целое32 н)
{
    printf("событие %d\n", н)
}

конст Слушатель СЛУШАТЕЛЬ = { на_событие = печать_события }

внешняя ничего зарегистрировать(чтение Слушатель с, целое32 н)

целое32 точка_входа(срез<символ*> аргументы)
{
    зарегистрировать(СЛУШАТЕЛЬ, 7)
    вернуть 0
}
KONDA
"$BIN" слушатель.конда >"$TMP/слуш.log" 2>&1 || {
    cat "$TMP/слуш.log" >&2
    fail "listener-паттерн (конст-структура + чтение) должен компилироваться"
}
assert_eq "событие 7" "$(./вывод/слушатель.elf)" "listener: конст-структура с колбэком через «чтение»"

# Типизированные слушатели: «внешний слушатель<T> … { поле(изменяемый T, …) }» +
# экземпляр + «слушать(...)» → трампулин прячет каст void*→T (тело колбэка
# типизировано, без «небезопасно»). Каст в ОДНОМ сгенерированном месте, привязан
# к T, проверенному на «слушать» (тип «данные» == T).
cat > фейкслуш.h <<'CH'
#pragma once
#include <stdint.h>
struct fake_listener { void (*on_event)(void *data, int32_t value); };
static inline void fake_add(void *obj, const struct fake_listener *l, void *data) {
    (void)obj; l->on_event(data, 42);   /* сразу «доставляем» событие */
}
CH
cat > тип_слушатель.конда <<'KONDA'
#содержит <stdio.h>
#содержит "фейкслуш.h"

структура Счётчик { целое32 сумма }

внешний слушатель<Счётчик> МойСлуш для fake_listener {
    on_event(изменяемый Счётчик с, целое32 значение)
}

ничего обработать(изменяемый Счётчик с, целое32 значение)
{
    с.сумма = с.сумма + значение
}

целое32 точка_входа(срез<символ*> аргументы)
{
    Счётчик сч = { сумма = 0 }
    МойСлуш л = { on_event = обработать }
    слушать(fake_add, нуль, л, сч)
    printf("сумма = %d\n", сч.сумма)
    вернуть 0
}
KONDA
"$BIN" тип_слушатель.конда >"$TMP/тслуш.log" 2>&1 || {
    cat "$TMP/тслуш.log" >&2
    fail "типизированный слушатель должен компилироваться"
}
# Каст void*→T ровно в ОДНОМ месте — сгенерированном трампулине; тело колбэка типизировано.
grep -q "static void _трамп_л_on_event(void \*data" вывод/тип_слушатель.c || {
    cat вывод/тип_слушатель.c >&2; fail "должен эмититься трампулин на поле слушателя"; }
grep -q "обработать((Счётчик \*)data" вывод/тип_слушатель.c || {
    cat вывод/тип_слушатель.c >&2; fail "трампулин должен кастовать void*→T и звать колбэк"; }
grep -q "static const struct fake_listener _л_л = {" вывод/тип_слушатель.c || {
    cat вывод/тип_слушатель.c >&2; fail "должна эмититься C-структура-литерал слушателя"; }
# Тело колбэка НЕ должно быть в «небезопасно» (нет сырого void*/каста у пользователя).
awk '/void обработать\(/,/^}/' вывод/тип_слушатель.c | grep -q "небезопасно\|(void\*)\|(void \*)" && {
    cat вывод/тип_слушатель.c >&2; fail "тело типизированного колбэка не должно содержать void*/небезопасно"; }
assert_eq "сумма = 42" "$(./вывод/тип_слушатель.elf)" "типизированный слушатель: колбэк через трампулин"

# Негатив: тип «данные» не совпадает с userdata-типом T → ошибка (тип-безопасность).
cat > тип_слушатель_бад.конда <<'KONDA'
#содержит "фейкслуш.h"
структура Счётчик { целое32 сумма }
структура Другое { целое32 x }
внешний слушатель<Счётчик> МС для fake_listener {
    on_event(изменяемый Счётчик с, целое32 значение)
}
ничего обработать(изменяемый Счётчик с, целое32 значение) { с.сумма = значение }
целое32 точка_входа(срез<символ*> аргументы) {
    Другое д = { x = 0 }
    МС л = { on_event = обработать }
    слушать(fake_add, нуль, л, д)
    вернуть 0
}
KONDA
if "$BIN" --только-си тип_слушатель_бад.конда >"$TMP/тслушб.log" 2>&1; then
    fail "несовпадение типа «данные» с T должно отвергаться"
fi
grep -q "не совпадает с userdata-типом" "$TMP/тслушб.log" || {
    cat "$TMP/тслушб.log" >&2; fail "ошибка типа данных слушателя должна быть понятной"; }

# «чтение» у СВОЕЙ функции — const-ссылка (Задача 1): передаётся Тип* без
# копии, «&» на вызове, тело НЕ может писать в объект вызывающего. Нулевая
# рантайм-цена; ссылке некуда утечь (second-class reference).
cat > чтение_своя.конда <<'KONDA'
#содержит <stdio.h>
структура Точка { целое32 х; целое32 у }
целое32 сумма(чтение Точка т) { вернуть т.х + т.у }
целое32 точка_входа(срез<символ*> аргументы)
{
    Точка т = { х = 3, у = 4 }
    printf("%d\n", сумма(т))
    вернуть 0
}
KONDA
"$BIN" чтение_своя.конда >"$TMP/чс.log" 2>&1 || {
    cat "$TMP/чс.log" >&2; fail "«чтение» у своей функции должно работать (const-ссылка)"; }
grep -q "сумма(Точка \*т)" вывод/чтение_своя.c || {
    cat вывод/чтение_своя.c >&2; fail "«чтение»-параметр должен передаваться как «Точка*» (без копии)"; }
grep -q "сумма(&т)" вывод/чтение_своя.c || {
    cat вывод/чтение_своя.c >&2; fail "на вызове «чтение» кодоген должен ставить «&»"; }
assert_eq "7" "$(./вывод/чтение_своя.elf)" "чтение-параметр своей функции: чтение полей"

# Запись в «чтение»-параметр — ошибка (иммутабельность const-ссылки).
cat > чтение_запись.конда <<'KONDA'
структура Точка { целое32 х }
ничего испортить(чтение Точка т) { т.х = 99 }
целое32 точка_входа(срез<символ*> аргументы) { вернуть 0 }
KONDA
if "$BIN" чтение_запись.конда >"$TMP/чз.log" 2>&1; then
