    cat "$TMP/чз.log" >&2; fail "ошибка про запись в «чтение» должна быть про неизменяемость"; }

# Переменная, названная как её тип (имена из C идут как есть, без манглинга):
# «п.поле = …» и «п.поле[i] = …» — доступ к члену/индекс переменной, а НЕ
# начало объявления. Раньше диспетчер оператора видел в первом токене имя типа,
# уходил в разбор объявления и падал «ожидалось имя переменной» (регресс из
# конвертера weston/calibrator.c, где «struct calibrator *calibrator» идиоматичен).
cat > имя_как_тип.конда <<'KONDA'
#содержит <stdio.h>

структура Калиб {
    срез<целое32> tests
    целое32 current_test
}

ничего записать(изменяемый Калиб Калиб, целое32 x) {
    Калиб.tests[Калиб.current_test] = x
    Калиб.current_test = Калиб.current_test + 1
}

целое32 точка_входа(срез<символ*> аргументы) {
    Калиб Калиб = { tests = выделить(3), current_test = 0 }
    записать(Калиб, 42)
    записать(Калиб, 7)
    printf("%d %d %d\n", Калиб.tests[0], Калиб.tests[1], Калиб.current_test)
    вернуть 0
}
KONDA
"$BIN" имя_как_тип.конда >"$TMP/имя_как_тип.log" 2>&1 || {
    cat "$TMP/имя_как_тип.log" >&2
    fail "переменная с именем типа: «п.поле[i] = …» должно разбираться как доступ"
}
assert_eq "42 7 2" "$(./вывод/имя_как_тип.elf)" "переменная, названная как тип: доступ/индекс на месте"

# ── Перегрузка операторов ────────────────────────────────────────────────────
# «Тип оператор+(Л а, П б)» → вызов функции на месте оператора (нулевая цена).
cat > оператор_перегрузка.конда <<'KONDA'
#содержит <stdio.h>

структура Точка {
    целое32 х
    целое32 у
}

Точка оператор+(Точка а, Точка б)
{
    Точка р = { х = а.х + б.х, у = а.у + б.у }
    вернуть р
}

Точка оператор*(Точка а, целое32 к)
{
    Точка р = { х = а.х * к, у = а.у * к }
    вернуть р
}

логический оператор==(Точка а, Точка б)
{
    вернуть а.х == б.х и а.у == б.у
}

целое32 точка_входа(срез<символ*> аргументы)
{
    Точка п1 = { х = 1, у = 2 }
    Точка п2 = { х = 10, у = 20 }
    Точка с = п1 + п2
    Точка м = п1 * 3
    Точка ц = п1 + п2 + м
    printf("%d %d %d %d %d %d\n", с.х, с.у, м.х, м.у, ц.х, ц.у)
    логический равны = п1 == п2
    если (п1 == п1) {
        если (равны) {
            printf("ошибка сравнения\n")
        } иначе {
            printf("сравнение верно\n")
        }
    }
    вернуть 0
}
KONDA
"$BIN" оператор_перегрузка.конда >"$TMP/оп.log" 2>&1 || {
    cat "$TMP/оп.log" >&2
    fail "перегрузка операторов должна транспилироваться"
}
assert_eq "11 22 3 6 14 28" "$(./вывод/оператор_перегрузка.elf | head -1)" \
    "перегрузка: +, * со скаляром, цепочка"
assert_eq "сравнение верно" "$(./вывод/оператор_перегрузка.elf | tail -1)" \
    "перегрузка: == в условии"
# Кодоген — обычный вызов манглированной функции (нулевая рантайм-цена).
grep -q "_опер_плюс_Точка_Точка(п1, п2)" вывод/оператор_перегрузка.c || {
    fail "оператор + должен стать вызовом функции"
}

