структура Т { целое32 х }
Т оператор+(Т а) { вернуть а }
целое32 точка_входа(срез<символ*> аргументы){ вернуть 0 }
KONDA
if "$BIN" оп_арность.конда >"$TMP/опа.log" 2>&1; then
    fail "оператор с одним параметром должен отвергаться"
fi
grep -q "ровно два параметра" "$TMP/опа.log" || {
    cat "$TMP/опа.log" >&2; fail "ошибка арности оператора должна быть понятной"; }

