# ─── Составное присваивание «+= -= …» (§45) ──────────────────────────────────
# Десугар «цель ОП= знач» → «цель = цель ОП знач»: реюз всей машинерии биноп.
# Все 10 операторов на простой переменной.
cat > составное_все.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 x = 10
    x += 5
    x -= 2
    x *= 3
    x /= 2
    x %= 7
    x <<= 2
    x >>= 1
    x &= 30
    x |= 1
    x ^= 4
    printf("%d\n", x)
    вернуть 0
}
KONDA
"$BIN" составное_все.конда >"$TMP/сост_все.log" 2>&1 || {
    cat "$TMP/сост_все.log" >&2; fail "составные операторы должны транспилироваться"; }
assert_eq "15" "$(./вывод/составное_все.elf)" \
    "все 10 составных операторов: ((((((((10+5-2)*3)/2)%7)<<2)>>1)&30)|1)^4 = 15"

# Составное на элементе среза + шаг цикла «i += 1» (канонический цикл, BCE-элизия).
cat > составное_срез.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> с = выделить(4)
    для целое32 i = 0; i < длина(с); i += 1 { с[i] += i * 2 }
    printf("%d %d\n", с[1], с[3])
    вернуть 0
}
KONDA
"$BIN" составное_срез.конда >"$TMP/сост_срез.log" 2>&1 || {
    cat "$TMP/сост_срез.log" >&2; fail "составное на элементе среза должно транспилироваться"; }
assert_eq "2 6" "$(./вывод/составное_срез.elf)" "с[i] += i*2 и шаг i += 1 (канонический цикл)"
# «i += 1» распознан как шаг канонического цикла → прямой доступ, без срез_доступ.
if grep -q ")срез_доступ(" вывод/составное_срез.c; then
    cat вывод/составное_срез.c >&2
    fail "шаг «i += 1» должен распознаваться как канонический (без рантайм-проверки)"
fi

# Составное на поле структуры.
cat > составное_поле.конда <<'KONDA'
#содержит <stdio.h>
структура Точка {
    целое32 х
    целое32 у
}
целое32 точка_входа(срез<символ*> аргументы)
{
    Точка т = { х = 10, у = 20 }
    т.х += 5
    т.у *= 2
    printf("%d %d\n", т.х, т.у)
    вернуть 0
}
KONDA
"$BIN" составное_поле.конда >"$TMP/сост_поле.log" 2>&1 || {
    cat "$TMP/сост_поле.log" >&2; fail "составное на поле структуры должно транспилироваться"; }
assert_eq "15 40" "$(./вывод/составное_поле.elf)" "т.х += 5; т.у *= 2"

# Guard деления через «/=»: неконстантный ноль → чистый abort (реюз §43-машинерии).
cat > составное_деление_ноль.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 x = 10
    целое32 z = длина(аргументы) - 1
    x /= z
    printf("%d\n", x)
    вернуть 0
}
KONDA
"$BIN" составное_деление_ноль.конда >"$TMP/сост_дель.log" 2>&1 || {
    cat "$TMP/сост_дель.log" >&2; fail "составное /= должно транспилироваться"; }
./вывод/составное_деление_ноль.elf >/dev/null 2>"$TMP/сост_дель.err" && rc=0 || rc=$?
assert_eq "134" "$rc" "x /= 0 (неконст) прерывается рантайм-guard'ом (через десугар)"
grep -q "деление на ноль" "$TMP/сост_дель.err" || {
    cat "$TMP/сост_дель.err" >&2; fail "сообщение о делении на ноль должно быть понятным"; }

# Беззнаковый «<<=» — §43-фикс (нативный тип) действует через десугар: 1<<63 = 2^63.
cat > составное_беззнак.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    неподписанный целое64 x = 1
    неподписанный целое64 n = как<неподписанный целое64>(длина(аргументы)) + 62
    x <<= n
    printf("%llu\n", x)
    вернуть 0
}
KONDA
"$BIN" составное_беззнак.конда >"$TMP/сост_бз.log" 2>&1 || {
    cat "$TMP/сост_бз.log" >&2; fail "беззнаковое <<= должно транспилироваться"; }
assert_eq "9223372036854775808" "$(./вывод/составное_беззнак.elf)" \
    "беззнаковый сдвиг 1<<63 через <<= (нативный тип, §43)"

# Составное с перегрузкой оператора: «v += w» → «v = оператор+(v, w)».
cat > составное_перегрузка.конда <<'KONDA'
#содержит <stdio.h>
структура Век {
    целое32 x
    целое32 y
}
Век оператор+(Век a, Век b)
{
    Век р = { x = a.x + b.x, y = a.y + b.y }
    вернуть р
}
целое32 точка_входа(срез<символ*> аргументы)
{
    Век v = { x = 1, y = 2 }
    Век w = { x = 10, y = 20 }
    v += w
    printf("%d %d\n", v.x, v.y)
    вернуть 0
}
KONDA
"$BIN" составное_перегрузка.конда >"$TMP/сост_перег.log" 2>&1 || {
    cat "$TMP/сост_перег.log" >&2; fail "составное с перегрузкой должно транспилироваться"; }
assert_eq "11 22" "$(./вывод/составное_перегрузка.elf)" "v += w через перегруженный оператор+"

# Негатив: вызов в ЦЕЛИ (double-fetch/TOCTOU) — запрещён.
cat > составное_вызов_в_цели.конда <<'KONDA'
#содержит <stdio.h>
целое32 идх() { вернуть 0 }
целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> с = выделить(4)
    с[идх()] += 1
    вернуть 0
}
KONDA
if "$BIN" составное_вызов_в_цели.конда >"$TMP/сост_выз.log" 2>&1; then
