# ─── Постфикс «.поле»/«[i]» после «(выр)» — цепочка чтения парен-первичного ──
# Раньше «(s).x» после «(» → выр → «)» возвращалось из primary БЕЗ применения
# постфикс-цепочки (только идент-путь её применял). Ломало «для p = (s).x; …»
# (fix для konda-from-clang / weston: reg-паттерн doubles).
cat > постфикс_парен.конда <<'KONDA'
#содержит <stdio.h>
структура S { целое32 x; целое32 массив[3] }
целое32 точка_входа(срез<символ*> аргументы)
{
    S s
    s.x = 42
    s.массив[1] = 99
    целое32 a = (s).x
    целое32 b = (s).массив[1]
    целое32 p = 0
    для p = (s).x; p < 45; p = p + 1 { }
    printf("%d %d %d\n", a, b, p)
    вернуть 0
}
KONDA
"$BIN" постфикс_парен.конда >"$TMP/пф_парен.log" 2>&1 || {
    cat "$TMP/пф_парен.log" >&2; fail "постфикс после парен-первичного должен парситься"; }
assert_eq "42 99 45" "$(./вывод/постфикс_парен.elf)" "(s).поле, (s).массив[i], для с (s).поле"

# ─── Постфиксный инкремент/декремент «x++» / «x--» (§46) ─────────────────────
# Go-стиль: ТОЛЬКО оператор (не выражение). Отдельный узел (не десугар в
# «x = x + 1»), чтобы «целое8 x; x++» не упиралось в запрет сужения.
cat > инкремент_основы.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    целое32 x = 5
    x++
    x++
    x--
    вещественное64 f = 1.0
    f++
    целое8 b = 100
    b++
    printf("%d %.1f %d\n", x, f, b)
    вернуть 0
}
KONDA
"$BIN" инкремент_основы.конда >"$TMP/инк.log" 2>&1 || {
    cat "$TMP/инк.log" >&2; fail "инкремент/декремент должны транспилироваться"; }
assert_eq "6 2.0 101" "$(./вывод/инкремент_основы.elf)" \
    "x++/x--/f++/b++ на переменной (в т.ч. целое8 — без приведения)"

# Отладка: знаковое целое → guard переполнения (арифметика_безопасно); эмит
# хойстит адрес (single-eval).
grep -q "typeof(x) \*_кц = &(x)" вывод/инкремент_основы.c || {
    cat вывод/инкремент_основы.c >&2
    fail "знаковый инкремент в отладке должен идти через guard с хойстом адреса"; }

# Переполнение знакового ++ в отладке → чистый abort.
cat > инкремент_переполнение.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    целое8 b = 127
    целое8 добавка = как<целое8>(длина(аргументы))
    b = b + добавка
    b++
    printf("%d\n", b)
    вернуть 0
}
KONDA
"$BIN" инкремент_переполнение.конда >"$TMP/инкпер.log" 2>&1 || {
    cat "$TMP/инкпер.log" >&2; fail "инкремент у границы должен транспилироваться"; }
./вывод/инкремент_переполнение.elf >/dev/null 2>"$TMP/инкпер.err" && rc=0 || rc=$?
assert_eq "134" "$rc" "b++ при b==МАКС (целое8) прерывается guard'ом переполнения"

# Элемент среза + шаг цикла «i++» (канонический цикл, BCE-элизия).
cat > инкремент_срез_цикл.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> с = выделить(4)
    для целое32 i = 0; i < длина(с); i++ { с[i]++ }
    printf("%d\n", с[3])
    вернуть 0
}
KONDA
"$BIN" инкремент_срез_цикл.конда >"$TMP/инкц.log" 2>&1 || {
    cat "$TMP/инкц.log" >&2; fail "инкремент элемента среза в цикле i++ должен работать"; }
assert_eq "1" "$(./вывод/инкремент_срез_цикл.elf)" "с[i]++ и шаг i++ (канонический цикл)"
if grep -q ")срез_доступ(" вывод/инкремент_срез_цикл.c; then
    cat вывод/инкремент_срез_цикл.c >&2
    fail "шаг «i++» должен распознаваться как канонический (без рантайм-проверки)"
fi

# Single-eval цели с побочным эффектом: «с[f()]++» вызывает f() РОВНО ОДИН РАЗ
# в рантайме (typeof — невычисляемый контекст, адрес берётся один раз).
cat > инкремент_single_eval.конда <<'KONDA'
#содержит <stdio.h>
целое32 идх() { вернуть 1 }
целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> с = выделить(4)
    с[идх()]++
    с[идх()]++
    printf("%d\n", с[1])
    вернуть 0
}
KONDA
"$BIN" инкремент_single_eval.конда >"$TMP/инксе.log" 2>&1 || {
    cat "$TMP/инксе.log" >&2; fail "«с[f()]++» должен транспилироваться"; }
assert_eq "2" "$(./вывод/инкремент_single_eval.elf)" "с[идх()]++ дважды → с[1]==2 (f() один раз каждый)"

# BCE-безопасность (класс §43 Ф1): лишний «и++» в ТЕЛЕ канонического цикла
# отменяет элизию границ (иначе индекс прыгал бы за длину — выход за границы).
cat > инкремент_bce_тело.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> с = выделить(4)
    для целое32 и = 0; и < длина(с); и++ {
        и++
        с[и] = 1
    }
    printf("ок\n")
    вернуть 0
}
KONDA
"$BIN" инкремент_bce_тело.конда >"$TMP/инкбце.log" 2>&1 || {
    cat "$TMP/инкбце.log" >&2; fail "цикл с лишним и++ в теле должен транспилироваться"; }
grep -q ")срез_доступ(" вывод/инкремент_bce_тело.c || {
    cat вывод/инкремент_bce_тело.c >&2
    fail "лишний «и++» в теле ДОЛЖЕН отменять элизию границ (иначе выход за границы)"; }

# Негатив: инкремент «конст».
cat > инкремент_конст.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    конст целое32 K = 5
    K++
    вернуть 0
}
KONDA
if "$BIN" инкремент_конст.конда >"$TMP/инкк.log" 2>&1; then
    fail "инкремент «конст» должен отвергаться"
fi
grep -q "неизменяем" "$TMP/инкк.log" || {
    cat "$TMP/инкк.log" >&2; fail "ошибка про конст-инкремент должна быть понятной"; }

# Негатив: инкремент нечислового типа (логический).
cat > инкремент_нечисло.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    логический l = истина
    l++
    вернуть 0
}
KONDA
if "$BIN" инкремент_нечисло.конда >"$TMP/инкн.log" 2>&1; then
    fail "инкремент логического должен отвергаться"
fi
grep -q "неприменим" "$TMP/инкн.log" || {
    cat "$TMP/инкн.log" >&2; fail "ошибка про неприменимость инкремента должна быть понятной"; }

# Негатив: инкремент внешней переменной в «параллельно для» — гонка.
cat > инкремент_параллельно.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> с = выделить(100)
    целое32 счёт = 0
    параллельно для целое32 и = 0; и < длина(с); и++ {
        счёт++
    }
    вернуть 0
}
KONDA
if "$BIN" инкремент_параллельно.конда >"$TMP/инкп.log" 2>&1; then
    fail "инкремент внешней переменной в «параллельно для» должен отвергаться (гонка)"
fi
grep -q "гонка" "$TMP/инкп.log" || {
    cat "$TMP/инкп.log" >&2; fail "ошибка про гонку инкремента должна быть понятной"; }

# ─── Флаги сборки: --только-си, --аллокатор, --целевая-архитектура ──────────
cat > флаги_сборки.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> д = выделить(длина(аргументы))
    printf("%d\n", длина(д))
    вернуть 0
}
KONDA

# --только-си: пишет .c, компиляцию пропускает (нет .elf).
rm -f вывод/флаги_сборки.elf
"$BIN" --только-си флаги_сборки.конда >"$TMP/только_си.log" 2>&1 || {
    cat "$TMP/только_си.log" >&2; fail "--только-си должен успешно выдавать .c"; }
grep -q "компиляция пропущена" "$TMP/только_си.log" || {
    cat "$TMP/только_си.log" >&2; fail "--только-си должен сообщать о пропуске компиляции"; }
[ -f вывод/флаги_сборки.c ] || fail "--только-си должен записать .c"
[ ! -f вывод/флаги_сборки.elf ] || fail "--только-си НЕ должен создавать .elf"

# Дефолт — jemalloc: в команде компиляции есть -l:libjemalloc.so.2 (исполняемый).
"$BIN" флаги_сборки.конда >"$TMP/деф.log" 2>&1
grep -q -- "-l:libjemalloc.so.2" "$TMP/деф.log" || {
    cat "$TMP/деф.log" >&2; fail "по умолчанию должен линковаться jemalloc"; }

# Hardening (нулевая цена на горячем пути, переносимая защита) — в команде
# компиляции присутствуют всегда: full RELRO, NX-стек, stack-clash, канарейка.
for f in "-Wl,-z,relro" "-Wl,-z,now" "-Wl,-z,noexecstack" \
         "-fstack-clash-protection" "-fstack-protector-strong"; do
    grep -q -- "$f" "$TMP/деф.log" || {
        cat "$TMP/деф.log" >&2; fail "hardening-флаг $f должен ставиться (отладка)"; }
done
# И в релизе тоже (hardening не зависит от режима оптимизации).
"$BIN" --релиз флаги_сборки.конда >"$TMP/деф_рел.log" 2>&1
grep -q -- "-fstack-clash-protection" "$TMP/деф_рел.log" || {
    cat "$TMP/деф_рел.log" >&2; fail "hardening должен ставиться и в релизе"; }

# §48 Релиз-оптимизации без нарушения инварианта №1: -fno-math-errno разрешает
# gcc векторизовать sqrt/exp/log (снимает искусственный барьер errno-побочки);
# -fno-plt заменяет PLT-thunk на прямой indirect через GOT (совместимо с FULL
# RELRO из §28: «-Wl,-z,now» уже ставится → ленивое разрешение выключено).
grep -q -- "-fno-math-errno" "$TMP/деф_рел.log" || {
    cat "$TMP/деф_рел.log" >&2; fail "релиз: -fno-math-errno должен разрешать векторизацию math"; }
grep -q -- "-fno-plt" "$TMP/деф_рел.log" || {
    cat "$TMP/деф_рел.log" >&2; fail "релиз: -fno-plt должен экономить прыжок PLT-thunk"; }
# Оба флага — ТОЛЬКО релиз (в отладке errno-семантика помогает диагностике,
# а PLT-thunk безобиден). Проверяем: в дефолтной (отладочной) сборке их нет.
if grep -q -- "-fno-math-errno" "$TMP/деф.log"; then
    cat "$TMP/деф.log" >&2; fail "-fno-math-errno не должен ставиться в отладке"; fi
if grep -q -- "-fno-plt" "$TMP/деф.log"; then
    cat "$TMP/деф.log" >&2; fail "-fno-plt не должен ставиться в отладке"; fi

# --аллокатор=libc: jemalloc не линкуется.
"$BIN" --аллокатор=libc флаги_сборки.конда >"$TMP/лкц.log" 2>&1
if grep -q -- "libjemalloc" "$TMP/лкц.log"; then
    cat "$TMP/лкц.log" >&2; fail "--аллокатор=libc не должен линковать jemalloc"
fi

# Неизвестный аллокатор — понятная ошибка.
if "$BIN" --аллокатор=tcmalloc флаги_сборки.конда >"$TMP/ал.log" 2>&1; then
    fail "неизвестный аллокатор должен отвергаться"
fi
grep -q "Неизвестный аллокатор" "$TMP/ал.log" || {
    cat "$TMP/ал.log" >&2; fail "ошибка про аллокатор должна быть понятной"; }

# --целевая-архитектура: компилятор «<триплет>-gcc», аллокатор авто-libc (кросс).
# Кросс-тулчейн в CI может отсутствовать → проверяем эхо команды, не результат.
"$BIN" --целевая-архитектура=aarch64-linux-gnu флаги_сборки.конда >"$TMP/кросс.log" 2>&1 || true
grep -q "aarch64-linux-gnu-gcc -std=gnu23" "$TMP/кросс.log" || {
    cat "$TMP/кросс.log" >&2; fail "--целевая-архитектура должна звать <триплет>-gcc"; }
if grep -q -- "libjemalloc" "$TMP/кросс.log"; then
    cat "$TMP/кросс.log" >&2; fail "на кроссе без явного --аллокатор jemalloc не линкуется (авто-libc)"
fi

# Библиотека (.so) не тянет jemalloc даже по умолчанию — аллокатор выбирает
# финальная программа.
cat > флаги_либа.конда <<'KONDA'
целое32 удвоить(целое32 х) { вернуть х * 2 }
KONDA
"$BIN" --библиотека флаги_либа.конда >"$TMP/либа.log" 2>&1 || {
    cat "$TMP/либа.log" >&2; fail "сборка библиотеки должна проходить"; }
if grep -q -- "libjemalloc" "$TMP/либа.log"; then
    cat "$TMP/либа.log" >&2; fail "библиотека (.so) не должна навязывать jemalloc"
fi

# OS-гейтинг флагов (§39): на Linux эмитятся ELF/GNU-ld флаги, а macOS-специфичные
# (-dynamiclib / @rpath / -install_name) НЕ протекают. Тест защищает от регрессии
# «случайно эмитим Darwin-флаг на Linux» — линкер молча их не сожрёт.
case "$(uname -s)" in
Linux)
    for f in "-dynamiclib" "-install_name" "@rpath" "@loader_path"; do
        if grep -qF -- "$f" "$TMP/деф.log"; then
            cat "$TMP/деф.log" >&2
            fail "Darwin-специфичный флаг «$f» не должен эмититься на Linux"
        fi
    done
    ;;
esac

# --статический (--static): статическая линковка исполняемого файла.
# С --аллокатор=libc (libc.a есть на любой системе со статической линковкой).
"$BIN" --статический --аллокатор=libc флаги_сборки.конда >"$TMP/статич.log" 2>&1 || {
    cat "$TMP/статич.log" >&2; fail "--статический --аллокатор=libc должно компилироваться"; }
grep -q -- "-static " "$TMP/статич.log" || {
    cat "$TMP/статич.log" >&2; fail "--статический должен передавать -static компилятору"; }
grep -q -- "libjemalloc" "$TMP/статич.log" && {
    cat "$TMP/статич.log" >&2; fail "--аллокатор=libc со --статический не должен линковать jemalloc"; }
ldd вывод/флаги_сборки.elf 2>&1 | grep -qi "not a dynamic\|не является динамическим" || {
    ldd вывод/флаги_сборки.elf >&2; fail "--статический должен давать статический бинарник"; }
[ -f вывод/флаги_сборки.elf ] || fail "--статический должен создать .elf"
assert_eq "1" "$(./вывод/флаги_сборки.elf)" "--статический бинарник (libc) работает"

# --статический + --библиотека — ошибка.
"$BIN" --статический --библиотека флаги_либа.конда >"$TMP/стбб.log" 2>&1 && {
    cat "$TMP/стбб.log" >&2; fail "--статический --библиотека должно быть ошибкой"; }
grep -q "несовместим" "$TMP/стбб.log" || {
    cat "$TMP/стбб.log" >&2; fail "ошибка --статический --библиотека должна быть понятной"; }

# ── размер_обьекта(тип) — sizeof(type) в C ──────────────────────────────
cat > размер_об.конда <<'KONDA'
#содержит <stdio.h>

структура Пара
{
    целое32 а
    целое64 б
}

целое32 точка_входа(срез<символ*> аргументы)
{
    printf("%d %d %d %d %d\n",
           размер_обьекта(целое32),
           размер_обьекта(вещественное64),
           размер_обьекта(целое32*),
           размер_обьекта(Пара),
           размер_обьекта(символ**))
    вернуть 0
}
KONDA
"$BIN" размер_об.конда >"$TMP/рзоб.log" 2>&1 || {
    cat "$TMP/рзоб.log" >&2; fail "размер_обьекта должно транспилироваться"; }
assert_eq "4 8 8 16 8" "$(./вывод/размер_об.elf)" "размер_обьекта: sizeof примитивов, структуры и указателей"

# ─── Цветные диагностики: строка-источник + каретка; цвет только в TTY ──────
cat > диаг_сниппет.конда <<'KONDA'
#содержит <stdio.h>

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> д = выделить(3)
    д[10] = 1
    вернуть 0
}
KONDA

"$BIN" диаг_сниппет.конда >"$TMP/диаг.log" 2>&1 && fail "выход за границы среза должен быть ошибкой"
# Диагностика показывает строку-источник и каретку под колонкой.
grep -q "д\[10\] = 1" "$TMP/диаг.log" || {
    cat "$TMP/диаг.log" >&2; fail "диагностика должна показывать строку-источник"; }
grep -q "\^" "$TMP/диаг.log" || {
    cat "$TMP/диаг.log" >&2; fail "диагностика должна показывать каретку под колонкой"; }
# Прежний текстовый заголовок сохранён (совместимость и грепаемость).
grep -q "Ошибка транспиляции" "$TMP/диаг.log" || {
    cat "$TMP/диаг.log" >&2; fail "заголовок «Ошибка транспиляции» должен сохраняться"; }
# Перенаправление (не TTY) → без ANSI-кодов (чистый текст).
if grep -q $'\x1b' "$TMP/диаг.log"; then
    cat -v "$TMP/диаг.log" >&2; fail "без терминала цветовых ANSI-кодов быть не должно"
fi

# ─── Рекурсия: защита стека, гарантированный TCO, предупреждение ─────────────

# (1) Защита стека: НЕхвостовая бесконечная рекурсия переполняет стек. Без
# обработчика это был бы сырой SIGSEGV (и, при большом кадре, порча памяти);
# с ним — детерминированная чистая паника с бэктрейсом и SIGABRT. Аппаратная
# guard-страница ловит переполнение → нулевая цена на горячем пути.
cat > стек_переполнение.конда <<'KONDA'
#содержит <stdio.h>

целое32 бездна(целое32 н)
{
    вернуть бездна(н + 1) + 1
}

целое32 точка_входа(срез<символ*> аргументы)
{
    printf("старт\n")
    вернуть бездна(1)
}
KONDA
"$BIN" стек_переполнение.конда >"$TMP/стек_переполнение.log" 2>&1 || {
    cat "$TMP/стек_переполнение.log" >&2; fail "стек_переполнение должно транспилироваться"; }
# Обработчик ставится конструктором у любого исполняемого файла.
grep -q "_конда_защита_стека" вывод/стек_переполнение.c || {
    cat вывод/стек_переполнение.c >&2; fail "исполняемый файл должен нести защиту стека"; }
./вывод/стек_переполнение.elf >/dev/null 2>"$TMP/стек_переполнение.run" && rc=0 || rc=$?
grep -q "переполнение стека" "$TMP/стек_переполнение.run" || {
    cat "$TMP/стек_переполнение.run" >&2
    fail "переполнение стека должно давать понятную панику, а не сырой segfault"; }
# Чистый abort (SIGABRT=134) через конда_прервать, НЕ сырой SIGSEGV (139).
assert_eq "134" "$rc" "переполнение стека → SIGABRT (чистая паника), не segfault"

# (2) Гарантированный TCO: хвостовая само-рекурсия помечается КОНДА_ХВОСТ и
# компилятором обязана стать переходом. 10 млн уровней в ОТЛАДКЕ (-O0) без TCO
# гарантированно переполнили бы стек; завершение доказывает, что TCO работает.
cat > хвостовой_tco.конда <<'KONDA'
#содержит <stdio.h>

целое32 обратный(целое32 н)
{
    если (н == 0) { вернуть 0 }
    вернуть обратный(н - 1)
}

целое32 точка_входа(срез<символ*> аргументы)
{
    printf("%d\n", обратный(10000000))
    вернуть 0
}
KONDA
"$BIN" хвостовой_tco.конда >"$TMP/хвостовой_tco.log" 2>&1 || {
    cat "$TMP/хвостовой_tco.log" >&2; fail "хвостовой_tco должно транспилироваться"; }
grep -q "КОНДА_ХВОСТ return обратный" вывод/хвостовой_tco.c || {
    cat вывод/хвостовой_tco.c >&2; fail "хвостовой само-вызов должен нести КОНДА_ХВОСТ"; }
# Компилятор гарантированно с musttail (gcc ≥ 15 / clang — проверено в начале
# run.sh), поэтому КОНДА_ХВОСТ раскрывается в реальный musttail → 10 млн уровней
# в -O0 обязаны завершиться без переполнения стека.
assert_eq "0" "$(./вывод/хвостовой_tco.elf)" "10 млн уровней хвостовой рекурсии не переполняют стек (TCO)"

# НЕхвостовой само-вызов (умножение после вызова) НЕ должен получать КОНДА_ХВОСТ.
cat > нехвостовой_нет_tco.конда <<'KONDA'
#содержит <stdio.h>

целое32 факт(целое32 н)
{
    если (н <= 1) { вернуть 1 }
    вернуть н * факт(н - 1)
}

целое32 точка_входа(срез<символ*> аргументы)
{
    printf("%d\n", факт(5))
    вернуть 0
}
KONDA
"$BIN" нехвостовой_нет_tco.конда >"$TMP/нехвостовой_нет_tco.log" 2>&1 || {
    cat "$TMP/нехвостовой_нет_tco.log" >&2; fail "нехвостовой_нет_tco должно транспилироваться"; }
# Грепаем именно ПРИМЕНЕНИЕ «КОНДА_ХВОСТ return», а не определение макроса
# (оно есть в прологе всегда).
if grep -q "КОНДА_ХВОСТ return" вывод/нехвостовой_нет_tco.c; then
    cat вывод/нехвостовой_нет_tco.c >&2
    fail "нехвостовой само-вызов НЕ должен помечаться КОНДА_ХВОСТ"
fi
assert_eq "120" "$(./вывод/нехвостовой_нет_tco.elf)" "нехвостовая рекурсия по-прежнему работает"

# (3) Предупреждение о нехвостовой рекурсии — только по флагу
# «--предупреждать-рекурсию». По умолчанию МОЛЧИТ (иначе шумело бы на всей
# легитимной рекурсии). Хвостовую пригодную рекурсию НЕ помечает (её спасает TCO).
cat > рекурсия_предупр.конда <<'KONDA'
#содержит <stdio.h>

целое32 плохая(целое32 н)
{
    если (н <= 1) { вернуть 1 }
    вернуть н * плохая(н - 1)
}

целое32 хорошая(целое32 н, целое32 акк)
{
    если (н == 0) { вернуть акк }
    вернуть хорошая(н - 1, акк + н)
}

целое32 нечёт(целое32 н)
{
    если (н == 0) { вернуть 0 }
    вернуть чёт(н - 1)
}
целое32 чёт(целое32 н)
{
    если (н == 0) { вернуть 1 }
    вернуть нечёт(н - 1)
}

целое32 точка_входа(срез<символ*> аргументы)
{
    printf("%d %d %d\n", плохая(5), хорошая(3, 0), чёт(4))
    вернуть 0
}
KONDA
# Без флага — ни одного предупреждения о рекурсии.
"$BIN" --только-си рекурсия_предупр.конда >"$TMP/рек_без.log" 2>&1 || {
    cat "$TMP/рек_без.log" >&2; fail "рекурсия_предупр должно транспилироваться"; }
# Грепаем текст предупреждения, а не «рекурс» (оно есть и в имени файла).
if grep -qE "хвостовой|взаимной рекурсии" "$TMP/рек_без.log"; then
    cat "$TMP/рек_без.log" >&2; fail "без флага предупреждений о рекурсии быть не должно"
fi
# С флагом — предупреждение о «плохая» (нехвостовая) и о взаимной «чёт»/«нечёт»,
# но НЕ о «хорошая» (хвостовая пригодная — её спасает TCO).
"$BIN" --только-си --предупреждать-рекурсию рекурсия_предупр.конда \
    >"$TMP/рек_флаг.log" 2>&1 || {
    cat "$TMP/рек_флаг.log" >&2; fail "рекурсия_предупр c флагом должно транспилироваться"; }
grep -q "«плохая».*не является (полностью) хвостовой" "$TMP/рек_флаг.log" || {
    cat "$TMP/рек_флаг.log" >&2; fail "нехвостовая прямая рекурсия должна предупреждаться"; }
grep -q "«нечёт».*взаимной рекурсии" "$TMP/рек_флаг.log" || {
    cat "$TMP/рек_флаг.log" >&2; fail "взаимная рекурсия должна предупреждаться"; }
grep -q "«чёт».*взаимной рекурсии" "$TMP/рек_флаг.log" || {
    cat "$TMP/рек_флаг.log" >&2; fail "взаимная рекурсия должна предупреждаться (обе функции)"; }
if grep -q "«хорошая»" "$TMP/рек_флаг.log"; then
    cat "$TMP/рек_флаг.log" >&2; fail "хвостовая пригодная рекурсия НЕ должна предупреждаться"
fi

# ─── Кастомный аллокатор: «аллокатор Имя {…}» + «Ящик<T> в Имя» ──────────────
# Пер-тип аллокатор (v1: Ящик<T>). Пул — во внешней памяти (инвариант №4 цел):
# выделить/освободить — обычные функции (здесь libc malloc/free через «внешняя»,
# самодостаточно). Кодоген роутит выделение и autofree через них.
cat > аллокатор_ящик.конда <<'KONDA'
#содержит <stdio.h>
#содержит <stdlib.h>

внешняя целое8* malloc(целое64 байт)
внешняя ничего   free(целое8* п)

аллокатор Куча {
    выделить = malloc
    освободить = free
}

структура Узелок {
    целое32 знач
}

целое32 точка_входа(срез<символ*> аргументы)
{
    Ящик<Узелок> в Куча у = выделить()
    у.знач = 99
    printf("%d\n", у.знач)
    вернуть 0
}
KONDA
"$BIN" аллокатор_ящик.конда >"$TMP/аллокатор_ящик.log" 2>&1 || {
    cat "$TMP/аллокатор_ящик.log" >&2; fail "аллокатор_ящик должно транспилироваться"; }
# Выделение — через кастомную функцию с приведением к T*, зануление memset
# (паритет с calloc), autofree — через кастомный освободитель, а не free().
grep -q "(Узелок\*)malloc(sizeof(Узелок))" вывод/аллокатор_ящик.c || {
    cat вывод/аллокатор_ящик.c >&2; fail "выделение должно идти через кастомный аллокатор"; }
grep -q "memset(у, 0, sizeof(Узелок))" вывод/аллокатор_ящик.c || {
    cat вывод/аллокатор_ящик.c >&2; fail "кастомный alloc должен зануляться (паритет с calloc)"; }
grep -q "free((void\*)у)" вывод/аллокатор_ящик.c || {
    cat вывод/аллокатор_ящик.c >&2; fail "autofree должно звать освободитель аллокатора"; }
assert_eq "99" "$(./вывод/аллокатор_ящик.elf)" "Ящик<T> с кастомным аллокатором работает"

# Move в пределах одного аллокатора: источник перемещён → освобождение РОВНО
# один раз (не double-free, autofree получателя зовёт освободитель).
cat > аллокатор_move.конда <<'KONDA'
#содержит <stdio.h>
#содержит <stdlib.h>
внешняя целое8* malloc(целое64 байт)
внешняя ничего   free(целое8* п)
аллокатор Куча { выделить = malloc  освободить = free }
структура Точка { целое32 х }
целое32 точка_входа(срез<символ*> аргументы)
{
    Ящик<Точка> в Куча х = выделить()
    х.х = 42
    Ящик<Точка> в Куча у = х
    printf("%d\n", у.х)
    вернуть 0
}
KONDA
"$BIN" аллокатор_move.конда >"$TMP/аллокатор_move.log" 2>&1 || {
    cat "$TMP/аллокатор_move.log" >&2; fail "аллокатор_move должно транспилироваться"; }
assert_eq "1" "$(grep -c 'free((void\*)' вывод/аллокатор_move.c)" \
    "move: освобождение ровно один раз (источник перемещён)"
assert_eq "42" "$(./вывод/аллокатор_move.elf)" "move Ящик<T> между тем же аллокатором работает"

