# ─── Кастомный аллокатор для срезов: «срез<T> в Имя» ─────────────────────────
# Выделение/клон — через сгенерированные помощники «_срезвыд_<Имя>»/«_срезклон_
# <Имя>» (guard переполнения + зануление = паритет с calloc), autofree — через
# освободитель. Проверка границ среза СОХРАНЯЕТСЯ (безопасность важнее аллокатора).
cat > аллокатор_срез.конда <<'KONDA'
#содержит <stdio.h>
#содержит <stdlib.h>
внешняя целое8* malloc(целое64 байт)
внешняя ничего   free(целое8* п)
аллокатор Куча { выделить = malloc  освободить = free }

целое32 точка_входа(срез<символ*> аргументы)
{
    срез<целое32> в Куча с = выделить(5)
    для целое32 к = 0; к < 5; к = к + 1 { с[к] = к * к }
    целое32 сумма = 0
    для_каждого э из с { сумма = сумма + э }
    срез<целое32> в Куча копия = клон(с)
    printf("%d %d %d\n", длина(с), сумма, копия[3])
    вернуть 0
}
KONDA
"$BIN" аллокатор_срез.конда >"$TMP/алл_срез.log" 2>&1 || {
    cat "$TMP/алл_срез.log" >&2; fail "аллокатор_срез должно транспилироваться"; }
grep -q "_срезвыд_Куча(5, sizeof(int32_t))" вывод/аллокатор_срез.c || {
    cat вывод/аллокатор_срез.c >&2; fail "выделение среза должно идти через помощник аллокатора"; }
grep -q "_срезклон_Куча(" вывод/аллокатор_срез.c || {
    cat вывод/аллокатор_срез.c >&2; fail "клон среза должен идти через помощник аллокатора"; }
grep -q "free((void\*)с.данные)" вывод/аллокатор_срез.c || {
    cat вывод/аллокатор_срез.c >&2; fail "autofree среза должно звать освободитель аллокатора"; }
# 0+1+4+9+16 = 30; копия[3] = 9
assert_eq "5 30 9" "$(./вывод/аллокатор_срез.elf)" "срез<T> с кастомным аллокатором: выделение/доступ/foreach/клон"

