# ─── stdlib/файл: безопасный API файлов (RAII, sum-типы ошибок, шим) ────────
# Проверяем end-to-end: пример «пример_файл.конда» открывает /proc/self/cmdline
# ЧЕРЕЗ stdlib/файл (без единого небезопасно в пользовательском коде), читает
# в срез (границы!), печатает и авто-закрывается через [удалить] на выходе из
# ветки выбора. Транспилятор берёт заголовок шима через -I (каталог исходника).
"$ROOT/Собранное/ТранспиляторКонда" \
    "$ROOT/stdlib/файл.конда" "$ROOT/stdlib/пример_файл.конда" \
    --вывод="$TMP/stdlib_out" >"$TMP/stdlib.log" 2>&1 || {
        cat "$TMP/stdlib.log" >&2; fail "stdlib/пример_файл должно транспилироваться и линковаться"; }
[ -x "$TMP/stdlib_out/файл.elf" ] || fail "stdlib: исполняемый файл не создан"
"$TMP/stdlib_out/файл.elf" >"$TMP/stdlib.out" 2>&1 || fail "stdlib/пример_файл должно успешно запускаться"
# Печатает «прочитано N байт: <cmdline с пробелами вместо NUL>».
grep -q "прочитано " "$TMP/stdlib.out" || {
    cat "$TMP/stdlib.out" >&2; fail "stdlib: ожидался вывод «прочитано N байт»"; }
# Кодоген должен эмитить close-хук (autofree через _файл_закрыть в конце
# ветки Открыт) — то есть RAII-деструктор Файл там ДЕЙСТВИТЕЛЬНО зовётся.
grep -q "_файл_закрыть" "$TMP/stdlib_out/файл.c" || {
    cat "$TMP/stdlib_out/файл.c" >&2; fail "stdlib: RAII-деструктор Файла должен эмититься"; }

# ─── Обобщённые sum-типы: «перечисление Результат<T, E> {…}» (§33) ──────────
# Мономорфизация перечислений — параллельна структурам: шаблон + ссылка на тип
# → специализация с манглированным именем. Конструкторы вариантов (Успех/Провал)
# — обычные вызовы sum-конструкторов над специализированным типом.
cat > обобщ_сум_базовый.конда <<'KONDA'
#содержит <stdio.h>

перечисление Результат<T, E> {
    Успех(T значение)
    Провал(E код)
}

Результат<целое32, целое32> сделать(целое32 х)
{
    если (х > 0) { вернуть Успех(х * 2) }
    вернуть Провал(42)
}

целое32 точка_входа(срез<символ*> аргументы)
{
    Результат<целое32, целое32> р = сделать(7)
    выбор р {
        Успех(зн) { printf("успех %d\n", зн) }
        Провал(код) { printf("провал %d\n", код) }
    }
    вернуть 0
}
KONDA
"$BIN" обобщ_сум_базовый.конда >"$TMP/обобщ_сум.log" 2>&1 || {
    cat "$TMP/обобщ_сум.log" >&2; fail "обобщённый sum-тип базового вида должен транспилироваться"; }
grep -q "Результат_целое32_целое32" вывод/обобщ_сум_базовый.c || {
    cat вывод/обобщ_сум_базовый.c >&2; fail "мономорфизация должна дать имя Результат_целое32_целое32"; }
assert_eq "успех 14" "$(./вывод/обобщ_сум_базовый.elf)" "обобщённый Результат: ветка Успех"

# Ветка Провал — тот же тип, отрицательный аргумент.
cat > обобщ_сум_провал.конда <<'KONDA'
#содержит <stdio.h>
перечисление Р<T, E> {
    А(T v)
    Б(E c)
}
Р<целое32, целое32> f(целое32 x) {
    если (x > 0) { вернуть А(x) }
    вернуть Б(-x)
}
целое32 точка_входа(срез<символ*> аргументы)
{
    выбор f(-3) {
        А(v) { printf("A %d\n", v) }
        Б(c) { printf("B %d\n", c) }
    }
    вернуть 0
}
KONDA
"$BIN" обобщ_сум_провал.конда >"$TMP/обобщ_сум_провал.log" 2>&1 || {
    cat "$TMP/обобщ_сум_провал.log" >&2; fail "обобщённый sum-тип с веткой Б должен транспилироваться"; }
assert_eq "B 3" "$(./вывод/обобщ_сум_провал.elf)" "обобщённый sum-тип: ветка Б"

# Негатив (v1): две специализации того же шаблона запрещены, т.к. конструкторы
# вариантов без вывода типа-контекста становятся неоднозначными.
cat > обобщ_сум_дубль.конда <<'KONDA'
перечисление П<T> {
    Знач(T x)
    Пусто
}
целое32 точка_входа(срез<символ*> аргументы)
{
    П<целое32> a = Знач(5)
    П<целое64> b = Знач(7)
    вернуть 0
}
KONDA
"$BIN" --только-си обобщ_сум_дубль.конда >"$TMP/обобщ_сум_дубль.log" 2>&1 \
    && fail "две специализации того же sum-шаблона (v1) должны быть ошибкой"
grep -q "уже специализировано" "$TMP/обобщ_сум_дубль.log" || {
    cat "$TMP/обобщ_сум_дубль.log" >&2; fail "ошибка про повторную специализацию sum-шаблона должна быть понятной"; }

# Негатив: неверное число тип-аргументов → понятная ошибка.
cat > обобщ_сум_арность.конда <<'KONDA'
перечисление Р<T, E> {
    А(T v)
    Б(E c)
}
целое32 точка_входа(срез<символ*> аргументы)
{
    Р<целое32> р = А(5)
    вернуть 0
}
KONDA
"$BIN" --только-си обобщ_сум_арность.конда >"$TMP/обобщ_сум_арность.log" 2>&1 \
    && fail "неверное число тип-аргументов sum-шаблона должно быть ошибкой"
grep -q "ожидает.*тип-аргумент" "$TMP/обобщ_сум_арность.log" || {
    cat "$TMP/обобщ_сум_арность.log" >&2; fail "ошибка про арность sum-шаблона должна быть понятной"; }

# ─── Автоподключение стандартной библиотеки (stdlib) ────────────────────────
# Пользователь НЕ пишет «#содержит "файл.h"»: транспилятор сам находит stdlib
# рядом с бинарником (или через KONDA_STDLIB), внедряет её функции/типы,
# синтетически включает «файл.h» и автолинкует «файл.so».

# Позитив: программа без «#содержит» использует Файл/открыть_чтение/прочитать.
cat > стд_авто.конда <<'KONDA'
#содержит <stdio.h>
целое32 точка_входа(срез<символ*> аргументы)
{
    выбор открыть_чтение("/proc/self/cmdline") {
        Успех(фд64) {
            Файл ф = { фд = как<целое32>(фд64) }
            срез<символ> буфер = выделить(16)
            выбор прочитать(ф, буфер) {
                Успех(н) { printf("прочитано %d байт\n", как<целое32>(н)) }
                Провал(код) { printf("ошибка чтения: %d\n", код) }
            }
        }
        Провал(код) { printf("не открылось: %d\n", код) }
    }
    вернуть 0
}
KONDA
KONDA_STDLIB="$ROOT/stdlib/вывод" "$BIN" стд_авто.конда >"$TMP/стд_авто.log" 2>&1 || {
    cat "$TMP/стд_авто.log" >&2; fail "автоподключение stdlib: программа должна собираться"; }
grep -q "файл.h" вывод/стд_авто.c || fail "автоподключение stdlib: синтетический #include файл.h должен быть в .c"
./вывод/стд_авто.elf >"$TMP/стд_авто_вывод.txt" 2>&1 || fail "автоподключение stdlib: .elf должен работать"
grep -qE "прочитано [1-9][0-9]* байт" "$TMP/стд_авто_вывод.txt" || {
    cat "$TMP/стд_авто_вывод.txt" >&2; fail "автоподключение stdlib: прочитано ненулевое число байт"; }

# Негатив: --без-стандартной-библиотеки — stdlib не видна (типы/функции
# не подключаются, транспиляция ломается).
"$BIN" --без-стандартной-библиотеки --только-си стд_авто.конда >"$TMP/стд_нет.log" 2>&1 \
    && fail "--без-стандартной-библиотеки: stdlib должна быть не видна"
grep -q "Ошибка транспиляции" "$TMP/стд_нет.log" || {
    cat "$TMP/стд_нет.log" >&2; fail "--без-стандартной-библиотеки: должна быть ошибка транспиляции"; }

# Коллизия имён: своя функция «записать» → stdlib не подключается (понятное
# предупреждение), программа со своим кодом работает.
cat > стд_коллизия.конда <<'KONDA'
#содержит <stdio.h>
структура Калиб {
    срез<целое32> tests
    целое32 current_test
}
ничего записать(изменяемый Калиб Калиб, целое32 x) {
    Калиб.tests[Калиб.current_test] = x
    Калиб.current_test = Калиб.current_test + 1
}
целое32 точка_входа(срез<символ*> аргументы) {
    Калиб Калиб = { tests = выделить(3), current_test = 0 }
    записать(Калиб, 42)
    записать(Калиб, 7)
    printf("%d %d %d\n", Калиб.tests[0], Калиб.tests[1], Калиб.current_test)
    вернуть 0
}
KONDA
KONDA_STDLIB="$ROOT/stdlib/вывод" "$BIN" стд_коллизия.конда >"$TMP/стд_коллизия.log" 2>&1 || {
    cat "$TMP/стд_коллизия.log" >&2; fail "коллизия со stdlib: программа должна собираться"; }
grep -q "не подключена" "$TMP/стд_коллизия.log" || {
    cat "$TMP/стд_коллизия.log" >&2; fail "коллизия со stdlib: должно быть предупреждение об отключении"; }
assert_eq "42 7 2" "$(./вывод/стд_коллизия.elf)" "коллизия со stdlib: своя функция побеждает"

# Коллизия вариантов: свой sum-тип с вариантами Успех/Провал → stdlib не
# подключена (пересечение имён конструкторов), своё перечисление работает.
cat > стд_варианты.конда <<'KONDA'
#содержит <stdio.h>
перечисление Результат<T, E> {
    Успех(T значение)
    Провал(E код)
}
Результат<целое32, целое32> сделать(целое32 х) {
    если (х > 0) { вернуть Успех(х * 2) }
    вернуть Провал(42)
}
целое32 точка_входа(срез<символ*> аргументы) {
    Результат<целое32, целое32> р = сделать(7)
    выбор р {
        Успех(зн) { printf("успех %d\n", зн) }
        Провал(код) { printf("провал %d\n", код) }
    }
    вернуть 0
}
KONDA
KONDA_STDLIB="$ROOT/stdlib/вывод" "$BIN" стд_варианты.конда >"$TMP/стд_варианты.log" 2>&1 || {
    cat "$TMP/стд_варианты.log" >&2; fail "коллизия вариантов со stdlib: программа должна собираться"; }
grep -q "не подключена" "$TMP/стд_варианты.log" || {
    cat "$TMP/стд_варианты.log" >&2; fail "коллизия вариантов: должно быть предупреждение об отключении"; }
assert_eq "успех 14" "$(./вывод/стд_варианты.elf)" "свои варианты Успех/Провал работают без stdlib"


# ─── Лимиты компилятора: явная ошибка вместо тихой мискомпиляции ─────────────
# Раньше переполнение внутренних таблиц (функции, символы…) и усечение слишком
# длинного имени происходили молча — сущность/имя терялись, дальше вылезала
# непонятная ошибка или битый C. Теперь это диагностика с позицией.

# (1) Слишком длинное имя переменной (>127 байт) — ошибка, а не тихое усечение
# (иначе два имени с общим префиксом слились бы в одно). 130 ASCII-байт.
LONGNAME=$(printf 'a%.0s' $(seq 1 130))
cat > имя_длинное.конда <<KONDA
целое32 точка_входа(срез<символ*> аргументы) {
    целое32 $LONGNAME = 5
    вернуть 0
}
KONDA
if "$BIN" --только-си имя_длинное.конда >"$TMP/имя_длинное.log" 2>&1; then
    fail "слишком длинное имя должно быть ошибкой транспиляции"
fi
grep -q "имя слишком длинное" "$TMP/имя_длинное.log" || {
    cat "$TMP/имя_длинное.log" >&2; fail "должна быть понятная ошибка про длину имени"; }

# (2) Переполнение таблицы функций (>128) — явная ошибка «слишком много», а не
# молчаливо пропущенная функция. Генерируем 200 функций.
{
    i=0
    while [ "$i" -lt 200 ]; do
        printf 'целое32 ф%d(){ вернуть %d }\n' "$i" "$i"
        i=$((i + 1))
    done
    printf 'целое32 точка_входа(срез<символ*> аргументы){ вернуть 0 }\n'
} > много_функций.конда
if "$BIN" --только-си много_функций.конда >"$TMP/много_функций.log" 2>&1; then
    fail "переполнение таблицы функций должно быть ошибкой"
fi
grep -q "слишком много" "$TMP/много_функций.log" || {
    cat "$TMP/много_функций.log" >&2; fail "переполнение функций: нужна понятная ошибка «слишком много»"; }
